window.__D("text/or-torah/c004",{"p":[[400080350,"רפח\n\n<b>רני</b> ושמחי בת ציון כי הנני בא ושכנתי בתוכך. ב\"ת נקרא הגוף. כי ב\"ת נקרא עי\"ר, ועי\"ר נקרא הגוף. וזהו הבנים ירשו והבנות יזונו. כי ב\"ן נקרא הנשמה, שהיא מבקשת מהש\"י להאכיל להגוף. וזהו הבן ירש עלמא דכסופא, והבנות, פי' הגופים, יזונו, (שהם) [שיש] להם לאכול. וזהו שמחי ב\"ת, פי' הגוף של הצדיק, הנני בא ושכנתי בתוכך, בתוך הגוף.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ה, ב. לקו\"א לז, א.</b>\n<i>רני ושמחי בת ציון גו'</i> – זכריה ב, יד.<i> ב\"ת נקרא עי\"ר</i> – (ב\"ת בחי' מלכות, זח\"ג יא, ב. שם רנו, ב. וכן עי\"ר) זח\"ג סח, ב. זו\"ח רות פ, ד.<i> ועי\"ר נקרא הגוף</i> – נדרים לב, ב. זח\"ג סח, ב. זו\"ח רות פ, ד.<i> הבנים ירשו כו'</i> – ב\"ב קלט, ב.<i> ב\"ן נקרא הנשמה</i> – זח\"א קפא, ב.<i> עלמא דכסופא</i> – ראה זח\"ב קטו, א. זח\"ג קנט, א."]]],[400080351,"רפט\n\n<b>אודך</b> ה' כי אנפת בי. על דרך משל אדם אוהב את בנו הקטן ומכה אותו מחמת אהבה, והתינוק מתחיל לבכות. וכשמתחיל לבכות, אביו מצטער ומנשק אותו. וזהו כי אנפת <span data-k=\"sm\">[בי]</span>, כי האף הוא בי, שאני סובר שזה מחמת האף, ובאמת אתה עושה מחמת האהבה, ישוב (ידך, כשידך) [אפך, כשאפך], פי' מכתך כביכול חוזרת אצלך כנזכר, ותנחמני, אתה מנחם אותי.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ה, ב. לקו\"א לז, ב.</b>\n<i>אודך ה' גו' ישב אפך ותנחמני</i> – ישעיה יב, א.\n----- הערות וציונים -----\n<i>ובאמת אתה עושה מחמת האהבה</i> – להעיר ממשלי ג, יב. וראה פי' הרה\"מ עה\"פ והפכתי אבלם גו' (ירמיה לא, יג) באוה\"ת-נ\"ך להצ\"צ, ח\"א ע' שג ושם ח\"ב ע' א'קכג. ולהעיר מלעיל סי' שו ד\"ה וזהו."]]],[400080352,"רצ\n\n<b>או</b> יאמר על דרך ג' דברים ניתנו ע\"י יסורים עוה\"ב (כי) [כו']. כשהאדם הוצרך להעלות דבר צריך לילך למקום ההוא, אפילו אם המקום הוא מלוכלך. כמשל מלך שנפל חותמו למקום רקק, צריך לילך לרקק להעלות את החותם, כדי שיאהב אותו המלך. וזה ידוע כי הוא יתברך עובד את עצמו. וזהו (תשיב ידך) [ישב אפך], אתה בעצמך תשיב (ידך) [אפך], פי' מדותיך, <span data-k=\"sm\">[ותנחמני]</span> ואתה מנחם אותי שאני אהוב אליך על ידי זה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ה, ב. לקו\"א לז, ב.</b>\n<i>ג' דברים ניתנו כו'</i> – ברכות ה, א. (<i>תשיב ידך</i> – ע\"פ תהלים עד, יא).<i> [ישב אפך ותנחמני</i> – ישעיה יב, א].\n----- הערות וציונים -----\n<i>כשהאדם הוצרך כו' כמשל מלך כו'</i> – להעיר ממשל הבעש\"ט והרה\"מ המובא בקדושת לוי שה\"ש ד\"ה לריח שמניך (והובא בכש\"ט בהערות לסי' קנד עיי\"ש). ורג\"כ לקמן סי תנא.\n<i>כי הוא יתברך עובד את עצמו</i> – עיין סי' שפז-א."]]],[400080353,"רצא\n\n<b>(כי)</b> [אם] רחץ ה' את צואת בנות ציון, כמשל שרוחצין את ארמון המלך כדי לשרות המלך בו, והוא ירחץ את צואת, פי' עם הצואה. כמשל בן הקטן, אף על פי שמלכלך את עצמו בטיט ובצואה, יש לאביו תענוג מפני שהוא בנו. כך השי\"ת משתעשע את עצמו בילד שעשועים, אפילו עבירות נעשו להם כזכיות כשעושים תשובה, ויש לו תענוג אפילו מהעבירות כשעושים תשובה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ו, א. לקו\"א לח, ב.</b>\n<i>אם רחץ ה' גו'</i> – ישעיה ד, ד.<i> עבירות נעשו להם כזכיות</i> – יומא פו, ב.\n----- הערות וציונים -----\n<i>אפילו עבירות כו' ויש לו תענוג כו'</i> – ראה סי' רפז."]]],[400080354,"רצב\n\n<b>ישמע</b> מהיכלו קולי. הי\"כל נקרא הדיבור. וצריך להתפלל רק בשביל שמביא את הדיבור לו ית'. וכשמתפלל כך, מניחין אותו כל המשמרות. על דרך משל, חותם המלך שנושא אותו בן כפר, אף על פי שאינו הגון לבוא לפני המלך מניחין אותו כל המשמרות, שהמלך יש לו געגועין על החותם, וממהרין אותו אל המלך כדי שיהיה אל המלך תענוג מהר. כך הקב\"ה מגעגע אחר הדיבור. וזהו ישמע מה\"יכלו קולי, דהיינו מחמת הדיבור.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ו, ב. לקו\"א לח, ב.</b>\n<i>ישמע מהיכלו קולי</i> – תהלים יח, ז. ש\"ב כב, ז.\n----- הערות וציונים -----\n<i>היכל נקרא הדיבור</i> – ראה סי' נ ד\"ה וזהו פי'. רג\"כ ריש סי' תו.\n<i>על דרך משל חותם המלך כו'</i> – ראה סי' רלד-ב."]]],[400080355,"רצג\n\n<b>ושבתי</b> (וראיתי) [ואראה] דמעת העשוקים ואין להם מנחם. ואיתא בזוהר פ' משפטים מהיכן שב מתרמוד <span data-k=\"sm\">[שפרח על נשר]</span>. פי' תרמוד נקרא אהבה רעה <span data-k=\"sm\">[כגון מחשבה זרה וכיוצא בו] [נ\"א: כגון ניאוף]</span>. וזהו ויבן את (תרמוד) [תדמר] במדבר, שהבין את המחשבה זרה הבאה לו בעת שהוא מדבר דיבורים של תפילות כדי להעלות אותם <span data-k=\"sm\">[נ\"א: להעלותה]</span>. וזהו נקרא עשוקים, שהם עשוקים בקליפות. ופרח על נשר, ר\"ל על מדת רחמים, שריחם את עצמו על המדריגות התחתונים. וזהו פי' מפני מה עיניהם של תרמודים תרוטות, ר\"ל השכל שבמדריגות התחתונות טרוטות, <span data-k=\"sm\">[לא צח]</span>, אלא מפני שדרים בין החולות, <span data-k=\"sm\">[פי']</span> על דרך אשר שמתי חול גבול לים. על דרך זכו נמשלו לכוכבים, פי' כוכב נקרא כשהש\"י שוכן בצירוף כ\"ו, גי' הוי\"ה, על כ\"ב אותיות הדיבור, לא זכו נמשלו לחו\"ל, לשון חולין.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ח, א. לקו\"א מ, ב.</b>\n<i>ושבתי ואראה גו'</i> – קהלת ד, א.<i> ואיתא בזוהר פ' משפטים</i> – זח\"ב קיב, ב.<i> ויבן את תדמד במדבר</i> – דה\"ב ח, ד. ראה מ\"א ט, יז-יח.<i> ויבן . . שהבין</i> – זח\"ג רלג רע\"ב. ראה נדה מה, ב.<i> ופרח על נשר</i> – קה\"ר ב, כה. זח\"ב קיב סע\"ב. זח\"ג רלג סע\"א.<i> נשר . . מדת רחמים</i> – זח\"ב פ, ב. זח\"ג רלג, א. שם רחצ, ב. ראה תנחומא עקב ב. מדרש שמואל ז, ב.<i> מפני מה עיניהם כו'</i> – שבת לא, א.<i> אשר שמתי חול גו'</i> – ירמיה ה, כב.<i> כוכב . . כ\"ו כ\"ב</i> – לקו\"ת להאריז\"ל בלק ד\"ה דרך.<i> זכו כו' לא זכו כו'</i> – ראה אגדת בראשית פל\"ט.\n----- הערות וציונים -----\n<i>תרמוד נקרא אהבה רעה</i> – להעיר מיבמות טז, ב.\n<i>כוכב נקרא כ\"ו גי' הוי\"ה על כ\"ב אותיות הדיבור</i> – ראה של\"ה פ' ויצא ד\"ה והנה בדרך הראשון (רצב, א)."]]],[400080356,"רצד\n\n<b>או</b> יחזיק במעוזי יעשה שלום לי שלום יעשה לי. על[ftnref_1_א] דרך מאת ה' היתה זאת. כי כשאדם עושה רצונו יתברך, נולד התפארות גדול למעלה להמעשים שאנו עושים, והוא יתברך מתאוה שנהיה דבוקים בו יתברך. והוא בבחי' אב ואנו בבחינת בן, ברא כרעא דאבוהי. והוא כביכול בבחינת אביון, וזהו פי' ואם מך הוא מערכך, שאם הוא יתברך <span data-k=\"sm\">[כביכול]</span> מך, <span data-k=\"sm\">[שהוא]</span> בבחינת דין, הוא מערכך, מכוחך זה בא. וזהו מאת ה' היתה זאת, כביכול ממנו (יתברך) נעשה זאת, <span data-k=\"sm\">[בחינת]</span> נוקבא, שהוא מדת (הרחמנות) [הדין]. נמצא שהוא יתברך בא במדות, אע\"פ שהוא למעלה מן המדות. אבל כשאדם עושה הטוב בעיני הבורא <span data-k=\"sm\">[נ\"א: רצונו של מקום]</span>, כביכול עושה מדת שלום לו יתברך, ומדת שלום הוא מדת התקשרות <span data-k=\"sm\">[שמקשר ומייחד כל המדות]</span>. וזהו או יחזיק במעוזי, על דרך ישראל מפרנסים לאביהם שבשמים, כביכול מחזיקים אותו יתברך. וזהו יעשה שלום לי, שמקשר[ftnref_2_ב] יתברך כביכול, ואח\"כ שלום יעשה לי, שמביא אל מדריגות התחתונות ההתקשרות (שעשיתי לו) <span data-k=\"sm\">[נ\"א: אשר עשה לי]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' פב (צג). אוה\"א ח, ב.</b>\n<i>או יחזיק במעוזי גו</i> – ישעיה כז, ה.<i> מאת ה' היתה זאת</i> – תהלים קיח, כג.<i> ברא כרעא דאבוהי</i> – עירובין ע, ב.<i> ואם מך הוא מערכך</i> – בחקותי כז, ח.<i> נעשה זאת נוקבא</i> – ראה זח\"ג קמה, ב.<i> שהוא מדת הדין</i> – זח\"ג קמה סע\"ב. שם קיג, ב.<i> ומדת שלום הוא מדת התקשרות</i> – (שלום בחי' יסוד, זח\"ג קטו, ב. תקו\"ז תס\"ט קטז, ב, שהוא מדת התקשרות) זח\"א לא סע\"א. שם פט, א.<i> ישראל מפרנסים כו'</i> – זח\"ג ז, ב.\n----- שולי הגליון -----\n[ftn_1_א]) <i>נו\"א במדל\"י:</i> פי' דהנה כתיב מאת ה' היתה זאת. דכשישראל עושים רצונו של מקום יש תענוג גדול להשי\"ת ב\"ה, כי הוא ית' מתאוה שנהיה דבוקים בו, כמו בחינת אב אל הבן, ברא כרעא דאבוה. וזהו אם מך הוא <i>(כבפנים)</i>.\n[ftn_2_ב]) <i>ברור שכאן חסר, וע\"פ המבואר לעיל נראה שצ\"ל</i> שמקשר מדותיו יתברך כביכול.\n----- הערות וציונים -----\n<i>כשאדם עושה רצונו ית' כו'</i> – ראה סי' רמ.\n<i>שאם הוא ית' מך כו' מכחך זה בא</i> – להעיר מספרי האזינו פיס' שיט. איכה רבה א, לג.\n<i>ישראל מפרנסין כו' כביכול מחזיקים כו'</i> – ראה סי' שח. וראה ריש סי' ס ובהערות שם.\n<i>מחזיקים אותו</i> – ראה סי' כד סד\"ה אך עכ\"ז."]]],[400080357,"רצה\n\n<b>אמר</b> עצל ארי בחוץ וגו'. על דרך לא יניח ידו תחת טיבורו. כי יש ב' מיני מדריגות. הא' כמו רשב\"י ע\"ה, דהוי אדכי שוקי דטבריא, שהיה מעלה כל המדריגות התחתונות להקדוש ברוך הוא. כמשל בן המלך ששלח אותו אביו בכפרים לבקש אוצרו שנאבד <span data-k=\"sm\">[מאתו]</span>. ממילא הבן מדבר עם כל בני הכפרים הבזוים, אע\"פ שאין זה כבודו, מכל מקום עושה זאת כדי שאולי ידבר הבן כפר מן האוצר. כן צריך להניח עצמו למדריגות התחתונות כדי שיעלה אותם, את האהבה והיראה רעה ושאר כל המדות כידוע. אך עלותם הוא כך, <i>דרבי ישראל בעש\"ט זללה\"ה</i> אמר צוהר תעשה לתיבה, שיהיו האותיות מצהירים <span data-k=\"sm\">[נ\"א: שיהא מצהיר את האותיות]</span>, תחתים שנים <span data-k=\"sm\">[ושלישים]</span> תעשה (את התיבה), כמ\"ש <i>בסי' א'</i>[ftnref_1_ג] וע\"ש[ftnref_2_ד].",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ט, ב. לקו\"א מא, א.</b>\n<i>אמר עצל גו'</i> – משלי כב, יג.<i> לא יניח ידו כו'</i> – נדה יג, ב.<i> רשב\"י ע\"ה דהוי אדכי כו'</i> – זח\"ב לז, רע\"א. זח\"ג עב, ב. ירושלמי שביעית פ\"ט סה\"א.<i> צוהר תעשה גו' תחתים גו'</i> – נח ו, טז.<i> כמ\"ש בסי'</i> – לעיל סי' יח.\n----- שולי הגליון -----\n[ftn_1_ג]) <i>ראה מש\"כ בהערות בסוף הספר</i>.\n[ftn_2_ד]) <i>חסר ביאור מדריגה הב', ואולי הוא המבואר לעיל סי' מד בפירוש הפסוק אמר עצל</i>.\n----- הערות וציונים -----\n<i>כמו רשב\"י ע\"ה כו'</i> – ראה סי' שכה.\n<i>כמשל בן המלך כו' כן צריך להניח עצמו כו'</i> – ראה סי' שו. וראה כש\"ט סי' שנו, וכן שם סוף סי' קלו.\n<i>דריבעש\"ט זללה\"ה אמר כו'</i> – לעיל סי' יח. וראה סי' יז.\n<i>כמ\"ש בסי' א'</i> – ראה בהערות לסי' יז."]]],[400080358,"רצו\n\n<b>טבעו</b> בארץ שעריה. <span data-k=\"sm\">[פי']</span> כי בדבר <span data-k=\"sm\">[שהוא במדריגות]</span> אי\"ן לא שייך שבירה, <span data-k=\"sm\">[כי השבירה שייך בדבר שהוא מדה או כלי]</span>. נמצא אם האדם מחזיק את עצמו לאי\"ן, מחזיק[ftnref_1_ה] דביקות בהקב\"ה. כמשל[ftnref_2_ו] המלך עמד בבית ושר גדול אשר (המלוכה) [במלוכה] שלו עמד אצל הפתח כעני, ובעל הבית לא חלק כבוד להשר, והשר לא הקפיד <span data-k=\"sm\">[על זה]</span>. ואם היה בפני עצמו בבית, היה חולק לו כבוד והיה בוש לפניו, אך <span data-k=\"sm\">[עתה]</span> נתבטל ממציאות המדות הגדלות שלו והיראה מלפניו, במדות של המלך. כי בהתדבקות האדם עם המלך מלכי המלכים הקב\"ה יתבטלו מדות שלו, שלא יש יראה ואהבה רק אותו יתברך ולא יפאר רק אותו <span data-k=\"sm\">[נ\"א: שלא יאהב רק אותו. ונ\"א: ויאהב ויפאר רק הבורא ית']</span>.\n<b>וזהו</b>[ftnref_3_ז] למה הצדיקים דומין לפני השכינה כנר לפני האבוקה. הצדיק נקרא מי שמקושר תמיד בהקב\"ה. נמצא כשעומד תמיד לפניו אינו מחשב עצמו לכלום, כמשל נר לפני האבוקה, וכשאינו מקושר אזי יש לו תאוות <span data-k=\"sm\">[אחרות]</span>.\n<b>[וזהו </b><span data-k=\"sm\">טבעו בארץ, ר\"ל שמחזיק את עצמו לארץ, לאי\"ן בעיניו, שעריה, ר\"ל המדות. וכשאין לו שום מדה אזי אין שייך אצלו שום שבירה. וזהו מכל חטאתיכם, [מה שנחסר לכם, לפני ה' תטהרו, כשיבוא הדבר]</span>[ftnref_4_ח].",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' פ (צא). אוה\"א יב, א. לקו\"א מז, א.</b>\n<i>טבעו בארץ שעריה</i> – איכה ב, ט.<i> למה הצדיקים דומין כו'</i> – פסחים ח, א.<i> שעריה ר\"ל המדות</i> – ראה זח\"א קג, ב. ובהג' החיד\"א שם.\n----- שולי הגליון -----\n[ftn_1_ה]) <i>נ\"א במדל\"י:</i> מחמת דביקותו בבורא ית', כמו השר אפילו הוא גדול שבכל שרי המלוכה, בעמדו לפני המלך הוא בעיניו כמו קטן, ואינו רוצה שיעשה לו שום כבוד מחמת גדלו ושררותו כמו שעושים לו כשהוא בביתו בפני עצמו, כי אז עושים לו כבוד ובושים ויראים ממנו. אמנם כשהוא לפני המלך, הוא וכל מדותיו נתבטלו מפני יראתו ובשתו מפני המלך. וזהו טבעו <i>(כבפנים)</i>.\n[ftn_2_ו]) <i>נוסח המשל באוה\"א:</i> המלך עמד בבית גדול אשר במלוכה שלו, ושר א' עמד אצל הפתח כעני, ובעל הבית לא חלק לו כבוד להשר<i> (כבפנים)</i>.\n[ftn_3_ז]) וזהו . . תאוות <i>ליכא במדל\"י</i>.\n[ftn_4_ח]) <i>הסיפא ע\"פ מדל\"י ולקו\"א, וקאי על מה שהובא במקבילות לפני ביאור הפסוק טבעו בארץ שעריה (והובא לקמן סוף סי' תא), וז\"ל שם:</i> מכל חטאתיכם לפני ה' תטהרו. פי' דהנה כתיב נודע בשערים בעלה ואיתא בזוהר כל חד לפום שיעורא דיליה. על ידי המדות אהבה ויראה הקב\"ה מקשר את עצמו כביכול עם האדם. טבעו בארץ שעריה <i>(כבפנים)</i>. וזהו למה כו' <i>אינו במדל\"י</i>.\n----- הערות וציונים -----\n<i>כי בדבר שהוא במדריגות אי\"ן לא שייך שבירה</i> – ראה סי' שע. ורג\"כ סי' צה ד\"ה ולבאר; סי' צז ד\"ה וזהו; וסי' שכט; שבמ\"ה אין בו שבירה.\n<i>כמשל המלך כו'</i> – ראה סי' סז ד\"ה ונבין. רג\"כ סי' שפב. השוה המשל במדל\"י סי' כו (ל).\n<i>חטאתיכם מה שנחסר לכם</i> – ע\"פ מ\"א א, כא. ראה פרש\"י לויצא לא, לח."]]],[400080359,"רצז\n\n<b>ועינינו</b> מאירות כשמש וכירח. השמש אינו מקבל משום דבר, והירח היא מקבלת האור מן השמש. אך בזה יש לה יותר תענוג, כי השמש אין לה תענוג, כי תענוג תמידי אינו תענוג, אבל הירח יש לה תענוג בהגיע לה אור. והתענוג הוא מדריגה גדולה, אז תתענג על ה'. כמשל עני אחד שמשתכר מאה זהובים יש לו יותר תענוג מהמלך. והאדם צריך לאחוז בשניהם, כמו משה רבינו ע\"ה שהיה במדריגת שמש, שלא היה מקבל, והיה אוחז את עצמו שהוא מקבל. וכשבא לאדם התלהבות צריך לאחוז במדת היראה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א יב, ב.</b>\n<i>ועינינו מאירות כו'</i> – סידור, נשמת כל חי.<i> והירח היא מקבלת כו'</i> – זח\"א רלו סע\"ב. שם רמט, ב.<i> אז תתענג על ה'</i> – ישעיה נח, יד.<i> משה כו' במדריגת שמש</i> – ב\"ב עה, א. זח\"ג רס סע\"ב.\n----- הערות וציונים -----\nהובא באוה\"ת להצ\"צ, ר\"ה, ע' א'ת בתוס' הגהות.\n<i>תענוג תמידי אינו תענוג</i> – ראה סי' לה ובהערות שם.\n<i>וכשבא לאדם התלהבות צריך כו'</i> – ראה סוף סי' קכד ובהערות שם."]]],[400080360,"רחצ\n\n<b>דרך</b> הנשר בשמים. פי' כשאחד מדבר דברי שכל יש בזה תענוג. והתענוג הוא דבר גדול, אז תתענג על ה', רק שנופל בקליפות והניצוצות רוצים להדבק בשכל. וזהו דרך הנשר, נשר לשון נפילה, בשמים, <span data-k=\"sm\">[פי']</span> בשכל.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א יב, ב.</b>\n<i>דרך הנשר בשמים</i> – משלי ל, יט.<i> אז תתענג על ה'</i> – ישעיה נח, יד.<i> נשר לשון נפילה</i> – סוכה י, א.\n----- הערות וציונים -----\n<i>בשמים פי' בשכל</i> – ראה ריש סי' שצד שמי\"ם . . ר\"ל שם מים והשכל נקרא מי\"ם."]]],[400080361,"רצט\n\n<b>כי</b> לא מחשבותי מחשבותיכם. על דרך עינה בדרך כחי. כי יש אדם שהולך תמיד בדרך ה', ואינו מגיע אצלו ית' מפני שעושה מעשים טובים בלא דחילו ורחימו. אבל כשעושה בדחילו ורחימו אז הוא נעשה אחדות עמו ית', ע\"ד הדבק במדותיו, ואז הוא כביכול משנה רצונו ית', <span data-k=\"sm\">[כפי]</span> שמה שהוא רוצה הקב\"ה רוצה. וזהו צדיק מושל ביראת אלקים. כמו חתיכת שאור שמחמיץ כל העיסה, כך הוא משנה רצונו, כי הוא אחדות עמו ית'. וזהו כי לא מחשבותי מחשבותיכם, מפני מה לא מחשבותי מחשבותיכם, כי לא דרכיכם דרכי, כי אין אתם מתנהגים בדרכי.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א יב, ב.</b>\n<i>כי לא מחשבותי מחשבותיכם</i> – ישעיה נה, ח.<i> ענה בדרך כחי</i> – תהלים קב, כד.<i> ואינו מגיע אצלו ית' כו'</i> – ראה תקו\"ז ת\"י כה, ב.<i> הדבק במדותיו</i> – ראה שבת קלג, ב. סוטה יד, א.<i> צדיק מושל גו'</i> – ש\"ב כג, ג. ראה מו\"ק טז, ב. זח\"א מה, ב.\n----- הערות וציונים -----\n<i>שמה שהוא רוצה כו'</i> – ראה סי' ס ד\"ה והנה נמשיל, ובהערות שם."]]],[400080362,"ש\n\n<b>שרפים</b> עומדים ממעל לו, פי' הם העובדים את הש\"י בהתלהבות. ממה הם עומדים במדריגה הזאת, מכח שהם חושבים תמיד ממעל. הכל מה שנעשה ממעל לו, ר\"ל כמו שמתנהג בו כך מתנהג למעלה, על דרך דע מה למעלה ממך. אם נתעורר הצדיק באהבה, נתעורר כביכול הקב\"ה באהבה, ואם ביראה וכו'[ftnref_1_ט].\n<b>וזהו</b> אפתח בכינור חידתי. שהקב\"ה שמים ושמי השמים לא יכלכלוהו, וצמצם שכינתו בתוך האדם. ואמרו חכמי המחקר שכשעושים כינור קטן במשקל שוה עם הגדול, כשמנגנים בקטן נשמע (קולו בגדול) [קול הגדול]. והש\"י ברא את האדם בצלמו, והוי ככנור קטן, ומעורר בכל מעשיו את השכינה. ולפיכך צריך שיעשה הכל לשם שמים כדי שלא לעורר אותה לבטלה ח\"ו.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א יג, א. לקו\"א מא, א.</b>\n<i>שרפים עומדים ממעל לו</i> – ישעיה ו, ב.<i> כמו שמתנהג בו כך כו'</i> – ראה זח\"א רי, ב. שם רמד, א. זח\"ב קפד, ב.<i> דע מה למעלה ממך</i> – אבות פ\"ב מ\"א.<i> אפתח בכינור חידתי</i> – תהלים מט, ה.<i> שמים ושמי השמים לא יכלכלוהו</i> – ע\"פ מ\"א ח, כז.<i> והש\"י ברא את האדם בצלמו</i> – בראשית א, כז.\n----- שולי הגליון -----\n[ftn_1_ט]) <i>ראה לקמן סי' שמ נ\"א לסימן זה.</i>\n----- הערות וציונים -----\nלקמן בסי' שמ באו\"א.\n<i>שרפים . . הם העובדים הש\"י בהתלהבות</i> – ראה סוף סי' נב.\n<i>כמו שמתנהג בו כך מתנהג למעלה כו'</i> – עיין סי' קלד ובהערות שם.\n<i>דע מה למעלה ממך</i> – ראה סי' תפ. כש\"ט סוף סי' קמה."]]],[400080363,"שא\n\n<b>שש</b> כנפים לאחד, בשש מדריגות עובדים להקב\"ה. בשתים יכסה פניו, כי עיקר עבודת ה' באהבה ויראה. ואיתא שהקב\"ה ברא את האדם כדי שיעשה מלבוש לעולם העליון. ויש שעובדים להקב\"ה באהבה ויראה פנימיות, שמבינים שהקב\"ה רב ושליט ואוהב אותנו <span data-k=\"sm\">[נ\"א: ואוהבים אותו]</span>, והוא (נעשה) [עושה] מלבוש לפנימיות של הכל. וזהו בשתים, באהבה ויראה, יכסה, עושה כיסוי, פניו, פי' הפנימיות.\n<b>ויש</b> שעובדים מצד אמונה. כי מאמינים שהקב\"ה מלא כל הארץ כבודו, עושה <span data-k=\"sm\">[נ\"א: עושים]</span> מלבוש לעולם האמונה. וזהו <span data-k=\"sm\">[ובשתים]</span> יכסה רגליו, כי רגלים נקראים אמונה, כמו על רגל עומדים והרגל מעמיד כל הגוף כך האמונה מעמיד כל העבודה, שאם לא יאמין בהקב\"ה עבודתו לאו עבודה[ftnref_1_י]. ולכן נקראת האמונה מזה הטעם רגלים כי היא חיזוק כל דבר. וזהו בשתים יכסה, עושה כיסוי, רגליו, לעולם האמונה, ובשתים יעופף, בזה האהבה והיראה מעופף ממדריגה למדריגה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א יג, א. לקו\"א מא, א.</b>\n<i>שש כנפים לאחד גו'</i> – ישעיה ו, ב.<i> בשתים יכסה פניו</i> – שם.<i> רב ושליט</i> – זח\"א יא, ב.<i> מלא כל הארץ כבודו</i> – ישעיה ו, ג.\n----- שולי הגליון -----\n[ftn_1_י]) <i>בלקו\"א נ\"א:</i> וזה בשתים יכסה רגליו, דאמונה נקראת רגלים, כמו שהגוף עמידתו על ידי הרגלים כך האמונה עמוד כל העבודה, שאם לא יאמין בהקב\"ה וב\"ש אין עבודתו כלום.\n----- הערות וציונים -----\nהשוה סי' שמא לנו\"א.\n<i>מאמינים שהקב\"ה מלא כל הארץ כבודו</i> – ראה כש\"ט סי' לט ד\"ה וביאר. שם ריש סי' פ.\n<i>רגלים נקראים אמונה</i> – ראה לקמן סי' שב ושמא. לקו\"י סי' סד פט, קנח. וראה אוה\"א כד רע\"א נו\"ה נקרא רגלים ע\"ש כל מי שאין לו אמונה בידוע כו'. ושם לב, א (בכתבי קודש כח, ג) ד\"ה בחי' דדים. וראה כתבי קודש כח, ב.\n<i>והרגל מעמיד כל הגוף כך האמונה כו'</i> – ראה תניא, אגה\"ק ריש סי' א. וראה לקו\"י סי' סד, פט, קמח."]]],[400080364,"שב\n\n<b>או</b> יאמר שרפים (עומדים), כמו הנחשים השרפים, עומדים, ברשעתם, ממעל לו. דשאנו אומרים אדני שפתי תפתח, פי' השכינה, עולם הדיבור, שאם אינה מתלבשת בפה אין הפה יכול לדבר. אבל הרשע אומר[ftnref_1_יא] שפתינו אתנו <span data-k=\"sm\">[ומי אדון לנו]</span>, שהוא בעצמו מדבר, ונרגן מפריד אלוף, שמפריד את עצמו מאלופו של עולם, דיבורו מעולם הדיבור ומחשבתו (הוא) מעולם המחשבה. וזהו ממעל, עולמות העליונים, אומר <span data-k=\"sm\">[שהוא]</span> לו, שהוא בעצמו. <span data-k=\"sm\">[בשתים יכסה כו']</span>, על דרך ביום (ברוא) [עשות] ה' אלהי\"ם ארץ ושמים, פי' אפילו בארציות יש אהבה ויראה, שזהו הוי\"ה אלהי\"ם. כי אפילו הגנב יש לו אהבה ויראה, אהבת ממון ויראה שלא יהיה לו מה לאכול, לכך עושה עבירה זאת, וכן בכל הדברים כידוע. וזה בשתים, באהבה ויראה של קליפות, יכסה פניו, שאין לו <span data-k=\"sm\">[בושה מ-]</span>מלך מלכי המלכים הקב\"ה, ויכסה רגליו, שאין לו אמונה, שאילו היה מאמין בהקב\"ה, שהקב\"ה לפניו, לא היה חוטא, ובשתים יעופף, לקליפות רחמנא ליצלן.\n<b>או</b> יאמר <span data-k=\"sm\">[על הצדיק, ממע\"ל, כל העולמות שלמעלה, לו, לא נבראו אלא בשבילו, על דרך כל העולם כולו לא נברא אלא לצוות לזה. או יאמר]</span> ממעל לו, על דרך אז תתענג על ה', התענוג הוא כביכול למעלה מהש\"י.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א יג, א. לקו\"א מא, ב.</b>\n<i>שרפים עומדים ממעל לו</i> – ישעיה ו, ב.<i> הנחשים השרפים</i> – חוקת כא, ו.<i> אד' שפתי תפתח</i> – ריש העמידה (תהלים נא, יז).<i> שפתינו אתנו</i> – תהלים יב, ה.<i> ונרגן מפריד אלוף</i> – משלי טז, כח.<i> שמפריד את עצמו מאלופו של עולם</i> – ראה זח\"ג טז רע\"ב. שם לא, א.<i> ביום עשות ה\"א ארץ ושמים</i> – בראשית ב, ד.<i> אהבה . . הוי\"ה</i> – ראה זח\"ג רסז, ב.<i> ויראה . . אלהי\"ם</i> – ראה זח\"ב צו, א. תקו\"ז תנ\"ו פט, ב.<i> אז תתענג על ה'</i> – ישעיה נח, יד.<i> כל העולם כולו כו'</i> – ברכות ו, ב.<i> כביכול למעלה מהש\"י</i> – זח\"ב פג רע\"א. זח\"ג צד, ב.\n----- שולי הגליון -----\n[ftn_1_יא]) <i>בלקו\"א:</i> אבל הרשעים אומרים גם כן אדני שפתי תפתח, ובאמת אינם סוברים כן, שאומרים שפתינו<i> (כבפנים)</i>.\n----- הערות וציונים -----\n<i>דשאנו אומרים אד' שפתי תפתח כו'</i> – ראה ריש סי' תו. וראה סי' שיד ובהערות שם.\n<i>רגליו . . אמונה</i> – ראה לעיל סי' שא ובהערות שם."]]],[400080365,"שג\n\n<b>אנכי</b> תרגלתי לאפרים קחם על זרועותיו <span data-k=\"sm\">[גו' כי רפאתים]</span>. כי מכל דבר צריך לעבוד את הקב\"ה. אם יש להאדם תענוג מדבר <span data-k=\"sm\">[מה]</span>, יזכור באהבת הקב\"ה, ואם ביראה יזכור ביראת הבורא יתברך. ועבודת ה' היא תמידית, ולכן נתן לו הקב\"ה שתהיה הדבר הזה אצלו <span data-k=\"sm\">[תמיד]</span>. למשל אדם שיש לו בן ואוהב אותו, ומזכיר מחמת זה את עצמו באהבת הבורא יתברך, נותן לו הקב\"ה את הבן תמיד כדי שיזכור באהבתו יתברך <span data-k=\"sm\">[תמיד]</span>. וזהו אנכי תרגלתי, פי' גידלתי אותו, קחם על זרועותיו, זרועות נקראים אהבה ויראה, ולא ידעו כי רפאתים, אך צריך שלא יתן דעתו בשביל רפואות, שלא יהיה לאדם פניה שבשביל כך יקח אהבה ויראה מהילד <span data-k=\"sm\">[נ\"א: שבשביל כך אוהב אותו ית']</span> כדי שיגדל התינוק. וזהו ולא ידעו כי רפאתים, צריך שלא יתן דעתו בשביל רפואות.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א יג, ב. לקו\"א מב, א.</b>\n<i>ואנכי תרגלתי לאפרים גו'</i> – הושע יא, ג.<i> זרועות נקראים אהבה ויראה</i> – תקו\"ז ת\"י כה, ב.<i> ולא ידעו כי רפאתים</i> – הושע שם.\n----- הערות וציונים -----\n<i>מכל דבר צריך לעבוד את הקב\"ה כו'</i> – ראה סי' קטו ובהערות שם. סי' תל. צוה\"ר סי' כב ובהערות שם. כש\"ט סי' לח <i>-א-ב</i>, וסי' קפ."]]],[400080366,"דש\n\n<b>כי</b> חלה וגם ילדה ציון את בניה. פי' עד\"מ, <span data-k=\"sm\">[יש]</span> אדם שנושא אשה בשביל אהבת נשים, וכשיש לו ממנה בנים יש לו תענוג מהבנים. ואחד שנושא אשה בשביל אהבת בנים, וזהו נקרא אהבה מוקדמת <span data-k=\"sm\">[נ\"א: הקודמת]</span>, שמצייר את מחשבתו בתמונת בנו <span data-k=\"sm\">[נ\"א: שמצייר במחשבתו תמונת בנו]</span> שיוולד לו, שכך יהיה תמונתו ומצייר איך יהיה מדבר דברי שכל. נמצא מצייר מחשבתו בתמונה. אעפ\"י שאין לו תמונה <span data-k=\"sm\">[נ\"א: נמצא מחשבתו בתמונה, אע\"פ שאין לה תמונה]</span>. נמצא מחמת ההשתתפות מחשבתו עם בנו שיוולד לאחר זמן נולד בתוכו אהבה. כך היה להשי\"ת תענוג מתחילה מישראל ילד שעשועים, (שמשתעשעים) [שישתעשע] בכל דור ודור מחמת מעשיהם ודיבורם. וזהו פי' ישראל עלה במחשבה, ומחמת זה רצה הקב\"ה לברוא את העולמות. נמצא נתהוו כל העולמות ברצון, וז\"ש בעץ החיים כשעלה ברצונו יתברך, ואח\"כ נשתלשל למטה במדות בז' ימים. וזהו ויברא אלהים את האדם בצלמ\"ו, באותו צלם שנתעלמה כביכול המחשבה בצלם שלנו, והוא באמת אין לו תמונה כמשל הנזכר. והטבעית הוא כשהוא יתברך מתעלם כביכול בהצלם בשבילי שאני[ftnref_1_יב]. וזהו פי' אסורה נא ואראה את המראה הגדול הזה. שיש פנים הנראים ופנים שאינם נראים. פנים הנראים נקראים אהבה ויראה, שזה יש ג\"כ בהאדם. ופנים שאינם נראים הוא מה שמחייב <span data-k=\"sm\">[את]</span> האהבה ויראה. ומפנים הנראים יכול לבוא לפנים שאינם נראים <span data-k=\"sm\">[וזהו את המראה, פנים הנראים, הגדול הזה, פנים שאינם נראים]</span>. וזהו פירוש ילדה ציון את בניה. ציו\"ן נקרא הצלם, וכשיש לנו תענוג, גם אל הצל\"ם הוא תענוג כביכול, וזה נקרא הולדה. וזהו ציון ילדה א\"ת בניה, פי' עם בניה. וזהו פי' מ\"ש במקום אחר <span data-k=\"sm\">[אברהם אברהם]</span>, שבהמחשבה, שצמצם כביכול המחשבה א\"ע בדמות אברהם.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א יד, א. לקו\"א מד, ב.</b>\n<i>כי חלה גם ילדה ציון גו'</i> – ישעיה סו, ח.<i> ילד שעשועים</i> – ירמיה לא, יט.<i> ישראל עלה במחשבה</i> – זח\"א כד, א. בר\"ר א, ד.<i> וז\"ש בעץ החיים כשעלה כו'</i> – ע\"ח ש\"א ענף ב. שם שער הכללים רפ\"א. ראה זח\"א קלד סע\"א.<i> ויברא אלקים גו'</i> – בראשית א, כז.<i> אסורה נא ואראה גו'</i> – שמות ג, ג.<i> שיש פנים הנראים ופנים שאינם נראים</i> – ראה זו\"ח יתרו לג סע\"ב. ספר הליקוטים פ' כי תשא ד\"ה ויעבור ה' (בד\"ה עוד פי' אחר).<i> מ\"ש במ\"א</i> – ראה לעיל סי' כג.<i> אברהם אברהם</i> – וירא כב, יא.\n----- שולי הגליון -----\n[ftn_1_יב]) <i>הלשון כאן צ\"ע. בלקו\"א:</i> והטבע היא כשהשי\"ת מתעלם בהצלם בשבילו שאינו נכנס בהצלם כביכול, וכשהולך למעלה יבוא להאיך שאין דמות וצלם.\n----- הערות וציונים -----\n<i>כך היה להקב\"ה תענוג מתחילה כו'</i> – ראה סי' א ובהערות שם.\n<i>וז\"ש בעץ חיים כו'</i> – ראה סי' ט.\n<i>וזהו ויברא כו' באותו צלם כו'</i> – ראה סי' ו ובהערות שם.\n<i>גם אל הצל\"ם הוא תענוג כ\"י כו'</i> – ראה סי' רכג."]]],[400080367,"שה\n\n<b>אנכי</b> תרגלתי לאפרים קחם על זרועותיו. על דרך משל האב שאין בנו הקטן יכול לעלות על ידיו מגביה אותו, ואח\"כ כשמחזיק אותו משעשע <span data-k=\"sm\">[את עצמו]</span> בזקן (שלו) [של אביו]. כך האדם אינו יכול להתדבק בהשי\"ת, והשי\"ת (מניח) [מכניס] אהבה ויראה ללבו של אדם שהם נקראים ידים. <span data-k=\"sm\">[שהם דמיון ידים, ש-]</span> כמו שביד נותן אדם לחבירו, כך על ידי מה שעובדים את הקב\"ה באהבה ויראה, כי בלא דחילו ורחימו לא פרחת לעילא, מביאים שפע בכל העולמות. וכשמתדבק האדם ע\"י מדותיו אהבה ויראה להשי\"ת, אזי הוא כביכול ממשיך מדותיו יתברך רחום וחנון וגו'. והמדות נקראים דיקנא ושערות, <span data-k=\"sm\">[לשון שיעורין]</span>, כי הם מותרות. כי העצמות אינו צריך לשום מדה, כי הוא א\"ל אף בלא המדות <span data-k=\"sm\">[נ\"א: כי הוא אין סוף]</span> רק העולמות צריכין שיהיה <span data-k=\"sm\">[הוא ית']</span> רחום וחנון וכו', שאלמלא כן לא היה להם קיום. לפיכך הם רק לצורך העולמות, שהם לא עצמיות, לכן נקראים מותרות.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' ס (עג). אוה\"א יז, ב.</b>\n<i>ואנכי תרגלתי לאפרים גו'</i> – הושע יא, ג.<i> אהבה ויראה . . נקראים ידים</i> – תקו\"ז ת\"י כה, ב.<i> בלא דו\"ר לא פרחת לעילא</i> – שם.<i> רחום וחנון גו'</i> – כי תשא לד, ו.<i> והמדות נקראים כו'</i> – זח\"ג קלא, ב.<i> ושערות לשון שיעורין</i> – ראה תקו\"ז ת\"ע קכב, א.<i> כי הם מותרות</i> – זח\"ג קלד, א. מבו\"ש ש\"ה ח\"א ספי\"ג.\n----- הערות וציונים -----\n<i>וכשמתדבק האדם כו' אזי הוא כו'</i> – ראה סי' קסז ד\"ה מה, וסי' רצד. וראה סי' רלב-א.\n<i>והמדות נקראים דיקנא ושערות כו'</i> – ראה סי' קיח סד\"ה או רמוז.\n<i>העצמות אינו צריך לשום מדה</i> – ראה סי' רצד.\n<i>רק העולמות צריכין שיהיה כו'</i> – ראה סי' קיח סד\"ה או רמוז."]]],[400080368,"שו\n\n<b>הן</b> גור יגור אפס מאותי. פי' כי פעמים יש אדם שדבוק בצדיק, כשרואה שעובד <span data-k=\"sm\">[נ\"א: שהוא רואה שהצדיק עובד]</span> את הקב\"ה שיושב ולומד, ולפעמים שהצדיק מדבר דברים בטלים. והוא כמשל בן מלך שהוא הולך בין בני הכפרים לחפש אחר אוצר שיש אצל בן כפר, <span data-k=\"sm\">[הנה היה]</span> צריך להלביש את עצמו כבן כפר כדי שלא יכירו שהוא בן מלך ומגלין לו כל הסודות והיכן הוא האוצר. כך הצדיק מדבר דברים בטלים, והוא מקושר להקב\"ה ומקשר את הדיבורים להקב\"ה. וזהו נקרא גירות, שהולך בשליחות הקב\"ה למצוא שם המדות. למשל אחד אינו יכול להתפלל ומדבר דברי שחוק ומעורר בעצמו אהבה, ואומר <span data-k=\"sm\">[אחר כך]</span> בלבו אם יש לו תענוג מזה שהוא דברי שטות, כמה יש להתענג מהקב\"ה שהוא תענוג לכל התענוגים. ועי\"ז יתפלל באהבה ויראה.\n<b>וזהו</b> הן גור יגור, כשהוא בגירות, דהיינו שמדבר דיבורים בטלים, אפס מאותי, כי יש בני אדם שסוברים שהקב\"ה אינו מלובש בכאן, והוא מחמת הבהירות <span data-k=\"sm\">[עד]</span> מאוד. כמשל[ftnref_1_יג] אור גדול שמכהה הראות ואינו יכול לראות שנתגלה הבהירות עד שאין השכל משיג. ובאמת הקב\"ה הוא בכאן רק התלבשותו אינו נראה, כמו (החורבן) [חרבן הבית] שהיה חסד גדול, כמו שכתב האלשיך זלה\"ה נטה קו ויאבל חיל וחומה, נטה קו על בנין העתיד. פי' שלא היו יכולים לסבול התגלות הבהירות הגדול שיתגלה כשיבוא משיח בב\"א, לפיכך נחרב הבית. וזהו אפס מאותי, שאין מה <span data-k=\"sm\">[נ\"א: שום דבר]</span> בעולם שאין אני <span data-k=\"sm\">[שם]</span>.\n<b>ע\"ד</b>[ftnref_2_יד] הוד והדר לפניו, פי' לפני הקב\"ה, כי עצמותו אין יכולים להשיג.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' סה-סו (עח-עט). אוה\"א יח, א.</b>\n<i>הן גור יגור גו'</i> – ישעיה נד, טו.<i> כמש\"כ האלשיך זלה\"ה כו'</i> – פירוש האלשיך לאיכה ב, ח.<i> נטה קו גו'</i> – איכה ב, ח.<i> הוד והדר לפניו</i> – תהלים צו, ו.\n----- שולי הגליון -----\n[ftn_1_יג]) <i>במדל\"י</i> כמשז\"ל, <i>להעיר מזח\"א רסה, א (ס' הבהיר סי' קס; וראה שם סי' קמז). ויותר נראה שזהו טה\"ד</i>.\n[ftn_2_יד]) ע\"ד <i>ליכא במדל\"י. ולכאורה מש\"כ כאן צ\"ל באנפא נפשיה</i>.\n----- הערות וציונים -----\nראה סי' רצה.\n<i>כך הצדיק כו'</i> – ראה סוף סי' לו ד\"ה ואמרו. סי' קעה ד\"ה וזהו. סי' רמח ד\"ה והנה כשהצדיק. וסי' תנא ותפח. ועיין כש\"ט סי' רמד ושסו ובהערות שם.\n<i>ובאמת הקב\"ה בכאן רק התלבשותו כו'</i> – להעיר מסי' רפט וראה שם בהערות."]]],[400080369,"שז\n\n<b>ושמועה</b> טובה מארץ מרחק. על דרך וישב יעקב בארץ וגו'. דאיתא בזוהר זכי יהבין ליה נפשא זכי יתיר יהבין ליה רוחא וכו'. כי כשנולד האדם אין בו אלא נפש הבהמיות. וכשמנצח את היצה\"ר יהבין ליה נפשא[ftnref_1_טו], פי' כל עולם עשיה הוא ברשותו, וזכי מלשון ניצוח כמו זכיתי שתאמר יציאת מצרים. זכה יתיר יהבין ליה רוחא, פי' כל עולם המלאכים הוא ברשותו, ע\"ד עושה מלאכיו רוחות. זכה יתיר יהבין ליה נשמתא מעולם הכסא, <span data-k=\"sm\">[ר\"ל]</span> הוא במחשבתו <span data-k=\"sm\">[וכונתו]</span> הוא במחשבתו עושה כסא להקדוש ברוך הוא, כשחושב באהבתו <span data-k=\"sm\">[ית']</span> משרה אותו בעולם האהבה, וכן ביראה משרה אותו בעולם היראה. וצריך האדם שלא יפסוק את מחשבתו אפילו רגע אחד מהש\"י, ובזה משרה <span data-k=\"sm\">[את]</span> הקב\"ה בהם. ולכך נכתבו הבארות בתורה, כי השרה הקב\"ה עליהם.\n<b>וזהו</b> וישב יעקב בארץ מגורי אביו. אע\"פ שישב בארציות, מגורי אביו, פי' <span data-k=\"sm\">[לשון]</span> אוגר בקיץ, שהאסיף הקב\"ה על זה. או יאמר מגורי <span data-k=\"sm\">[אביו]</span>, פי' כי כל (עולם ה)מחשבה הוא עולם שלם, והם ניצוצות הקב\"ה <span data-k=\"sm\">[נ\"א: הקדושה]</span>, ואסף אותם אל השורש. וזהו מגורי אביו, פירוש שאסף את אביו כביכול.\n<b>וזהו</b> פירוש עיני ה' אל צדיקים. פי' כמשל בן הקטן שעושה מעשה נערות מביא את השכל של אביו לתוך המעשים האלו, כי מגודל האהבת האב אל בנו מצמצם האב את שכלו ורואה ומתבונן במעשה בנו. כך הצדיקים כביכול עושים להקב\"ה (קדמות השכל) [כדמות שכלם], שהוא יתברך חושב מה שהם חושבים, אם חושבים באהבה מביאים את הקב\"ה בעולם האהבה. והוא יתברך אינו דמות הגוף, כמו השכל שאינו בעל תמונה[ftnref_2_טז]. וזהו פירוש צמצם שכינתו בין ב' בדי ארון, פי' כנפי ריאה השכינה, שהקב\"ה שורה כמו שהוא מחשב, ועי\"ן נקרא השכל, והשכל שלו ביד הצדיקים. אבל איך זוכים למדריגה זו, בחשבו שהוא עפר ואינו יכול לעשות שום מעשה בלי כחו של הקב\"ה. נמצא מה שהוא עושה עושה זאת הקב\"ה, שאם לא היה הוא יתברך לא היה יכול לעשות כלום.\n<b>וזהו</b> ושמועה טובה מארץ, <span data-k=\"sm\">[מארץ]</span> פי' בשביל שהוא חושב שהוא ארץ, מרחק, ר\"ל מרחיק א\"ע מהיצר הרע.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' ב-ג (ב). אוה\"א יח, ב.</b>\n<i>ושמועה טובה מארץ מרחק</i> – משלי כה, כה.<i> וישב יעקב בארץ גו'</i> – וישב לז, א.<i> דאיתא בזוהר כו'</i> – זח\"ב צד, ב. ראה פרדס רמונים של\"א פ\"ג.<i> [ולא] זכיתי שתאמר כו'</i> – ברכות יב, ב ובפי' הר\"ב שם.<i> נפשא . . עשיה . . רוחא . . עולם המלאכים . . נשמתא מעולם הכסא</i> – תקו\"ז תכ\"ב סח סע\"ב. ראה פרדס רמונים שט\"ז פ\"א ושם של\"א פ' ב-ג.<i> עושה מלאכיו רוחות</i> – תהלים קד, ד.<i> אוגר בקיץ</i> – משלי י, ה.<i> עיני ה' אל צדיקים</i> – תהלים לד, טז.<i> צמצם שכינתו כו'</i> – ראה שהש\"ר א, טז. תנחומא ויקהל ז.<i> כנפי ריאה השכינה</i> – ראה תקו\"ז תכ\"א מט, ב.<i> ועי\"ן נקרא השכל</i> – ראה ע\"ח ש\"ד פ\"א. שם ש\"ח פ\"א.\n----- שולי הגליון -----\n[ftn_1_טו]) יהבין ליה נפשא . . זכה יתיר <i>ליכא במדל\"י, אלא</i> יהבין ליה רוחא <i>כדלקמן</i>.\n[ftn_2_טז]) והוא יתברך . . תמונה<i> ליכא במדל\"י, ושם:</i> מביאים את הקב\"ה לעולם האהבה, כמ\"ש בזוהר (תקו\"ז ת\"ו כא, ב) מלך אסור ברהטים (שה\"ש ז, ו) ברהיטי מוחין.\n----- הערות וציונים -----\n<i>כשחושב באהבתו ית' משרה כו'</i> – ראה סי' ש ובהערות שם.\n<i>ולכך נכתבו הבארות בתורה כו'</i> – ראה סי' שכה.\n<i>וזהו וישב יעקב כו'</i> – ראה סי' נא ד\"ה והנה כתיב. רג\"כ סי' מח ד\"ה וזהו וישב.\n<i>כמשל בן הקטן כו'</i> – ראה סי' א ובהערות שם.\n<i>שהוא יתברך חושב כו'</i> – ראה סי' רמח ד\"ה והנה נאמר. וראה סי' ש ובהערות שם."]]],[400080370,"שח\n\n<b>ושמועה</b>[ftnref_1_יז] טובה תדשן עצם. על דרך <span data-k=\"sm\">[שאמרו רז\"ל]</span> ישראל מפרנסין לאביהם שבשמים. כמו אדם ששבע מחמת תענוג, כך הקב\"ה מתענג ממעשיהם של ישראל. תדשן <span data-k=\"sm\">[עצם]</span>, פי' <span data-k=\"sm\">[מדשן ו-]</span> מענג את העצמות של הכל, <span data-k=\"sm\">[והוא הקב\"ה]</span>. וזהו פי' נעריצך, פירוש לשון חוזק, כביכול (אז) [אנו] מחזקים <span data-k=\"sm\">[נ\"א: מחזיקים]</span> אותו יתברך.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סוף סי' ג (סוף סי' ב). אוה\"א יט, א.</b>\n<i>שמועה טובה גו'</i> – משלי טו, ל.<i> ישראל מפרנסין כו'</i> – זח\"ג ז, ב.<i> נעריצך</i> – סידור, נוסח הקדושה.<i> נעריצך . . לשון חוזק</i> – ראה תהלים פט, ח.\n----- שולי הגליון -----\n[ftn_1_יז]) <i>במקבילות אין דרוש זה באנפא נפשיה אלא המשך וסיום סי' שז דלעיל, דשם מתחיל</i> וזהו ושמועה טובה כו'.\n----- הערות וציונים -----\nראה סי' רצד ושם בהערות ד\"ה ישראל."]]],[400080371,"שט\n\n<b>עיר</b> קטנה ואנשים בה מעט. עי\"ר לשון אעיר\"ה שחר. פי', כי הקב\"ה דורש אותנו לשוב אליו. משל למלך שהגלה את בניו. אחד מהם היה חכם, שכל צערו היה רק על אביו שיש לו צער ממה שגלו ממנו, ולא על צערו. ובזה נתעוררו רחמיו על כל הבנים מכח האחד החכם. כן הצדיק מעורר רחמיו יתברך על כל ישראל אמן[ftnref_1_יח].",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י ריש סי' ט (ריש סי' י). אוה\"א כ, א.</b>\n<i>עיר קטנה גו'</i> – קהלת ט, יד.<i> אעיר\"ה שחר</i> – תהלים נז, ט.\n----- שולי הגליון -----\n[ftn_1_יח]) <i>באוה\"א מסתיים הדרוש כאן כמו בפנים. במדל\"י יש המשך (והובא באוה\"א יב סע\"א ד\"ה הצדיק מעורר רחמי הקב\"ה על כל ישראל):</i> וזהו אעירה שחר, ובת קול מכרזת בכל יום שובו בנים שובבים (זח\"ג קכו, א). וזהו הכרוז שבא לכל אחד ואחד התעוררות. ודוד המלך ע\"ה אמר אני מעורר השחר (במ\"ר טו, טז), שחר לשון דרישה, אני מעורר שהקב\"ה ידרוש את ישראל. וזהו עיר <i>[לשון התעוררות]</i> קטנה ואנשים בה מעט, <i>[אנשים נקראים המצות, שכל מצוה היא קומה שלמה, מעט,]</i> שאילו היו עושים מצות היה מצוה גוררת מצוה והיו עובדים את הש\"י. ובא אליה מלך גדול, כמאמר רז\"ל (גיטין לא, ב) רוח דרומית קשה מכולם, דיש פיתוי יצר הרע שמפתה את הבריות באהבה רעה, ניאוף ח\"ו וכיוצא בה.\n<i>באוה\"א מוסיף בהרחבת הדיבור וביאור:</i> ויש ביראה רעה ח\"ו, אבל ע\"י יראה רעה יוכל לקרב עצמו אל הקב\"ה. על דרך עולה הייתי במעלה אדומים (ר\"ה כב, ב), כשהצדוקים שכרו את אחד להטעות הסנהדרין מסתמא חפשו אחר אדם לא טוב. אך כשהזכיר את עצמו ביראה רעה, דהיינו גיהנם, ועי\"ז שב אל ה' ולא הטעה הסנהדרין, דיראה הוא מדת אדום עיין לעיל <i>(באוה\"א א, ב. בלקו\"י טו, ד </i>–<i> סי' קצד; צוה\"ר סי' פז; לקו\"א לג, א)</i> כמ\"ש עשו הוא אדום (וישלח לו, ח). וזהו עולה הייתי, שהיה לי עליה על ידי מעלתו של אדומים כנ\"ל. אבל ע\"י אהבה רעה לא יוכל לשוב אל הקב\"ה, כי אם כשיתן אל לבו היראה. וזו רוח דרומית קשה מכולם, שדרום נקרא אהבה. ומצא בה איש מסכן (קהלת ט, טו), לשון ערי מסכנות, לשון אוצר, שהיצר טוב אינו רוצה לגלות חכמתו לאחרים שיתיהר בה. ומלט הוא את העיר בחכמתו, פי' בחכמת היצר הרע שמה שמביא לו אהבה רעה אומר אם אני אוהב זה כל שכן שיש לי לאהוב את השם יתברך.\n----- הערות וציונים -----\n<i>עיר לשון אעיר\"ה</i> – ראה סי' נ ד\"ה וזהו וימלוך. סי' רכט ד\"ה והמשך. סי' רמח ד\"ה והנה כשהצדיק."]]],[400080372,"שי\n\n<b>עם</b> זו יצרתי לי תהילתי יספרו. <span data-k=\"sm\">[פי']</span> כי לכך יצר את נשמתו של אדם כחומר <span data-k=\"sm\">[נ\"א: למה מסר הקב\"ה נשמתו של אדם בגוף החומרי]</span>, ולא ברא את האדם כאחד המלאכים, בשביל השעשועים שהקב\"ה משתעשע בנשמתן של צדיקים. <span data-k=\"sm\">[ומהו השעשועים]</span>, על דרך משל מלך בשר ודם יש לו ציפור אחת שמדברת, ובשעה שמדברת <span data-k=\"sm\">[המלך משתעשע עמה ושומע ומצמצם שכלו הרמה לשמעה, ו-]</span> יש לו שמחה גדולה <span data-k=\"sm\">[ותענוג]</span> יותר (אבל) [מכל] השכליות שמדברים כל השרים היושבים ראשונה במלכות, מפני שזה הוא חידוש גדול וצמצם עצמו לשמוע אותו בשביל אהבתו. וזהו <span data-k=\"sm\">[פירוש]</span> עם זו יצרתי לי, פי' <span data-k=\"sm\">[מלשון]</span> צרור וחתום, בחומר. לי, כדי לעשות <span data-k=\"sm\">[לי]</span> שעשוע. וכל המלאכים רואים חידוש גדול כזה, ואומרים ה' אדונינו מה אדיר שמך בכל הארץ, ומי כעמך וגו'. וזהו תהילתי יספר\"ו, לשון ספי\"ר, שהדברים מאירים <span data-k=\"sm\">[למרחוק]</span>, אחד מספר לחבירו וחבירו לחבירו. ולכך ישראל מאירים בכל העולמות, שעושין שעשועים גדולים ועושין רצון ושמחה לפניו יתברך להפיס כעסו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י יז, ב (סי' רכ).</b>\n<i>עם זו יצרתי לי גו'</i> – ישעיה מג, כא.<i> צרור וחתום</i> – ב\"מ מג, א.<i> וכל המלאכים כו' ואומרים כו'</i> – זח\"ב קנה, ב. בר\"ר ח, ו.<i> ה' אדונינו גו'</i> – תהלים ח, י. ראה שבת פט, א.<i> ומי כעמכך כישראל גו'</i> – ש\"ב ז, כג.<i> לשון ספיר</i> – תצוה כח, יח. ועוד.\n----- הערות וציונים -----\nעיין סי' שפח. לקו\"י סי' קס (והוא באוה\"א עו סע\"ב) [הובא לקמן בהערות לסי' שפח]. וראה אורח לחיים פ' ויצא רד\"ה א\"י ויחלום: ושמעתי בשם הרה\"ק בוצ\"ק מוהר\"ר דוב בער זללה\"ה דתפארת נקרא גופא שהשי\"ת אינו מתפאר במלאכים ובשרפים שעובדים אותו שהם מוכרחין בעבודה ואין להם יצה\"ר ובחירה, אבל השי\"ת מתפאר באדם שהוא מלובש בגוף ויצה\"ר ויש לו בחירה לנטות איזה דרך שירצה, וכשעובד השי\"ת הוא גורם התפארות, וזהו ישראל אשר בך אתפאר, ועל כן נקרא תפארת גופא מפני שהגוף שהאדם מלובש בו גורם התפארות ודפח\"ח (וכן הובא שם בפ' שמות ד\"ה והנה משה, פ' יתרו ד\"ה ונראה דידוע, פ' תצוה סד\"ה ואפשר לומר, ופ' אמור ד\"ה שבת שבתון).\n<i>יצרתי לי פי' מלשון צרור וחתום</i> – ראה סוף סי' רסב."]]],[400080373,"שיא[ftnref_1_יט]\n\n<b>חכמות</b> בחוץ תרונה. פי' אעפ\"י שהם ב' חכמות, עילאה ותתאה, וזו היא חכמות, אפילו כשהם בחוץ, דהיינו חכמה תתאה, אע\"פ כן תרונה, שחכמה אקרי כ\"ח מ\"ה והוא האי\"ן. והוא היולי של כל העולמות ועליו נאמר בברית מנוחה יושבת בחיק המלך והיא סוכנ\"ת למלך, לשון תענוג. וזה הוא למעלה רי\"ש ולמטה שי\"ר. חכמה נקרא צורכי של כל דבר מה שנצרך לעולם. וזהו תענוגו וחיותו מה שאנו ממשיכין לו יתברך תענוג נקרא חכמה עילאי ומה שאנו ממשיכין תענוג לעולם נקרא חכמה תתאה. וזהו בין תרין צדיקים עלמא יתיב, דהיינו ב' המשכות. המשכה אחת לתענוג עליון, והב' בתענוג הב' חכמה תתאה. וזהו תמונת ב' צדי\"ן, צד\"י פשוטה וצד\"י כפופה. כי כשהצדיק רוצה להתפלל מתחילה משתחוה וכפיף קדם עלמא עילאה ונופל עליו יראה גדולה ואימה ובושה. וזהו השראת שכינה. דהיינו יראה פנימיות חכמה, בגין דאיהו רב ושליט. ונופל עליו כל כך יראה עד שיהיה בטל ממציאות נגד המלך ונכנס לשער אי\"ן שהוא חכמה, יו\"ד, בזה מקשר היו\"ד עם הנו\"ן ונעשה צד\"י כפופה. אך עדיין הוא בחכמה תתאי דהיינו יראה, ועי\"ז מוסיף תענוג להש\"י כביכול. וזהו עצם השעשועים כמו האב שיש לו תענוג כשהבן מבקש להאב והאב נותן לו. וזהו בראשי\"ת יר\"א בוש\"ת. והצדיק כיון שנכנס לשער אי\"ן אז מקשר את עצמו לחכמה עילאי, כיון שהוא עצמו אי\"ן, והאי\"ן אינו מתאוה לשום דבר. וזהו פי' ויקח מאבני המקום. כיון שנכנס לשער אי\"ן ומעלה אל לבו אלמלא כח השי\"ת בו אזי הוא אפס מוחלט, א\"כ הכל הוא כח השי\"ת. והדיבור הוא עולם הדיבור של השי\"ת שבו נברא העולם, ועולם הדיבור נמשך מחכמה, דהיינו התענוג והשעשועים של השי\"ת שיש לו מן העולמות. וגם עתה הוא מדבר בשביל שעשוע של השי\"ת, ובזה מחזיר את האותיות לשורשם, דהיינו חכמה שממנו נמשכו. וזהו ויקח מאבני המקום וישם מראשותיו, דהיינו לשורשם, רק בשביל תענוג המלך, ובזה נתקשר המלך בחכמה עילאה ומלביש בדיבור שלו ובכוונה הנזכר, רצוניות שלו, בזה ממשיך שפע מרצון עליון לחכמה וממנה למטה עד סוף כל המדריגות. וכשנמשך נקרא צד\"י פשוטה, נו\"ן פשוטה שנמשכה כנודע ויו\"ד שהיא חכמה נתקשרה בה. וכל הנזכר נקרא מל\"ך, ך' פשוטה רצון עליון שנמשך עד הל', הוא ג' קוים שלמעלה שביחד נקרא גימ\"ל, דהיינו ו' שהוא המשכה, ובסופ' יו\"ד שהוא נותן לדל\"ת, כמ\"ש ג\"ד גמו\"ל דלי\"ם, אבל בעשיריות נקרא למ\"ד, דהיינו המשכה שבאה מלמעלה לתמונת נו\"ן, וזהו תמונת למ\"ד. ואח\"כ מהלמ\"ד אל המ', מלכות. וזה הציור מל\"ך. וזהו הדיבור שהיה לו עליה עד למעלה בשביל השעשועים לעילא כנזכר, ועי\"כ נמשך גם לתתאי. וידוע שהצדיק נקרא כ\"ל. וזהו לא הכל בקימה ולא הכל וכו'. דהיינו תרין צדיקים לא שניהם שוים, כ\"א מלך בקימה שיש לו עליה לעילא, ושרים בהשתחויה דהיינו המשכה לתתא, כדאיתא דהשתחויה הוא המשכה. על כן תקנו השתחויה לפני השם יתברך.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י באמצע סי' צא (באמצע סי' ק). [כל הדרוש לקמן סי' תכד].</b>\n<i>חכמות בחוץ תרונה</i> – משלי א, כ.<i> ב' חכמות כו'</i> – זח\"א קמא, ב.<i> שחכמה אקרי כ\"ח מ\"ה</i> – זח\"ג כח, א. שם לד, א.<i> והוא האי\"ן</i> – תקו\"ז תמ\"ב פא, ב. שם ת\"ע קכז סע\"א וקלג רע\"ב.<i> בברית מנוחה</i> – ס' ברית מנוחה, שלהי הדרך הראשונה (ושם: היא שוכנת בחיק המלך וסוכנת למלך).<i> יושבת כו' והיא סוכנ\"ת למלך</i> – ע\"פ מ\"א א, ב' וד'.<i> בין תרין צדיקים כו'</i> – זח\"א קנג, ב.<i> בגין דאיהו רב ושליט</i> – זח\"א יא, ב. ראה ר\"ח שער היראה פ\"א.<i> חכמה יו\"ד</i> – זח\"ב קכא, א. זח\"ג י, ב.<i> מקשר היו\"ד עם הנו\"ן ונעשה צד\"י כפופה</i> – ראה זח\"א ב, ב.<i> בראשי\"ת יר\"א בש\"ת</i> – זח\"ג רנז, א. תקו\"ז ה, ב. שם ת\"ז כד, א.<i> ויקח מאבני המקום</i> – ויצא כח, יא.<i> והדיבור כו' שבו נברא העולם</i> – בר\"ר ג, ב. שם כז, א. אבות פ\"ה מ\"א.<i> ג\"ד גמו\"ל דלי\"ם</i> – שבת קד, א.<i> שהצדיק נקרא כ\"ל</i> – זח\"א לא סע\"א. זח\"ג רנז, א.<i> לא הכל בקימה כו'</i> – תענית יד, ב.\n----- שולי הגליון -----\n[ftn_1_יט]) <i>הנוסח שלפנינו כאן משובש מאד, ולא תקנתיו דדרוש זה נמצא לפנינו על נכון לקמן סי' תכד (החל מד\"ה וכתיב חכמות בחוץ תרונה), ביחד עם הרישא שבמקבילות, והמעיין ידרשנו משם</i>.\n----- הערות וציונים -----\nסימן זה הוא קטע מסי' תכד (שם ד\"ה וכתיב חכמות בחוץ תרונה) והערותי שם."]]],[400080374,"שיב\n\n<b>או</b> יאמר חכמות בחוץ תרונה. כי רבי יהושע אומר אין משגיחין בבת קול, וקב\"ה קא חייך נצחוני בני. כי החכמה נקרא עיני העדה, ומקשרים את עצמם לחכמה ואומרים סברות, יש להקב\"ה שמחה. דהיינו חכמה בא לבינה, דהיינו התענוג. וזה שקורין אותו מלך עלוב, וזהו הניצוח שמביאים אותו למדריגה שאחר זו. ואף שאין הדין כך, להיות השתנות מביאין צירופים, ע\"ד אז תתענג, וזה שקורא אותו על ה', ומנהיגים כל העולמות בצירופים אחרים. והקב\"ה משתעשע בזה שמביאין צירופים ממדריגה עליונה לתחתונה. וזהו חכמות בחוץ תרונה, כלומר שמביאים צירופים מחכמה למטה, וזה שמחה ורנה, ע\"ד הכהנים הלוים.",[["","","----- מקורות ומראה מקומות -----\n<i>חכמות בחוץ תרונה</i> – משלי א, כ.<i> רבי יהושע אומר אין משגיחין כו'</i> – ברכות נב, א. ב\"מ נט, ב.<i> וקב\"ה קא חייך כו'</i> – ב\"מ נט, ב.<i> (החכמה) [החכמים] נקרא עיני העדה</i> – שהש\"ר א, טו. ע\"ח ש\"ח פ\"א.<i> מלך עלוב</i> – פרקי היכלות פי\"ח.<i> אז תתענג . . על ה'</i> – ישעיה נח, יד.<i> על ה'</i> – זח\"ב פג, א. זח\"ג צד, ב.<i> שמחה ורנה ע\"ד הכהנים הלוים</i> – זח\"ג ח, א-ב.<i> הכהנים הלוים</i> – יחזקאל מד, טו. ראה זח\"ג מח סע\"ב.\n----- הערות וציונים -----\nעיין סי' רנח ד\"ה אבל, ובהערות שם.\n<i>וזה שקורין אותו מלך עלוב</i> – עיין קדושת לוי פ' נצבים ד\"ה והותירך (והוא בקשר להמובא לעיל סי' רכז ועיי\"ש בהערות): ובזה יבואר מש\"כ בספר רזיא\"ל [פרקי היכלות יח, ד ושם כד, ד] כי הש\"י נקרא מלך עלוב כ\"י, לשון בושה, ויבואר עד\"מ אם חכם גדול בא לשאול עצה כו' עיי\"ש. ולהעיר מתומר דבורה להרמ\"ק ריש פ\"א."]]],[400080375,"שיג\n\n<b>או</b> יאמר חכמות בחוץ תרונה. פי' אימתי חכמתו חשובה, כשהוא עוסק בחכמתו בחוץ, דהיינו הקליפות. פירוש שמעלה משם ניצוצות, חכמה זו תרונה אז.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ד, א (סי' פז).</b>\n<i>חכמות בחוץ תרונה</i> – משלי א, כ.\n----- הערות וציונים -----\nלהעיר מסי' נא, וסי' צז ד\"ה וז\"ש."]]],[400080376,"שיד\n\n<b>קול</b> קורא במדבר פנו דרך ה'. על דרך ושמעה קול אלה, (על דרך) שמשביעין אותו הוי צדיק ואל תהי רשע שעה א' בעולם. כי בהתחלת הויות הנשמה לברוא מקשרים אותה בשכינה שהיא עולם השבועה, והשבועה היא שתהא מקושרת שם. וכל הדיבורים שמדברים בעוה\"ז נחצבים מהדיבור שלמעלה. והדיבור הזה <span data-k=\"sm\">[הוא]</span> ממוצע דיבור אחרון שלמעלה ודיבור ראשון שלמטה, וכל הדיבורים שמדברים באים מזה הדיבור, וכל מה שמדבר מעורר זה הדיבור ([ftnref_1_כ]נ\"א מעורבים בזה הדיבור). וזהו לא תשא את שם ה' אלהי\"ך לשוא, פירוש, כשמדבר דברים בטלים מגביה זה הדיבור בחנם, והוא מותרה ועומד בזה <span data-k=\"sm\">[להיות לו]</span> התקשרות בזה הדיבור. וכשהוא רוצה <span data-k=\"sm\">[ח\"ו]</span> לנטות מדרך הטוב מתרה בו הדיבור, וגם מי שזוכה שומע שמתרה בו הקול <span data-k=\"sm\">[נ\"א: ומי שזוכה יודע ושומע את הקול].</span>\n<b>וזהו</b> נפש כי תחטא, אורייתא קא מתמה האיך אפשר שתחטא ושמעה קול אלה, הלא היה <span data-k=\"sm\">[לו]</span> לשמוע קול השבועה. או ראה, <span data-k=\"sm\">[שראה]</span> מעשה של אחרים ונזכר במעשיו. כי כל מה שאדם רואה ישים אל לבו למה הראה לו הקב\"ה <span data-k=\"sm\">[את זה]</span>, הלוא הכל בהשגחה פרטית. ואם רואה דבר עבירה <span data-k=\"sm\">[יחשוב]</span> מסתמא גם אני עשיתי זאת <span data-k=\"sm\">[נ\"א: שמץ מנהו]</span>, אע\"פ שלא עשיתי זאת במעשה <span data-k=\"sm\">[נ\"א: ממש]</span>, מכל מקום בענין אחר עשיתי זאת <span data-k=\"sm\">[נ\"א: הרהר בלבו לעשות, וידוע כי המחשבה חמורה ממעשה]</span>. למשל אחד עובר עבירה והולד ממזר, ומחשבה זרה חמור כמו ולד ממזר <span data-k=\"sm\">[נ\"א: למשל אם הוא רואה את אחד שבא על אשת איש והוליד ממזר, [דמיון לזה הוי מ\"ז] ומוציא זרע לבטלה על ידי מחשבה זרה חמור כמו מוליד ממזר]</span>. וזהו או ראה, שרואה דבר אחד <span data-k=\"sm\">[נ\"א: דבר עבירה מאדם אחר]</span> ונזכר <span data-k=\"sm\">[בו]</span> דבר שעשה. או ידע, על דרך אלהי\"ם בושנו במעשינו ונכלמנו להרים פנינו אליך. עך דרך משל חותם המטונף, אם ישים אותו על שעוה אז נתטנף גם השעוה. כך כשהאדם מלוכלך בעבירה ומדבק את עצמו להשם יתברך, כביכול נעשה הלכלוך בהשם ית' <span data-k=\"sm\">[נ\"א: הלכלוך למעלה]</span> כביכול כשנעשה אחדות עם השם יתברך בעת תפילתו, שמדבר דיבורים ושורה בהם הקב\"ה. לכן צריך תשובה קודם התפילה. וזהו בושנו במעשינו, מכח העבירות, ונכלמנו להרים פנינו אליך, פי' (פנימיות) [פנימיותנו] אליך, שיהא אני מדובק בך בשביל לכלוך העבירות. וזהו המדה של נושא עון, שסובל העון. וזהו או יד\"ע <span data-k=\"sm\">[כי ידע הוא לשון התקשרות, ר\"ל]</span> בשביל התקשרות הבורא מונע את עצמו מעבירות.\n<b>וזהו</b> קול קורא <span data-k=\"sm\">[הקול אלה קורא]</span>, במדבר, פי' בהדיבור, פנו דרך ה', שיהא השם ית' שורה בו. ישרו בערבה, כשנופלת לאדם מחשבה זרה בתפילתו שבא בהיכל המלך ודחפו אותו משם, (וכשמישים) [וכאשר ישים] אל לבו שדחפו אתו ישוב להקב\"ה באימה גדולה ובושה גדולה <span data-k=\"sm\">[נ\"א: ובתשובה רבה].</span> והקב\"ה מבטיח אותו אל תירא כי אתך אני, בכל מקום (שאני) [שאנו] שם מביאים הקב\"ה שם. וזהו ישרו בערבה, בזה שהמחשבה מעורב בקליפות, מסיל\"ה, נקרא דרך שאינו כבושה, לאלהינ\"ו.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' סט (סי' פא). אוה\"א לח, א.</b>\n<i>קול קורא במדבר גו'</i> – ישעיה מ, ג.<i> ושמעה קול אלה</i> – ויקרא ה, א.<i> שמשביעין אותו כו'</i> – נדה ל, ב.<i> בשכינה שהיא עולם השבועה</i> – ראה זח\"ג רנה סע\"א. ע\"ח, שער הכללים פ\"ז.<i> לא תשא גו'</i> – יתרו כ, ז.<i> נפש כי תחטא . . ושמעה גו' או ראה . . או ידע</i> – ויקרא ה, א.<i> אורייתא קא מתמה כו'</i> – זח\"ג יג, ב. שם טז, א.<i> אלהי\"ם בושנו כו'</i> – סליחות (ראה בהערות). ע\"פ עזרא ט, ו.<i> לכן צריך תשובה קודם התפילה</i> – ראה זח\"א רכח, ב.<i> ישרו בערבה . . מסילה לאלקינו</i> – ישעיה מ, ג.<i> כשנופלת כו' שבא בהיכל המלך ודחפו כו'</i> – זח\"ב רמה, ב.<i> אל תירא כי אתך אני</i> – ישעיה מג, א-ב.<i> מסיל\"ה נקרא כו'</i> – ראה זח\"א קמב, א.\n----- שולי הגליון -----\n[ftn_1_כ]) <i>הנ\"א הנזכר אינו במקבילות שנסמנו</i>.\n----- הערות וציונים -----\n<i>וכל הדיבורים שמדברים בעוה\"ז כו'</i> – ראה סי' שב. וראה ריש סי' רעז-א. סי' שיז. ריש סי' תו.\n<i>וזה נפש – </i>(עד סוף הקטע) כבר הובא לעיל סי' קז.\n<i>ישרו בערבה מסילה לאלקינו</i> – ראה פי' הרה\"מ באורח לחיים פ' דברים סד\"ה אלה הדברים, פי' הפסוק קול קורא גו' באו\"א, ושם: ישרו בערבה כשהאדם הוא בערבוב ואין יכול להיות יחוד קול ודיבור ואין לו דרך ה' לעשות יחוד, עכ\"ז תישרו בערבה כשאתם בערבוב [בשמועה טובה נד, א: ערבוב מחשבה] שתתן עכ\"פ מסילה לאלקינו.\n<i>כשנופלת לאדם מ\"ז כו' דחפו אותו משם כו'</i> – ראה סי' שפו וסי' תו. מדל\"י סי' מז (נג). ורג\"כ לעיל סי' נ ד\"ה וזהו פי' וימלוך.\n<i>מסילה נקרא דרך שאינו כבושה</i> – צ\"ע מפרש\"י וארא ט, יז: מסילה דמתרגמינן (ישעיה יא, טז) אורח כבישא. וכן בזח\"א קמב, א מסלה דאיהי מתיישבא לאעברא כו'."]]],[400080377,"שטו\n\n<b>כי</b> תורה חדשה מאתי. כי הנה ידוע באורייתא ברא קב\"ה עלמא. והנה יש בעולם עור בשר וגידין ועצמות. ומוכרח <span data-k=\"sm\">[הוא]</span> שיש גם כן בתורה כל זה. כי בהכרח שיהיה בפועל מה שיש בנפעל, כי כח הפועל בנפעל[ftnref_1_כא].\n<b>והנה</b> התורה היא קומה שלימה, עור ובשר גידין ועצמות. עו\"ר נקרא קליפות דאורייתא. בש\"ר נקרא <span data-k=\"sm\">[נ\"א: על דרך]</span> מי שמיגע עצמו על התורה טועם בה טעם בשר. גידין (ע\"ש) [ע\"ד] ויג\"ד להם <span data-k=\"sm\">[שאמר להם]</span> דברים הקשים כגידין. ועצמות, <span data-k=\"sm\">[פי']</span> התורה עצמה <span data-k=\"sm\">[נ\"א: עצמיות התורה]</span> לא נתגלה עדיין. כי הנה כל התורה מלוקט מאנשים צדיקים, מאדם (ועד) [ו-]נח ואבות ומשה, שהישרו השכינה במעשיהם, וזהו תורה שלימה. אבל בהירות (עצמות) [עצמיותה] לא נתגלה עדיין עד שיבוא משיח צדקינו בב\"א, ויבינו את הבהירות עצמו <span data-k=\"sm\">[נ\"א: ויבינו את בהירות עצמיותה]</span>. וזהו תורה חדשה מאת\"י פי' מעצמיות.\n<b>וזה</b> (שראה) [שניבא] יחזקאל, שהוא ראה את בנין העתיד, התחיינה העצמות <span data-k=\"sm\">[האלה]</span>, פירוש העצמיות של התורה, ויאמר אלהים אתה ידעת. ר\"ל, אם התקשרות יהיה ממך אז יהיה מושג ומובן העצמיות. והסוד הוא למה באמת אינו מובן עתה העצמיות של התורה <span data-k=\"sm\">[ואין משיגים אותה]</span>, ולמה הוא כך. אך לפי שאין עתה התורה אלא רק מה שנלקח מבני אדם, קצת תורה נלקחה מלבן, ר\"ל מהסיפורים שלו, וקצת מסיפורי בלעם, וקצת מסיפורי שאר בני אדם הכתובים בתורה. אך לעתיד יהיה התקשרות הקב\"ה בתורה, ועתידין אנו להשיג גם העצמיות. וז\"ש כי <span data-k=\"sm\">[תורה חדשה]</span> מאתי תצא (תורה), ולא כמו שהוא עתה שהתורה אינה רק הסיפורים כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<i>כי תורה . . כח הפועל בנפעל:</i><b> לקו\"י לא, ג (סי' רנ).</b><i> והנה התורה כו' . . פירוש העצמיות של התורה:</i><b> מדל\"י ו (ו). אוה\"א לח, ב.</b><i> ואמר כו':</i><b> לקו\"י שם.</b>\n<i>כי תורה חדשה מאתי</i> – ראה ויק\"ר יג, ג ע\"פ ישעיה נא, ד.<i> באורייתא ברא כו'</i> – זח\"א ה, א.<i> גם כן בתורה כל זה</i> – זח\"א קלד, ב.<i> מי שמיגע עצמו כו'</i> – עירובין כא, ב.<i> ויג\"ד</i> – יתרו יט, ט.<i> דברים הקשים כגידין</i> – שבת פז, א.<i> יחזקאל שהוא ראה את בנין העתיד</i> – יחזקאל פ\"מ ואילך.<i> התחיינה העצמות האלה</i> – יחזקאל לז, ג.<i> ואמר [ה'] אלקים גו'</i> – שם.<i> תורה מאתי תצא</i> – ישעיה נא, ד.\n----- שולי הגליון -----\n[ftn_1_כא]) <i>עד כאן בלקו\"י, ומכאן ואילך ממשיך שם בנ\"א:</i> אך כי באמת יש כל אלה בתורה. כי פשטיות התורה הוא סוד עור. ובשר התורה על דרך מ\"ש בגמרא (עירובין כא, ב) על פסוק (קהלת יב, יב) ולהג הרבה יגיעת בשר, בכל פעם שהוא לומד טועם בו טעם בשר. וגידין הוא מרומז בפסוק (יתרו יט, ג) ותגיד לבני ישראל, כמ\"ש רש\"י שם. אך העצמות של התורה אין אנו יכולין להשיג עתה, רק לעתיד. וזה סוד הפסוק ביחזקאל התחיינה העצמות האלה, ויאמר <i>(כבפנים)</i>.\n----- הערות וציונים -----\n<i>עור ובשר גידין ועצמות כו'</i> – ראה כתבי קודש כד, ד ושמועה טובה נט, ב: יש עור שהוא פשט שעדיין הם מרומז בקליפות התורה כמעשה לבן ודומה לו, ואח\"כ ההוגה בה טועם טעם בשר, ואח\"כ העלים דברים שקשין כגידין, ואח\"כ עצמו [והן עצמיות] התורה, וליחזקאל נתגלה עצמיות [התורה] [ולכן כתיב ותקרב] עצם אל עצמו.\n<i>בהירות עצמיות התורה לא נתגלה עדיין עד שיבוא משיח כו'</i> – ראה כש\"ט סי' פד ד\"ה ותירץ.\n<i>אתה ידעת ר\"ל אם התקשרות כו'</i> – ע\"פ ידעת לשון התקשרות (ראה תקו\"ז תס\"ט צט, א).\n<i>קצת ד\"ת נלקחה מלבן כו'</i> – ראה בהערות לסי' פא."]]],[400080378,"שטז\n\n<b>עבדי</b> אתה ישראל אשר בך אתפאר. הוי ליה למימר בני. אך מי שיש לו עבד הוא מפאר את העבד במלבושים נאים ופאר התפארות לאדון, ובזה נתלהב לב העבד לאהוב את רבו כי מפאר אותו.",[["","","----- מקורות ומראה מקומות -----\n<i>עבדי אתה ישראל גו'</i> – ישעיה מט, ג.\n----- הערות וציונים -----\n<i>אתפאר . . במלבושים נאים כו'</i> – ראה קדושת לוי ס\"פ נח ד\"ה וירח: השי\"ת מתפאר בישראל כנאמר ישראל אשר בך אתפאר דאמר הצדיק ר' בער ז\"ל אתפאר מלשון התלבשות מלשון ויתפרו עלי תאנה ע\"כ דבריו."]]],[400080379,"שיז\n\n<b>מי</b> עלה שמים וירד, למטה, ולהעלות היראה והאהבה במחשבתו שהם נקראים שמים, מי אסף רוח בחפניו, פי' מי שיאסוף כל הדיבורים למעלה במדות. מי צרר מים בשמלה, מי צרר מים התורה בשמלה, במלבוש, על דרך שיחת חולין של ת\"ח צריכה לימוד. מי הקים כל אפסי ארץ, כל הנצוצין של ארציות. זה מה, שהוא מה שמו ומה שם בנו כי תדע. פירוש כשיודע שכל מה הוא משמו כנודע, מאהבה ויראה ובכל הכנויים, שכל הדיבורים והמחשבות הכל מהשכינה. ומה שכל זה הוא משם, פי' שכל המדות יראה ואהבה וכו' וכל החכמות הכל מהשי\"ת והם כמו הבן כביכול. נמצא כשיודע כל זה הוא מעלה אותם להקב\"ה. לזה אומר אמרת ה' צרופה[ftnref_1_כב], לא לחנם, כי מהדיבור העליון כנזכר, וגם לשון צירוף הוא שיודע לצרף את כל הדיבורים המעשיות והגשמיות להשי\"ת.\n<b>וזהו</b> תורה לשמה, ולא במעשה לבד. נמצא זה הכלל, מה שאדם רואה או שומע או מדבר יקח להשי\"ת יראה ואהבה, או שיודע הצירופים והכינוים כנזכר. וזהו פירוש תורה לשמה, כשמה, שהיא מורית לאדם יראה ואהבה וכו', וגם בשבילה, וזהו לשם ה', פירוש לשם השכינה, שיעלה כל הדיבורים כנזכר, ולא למעשה בלבד, כי זה גרם כמו[ftnref_2_כג], וזהו אורייתא שמותיו של הקדוש ברוך הוא.",[["","","----- מקורות ומראה מקומות -----\n<i>מי עלה שמים וירד</i> – משלי ל, ד.<i> היראה והאהבה . . נקראים שמים</i> – ראה זח\"ג רנז, א.<i> מי אסף גו' מי צרר גו' מי הקים גו' מה שמו גו'</i> – משלי שם.<i> מים התורה</i> – ב\"ק יז, א.<i> שיחת חולין כו'</i> – סוכה כא, ב.<i> אמרת אלוה צרופה</i> – משלי ל, ה.<i> תורה כו' שהיא מורית כו'</i> – זח\"ג נג, ב.<i> לשמה . . לשם ה'</i> – פע\"ח ריש שער הנהגת הלימוד. שער המצות פ' ואתחנן ד\"ה ענין מ\"ש רז\"ל.<i> אורייתא שמותיו של הקב\"ה</i> – זח\"ב קכד, א. שם פז סע\"א. שם צ, ב.\n----- שולי הגליון -----\n[ftn_1_כב]) <i>נראה שצ\"ל</i> אמרת אלוה צרופה, <i>ע\"פ לשון הכתוב במשלי ל, ה הבא תיכף אחרי הפסוק הנדרש כולו לעיל, ובפנים העתיק לשון הכתוב בשירת דוד (ש\"א כב, לא; תהלים יח, לא)</i>.\n[ftn_2_כג]) <i>אולי צ\"ל</i> כי זה גרם שמו, <i>ואם לאו חסר כאן</i>.\n----- הערות וציונים -----\n<i>שכל הדיבורים . . מהשכינה</i> – ראה ריש סי' שב ובהערות שם.\n<i>מה שאדם רואה או שומע או מדבר יקח כו'</i> – ראה סי' קז ד\"ה או ראה, וריש סי' קטו.\n<i>כשמה שהיא מורית לאדם כו'</i> – ראה סי' תנג. רג\"כ סי' תמא ד\"ה וזהו.\n<i>לשם ה'</i> – ראה סי' תיט. וראה בהערות לכש\"ט סי' קמב."]]],[400080380,"שיח\n\n<b>החכם</b> עיניו בראשו. פירוש כל מה שהוא רואה בעיניו הוא מסתכל בראשו, פי' בשרשו. כי כל דבר מה שיש בעולם הכל יש להם שורש בעולם העליון כנודע. נמצא מזה ההסתכלות עליהם הוא מקשר ומיחד הבורא ית' עליו, והוא בבורא ית', להורות כי מלא כל הארץ כבודו רב ושליט שרשא דכל עלמין. וזהו ראשית חכמה יראת ה', יראה מכח בושה, להעלות מכל המדות והתנועות להשי\"ת כנזכר, בגין דאיהו רב ושליט. ואם לאו, ח\"ו הוא נרגן מפריד אלוף, אלופו של עולם. וגם כל התנועות צריך שיהיה עושה אותם ביראה ובבושה, כי הוא עושה ממש בכחו יתברך, המחשבה מעולם המחשבה, הדיבור מעולם הדיבור, כי בצלם אלהים נעשה. לכן צריך שיהיה לו יראה ובושה שהוא מעורר את העולם העליון ממש כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<i>החכם עיניו בראשו</i> – קהלת ב, יד.<i> כל דבר כו' שורש בעולם העליון</i> – ראה זח\"א קנו רע\"ב. פרדס רמונים שכ\"ב פ' א-ב. ראה לעיל הנסמן בריש סי' קנז.<i> מלא כל הארץ כבודו</i> – ישעיה ו, ג.<i> בגין דאיהו רב ושליט כו'</i> – זח\"א יא, ב.<i> ראשית חכמה גו'</i> – תהלים קיא, י.<i> יראה מכח בושה</i> – ראה תקו\"ז ה, ב.<i> נרגן מפריד אלוף</i> – משלי טז, כח.<i> אלופו של עולם</i> – זח\"ג טז רע\"ב. שם לא, א.<i> כי בצלם אלקים נעשה</i> – ע\"פ בראשית א, כז. נח ט, ו.\n----- הערות וציונים -----\n<i>החכם עיניו בראשו כו'</i> – ראה סוף סי' רו.\n<i>כי כל דבר כו' יש להם שורש בעולם העליון כנודע</i> – ראה ריש סי' קנז. וסי' ר ד\"ה והנה כשעלה.\n<i>כי הוא עושה ממש בכחו יתברך</i> – ראה מדל\"י סי' לח (מא).\n<i>מחשבה מעולם המחשבה הדיבור מעולם הדיבור</i> – ראה מדל\"י סי' לט (מב)."]]],[400080381,"שיט\n\n<b>צדיק</b> מושל (ב)יראת אלהי\"ם, צדיקים הופכים מדת הדין לרחמים. למשל כשתינוק רוצה איזה דבר שהתינוק נהנה ממנו, אביו מחמת אהבתו לתינוק יש לו הנאה כשיהיה אותו הדבר לתינוק, שנמצא כי התינוק מוליד אהבת אותו דבר באביו. וכן למשל כשיש כאב לאדם ברגליו, גורם הרגל רצון במחשבתו שיצוה ליד להסיר הכאב, כיון שהם אחדות אחד. וכן הצדיק כשהוא דבוק בבורא יתברך, כל מה שחסר לו גורם למעלה כביכול רצון בבורא יתברך.\n<b>וזה</b> המשל הא' שייך לענין מה שאמרו רז\"ל שמצוה בשבת אכילה ושתיה. ולכאורה קשה, מה הנאה יש לנשמה יתירה באכילה ושתיה. אבל לפי משל הזה אתי שפיר, שהנשמה יתירה יש לה גם כן תענוג מזה, כמו שכתב בזוהר <span data-k=\"sm\">[על פסוק]</span> באתי לגני אחותי כלה, בשביל רעותא דילה אכיל ושתי.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' לו (לט). אוה\"א מו, א.</b>\n<i>צדיק מושל גו'</i> – ש\"ב כג, ג.<i> צדיקים הופכים מדה\"ד לרחמים</i> – זח\"ג רמח רע\"א. סוכה יד, א.<i> שמצוה בשבת כו'</i> – שבת קיח, ב. פסחים סח, ב. רמב\"ם הלכות שבת פ\"ל.<i> כמ\"ש בזוהר באתי כו'</i> – זח\"ג רמא סע\"ב.<i> באתי לגני גו'</i> – שה\"ש ה, א.\n----- הערות וציונים -----\n<i>למשל כשתינוק כו'</i> – ראה סי' ס סד\"ה ונמשיל.\n<i>כל מה שחסר לו כו'</i> – ראה שם ובהערות שם.\n<i>שמצוה בשבת אכילה ושתיה כו'</i> – ראה סי' קצט. וראה כש\"ט סי' קז ובהערות שם."]]],[400080382,"שכ\n\n<b>הושיענו</b> ונושעה כי תהילתנו אתה. פי' אנו מתפללים להשי\"ת הושיענו, דהיינו שתגאל אותנו מן הגלות, ובשביל אנו <span data-k=\"sm\">[ונושעה]</span> שנינו. במה, מפרש ואמר כי תהילתנו אתה, ר\"ל כי תהילה שישבחו אז אותנו, דהיינו בקדושה, את\"ה, היא תהילתך <span data-k=\"sm\">[נ\"א: עתה היא תהילתך]</span>[ftnref_1_כד], וזהו את\"ה, ובוודאי יהיה אז תהילתך יותר מעולה. נמצא שנושעה שנינו אז כשתגאל אותנו. וזהו פירוש כשאנו נגאלין, שאז יהיה תהילתינו בקהל חסידים, דהיינו תהילה שמשבחים אתה (נ\"א עתה)[ftnref_2_כה] בקדושה יהיה אז עלינו אותה תהילה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א מז, ב.</b>\n<i>הושיענו ונושעה כו'</i> – עמידה דימי חול ע\"פ ירמיה יז, יד.<i> שנושעה שנינו</i> – ראה פרש\"י נצבים ל, ג ע\"פ מגילה כט, א.<i> שישבחו אז כו' בקדושה</i> – ב\"ב עה, ב.<i> תהילתנו בקהל חסידים</i> – ע\"פ תהלים קמט, א.\n----- שולי הגליון -----\n[ftn_1_כד]) <i>נראה שהנ\"א עיקר, שכן מבואר לעיל סי' רמט, וכן משמע גם כאן מההמשך</i> וזהו את\"ה כו'.\n[ftn_2_כה]) <i>נראה שיש לקיים ב' הנוסחאות ביחד</i>. שמשבחים אתה <i>(כלומר אותך)</i> עתה בקדושה כו', <i>כמבואר לעיל בסי' רמט</i>.\n----- הערות וציונים -----\nראה לעיל סי' רמט."]]],[400080383,"שכא\n\n<b>אל</b> יתהלל חכם בחכמתו. דאיתא ברעיא מהימנא משל לבאר מים חיים נובע לעשרה גומות וכו'. נמצא שכל המדות אין להם סוף. אך מה שנשתלשל אחד מאחד, ואנו תופסין זה בחינת הכלי שזה מאציל וזה נאצל, ובערך הכלי נקרא מדה, אך בערך העצם הוא אין סוף. נמצא אם אדם אומר שהוא חכם בעצמו ומתגאה, הוי חיסרון, כי זה וודאי יש סוף. ואם היה לו שכל שחכמתו הוא מאין סוף <span data-k=\"sm\">[ב\"ה]</span>, ואין סוף לא (יתחלף) [יתחלק], לא היה מתגאה. אבל הוא מראה שהוא מהשבירה, בחינת כלי. ולזה אמר כי אם השכל וידוע אותי, שהוא לשון התקשרות, כמו משכי\"ל לאיתן כמ\"ש בסבא דמשפטים, ור\"ל שיתקשר אתי[ftnref_1_כו].",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א מח, א (95). ראה לקו\"י יז, ב (סי' ריט).</b>\n<i>אל יתהלל חכם בחכמתו</i> – ירמיה ט, כב.<i> דאיתא בר\"מ משל כו'</i> – זח\"ב מב, ב.<i> כי אם . . השכל וידוע אותי</i> – ירמיה ט, כג.<i> משכי\"ל לאיתן</i> – תהלים פט, א.<i> כמ\"ש בסבא דמשפטים</i> – זח\"ב קי סע\"א.\n----- שולי הגליון -----\n[ftn_1_כו]) <i>בלקו\"י יז, ב (סי' ריט) נ\"א יותר מבורר:</i> אם אדם אומר בגדולתו שהוא חכם, אילו היה לו שכל (אדם) היה מתיישב בעצמו שזהו <i>(כלומר חכמתו)</i> מא\"ס ב\"ה, [ו]לא היה מתגאה. אבל הוא אומר שהוא חכם מעצמו, הוי חסרון, דלזה בודאי יש לו סוף. אבל מא\"ס ב\"ה הכל הוא באין סוף, [ו]באין סוף אינו מתחלק. אבל באמת גדולתו מראה חסרונו שהוא מהשבירה, בחינת אנא אמלוך. ולזה אמר הכתוב אל יתהלל חכם בחכמתו, ר\"ל שמייחד החכמה לעצמו, כי אדרבא חסרון הוא לו, ובמה יתהלל. כי אם בזאת יתהלל המתהלל השכל וידוע אותי, ידוע הוא מלשון התחברות והתקשרות, ר\"ל שיתקשר במחשבתו שהכל הוא מאתו ב\"ה, ואז יקרא חכם האמיתי. וז\"ש השכל וידוע אותי כנ\"ל.\n----- הערות וציונים -----\nראה סי' קנא-ג.\n<i>הוא מראה שהוא מהשבירה</i> – ראה סי' קעו שהשבירה כבר היה בשביל גדלות כו'."]]],[400080384,"שכב\n\n<b>פירוש</b> הפסוק לדעת בארץ דרכך. <span data-k=\"sm\">[לדעת כמו וידע האדם]</span>, לשון זיווג. <span data-k=\"sm\">[פירוש, אנו מתפללים להשי\"ת שיזווג עם הארץ. וזהו לדעת בארץ, פירוש השכינה, דרכך, לשון זיווג]</span>, כי ביאה אקרי דרך.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' כד (כח). אוה\"א מח, א (95).</b>\n<i>לדעת בארץ דרכך</i> – תהלים סז, ג.<i> לשון זווג</i> – בראשית ד, א. תקו\"ז תס\"ט צט, א.<i> בארץ פי' השכינה</i> – ראה זח\"א נ, ב. זח\"ב יב, א.<i> ביאה אקרי דרך</i> – קידושין ב, ב.\n----- הערות וציונים -----\nפירושו נראה דליהוי יחוד קוב\"ה ושכינתיה."]]],[400080385,"שכג\n\n<b>אדם</b> לעמל יולד, איני יודע אם לעמל <span data-k=\"sm\">[פה וכו' ועדיין איני יודע אם לעמל]</span> תורה וכו' ועדיין איני יודע אם לעמל שיחה וכו' תלמוד לומר והגית בו יומם ולילה וגו'. הנה רש\"י ז\"ל פירש בפרשת ויצא שעקירתו של הצדיק ויציאתו עושה רושם. פירוש, הגם אם הצדיק המחיה את מקומו אעפ\"י שיצא ממקומו, הניח רשימו במקום הזה[ftnref_1_כז]. והיינו כמ\"ש בכתבי האר\"י זלה\"ה, כשנשבר הכלי ויצא הבהירות והאור ממנו, אעפי\"כ הניח הרשימו <span data-k=\"sm\">[בכלי]</span> המחיה (אותה) [את הכלי]. וגם אצל מטי ולא מטי מבואר כן, (וכן) <span data-k=\"sm\">[ש]</span>כשיצאו מן הכלים אעפי\"כ (הניח הרשימו) [נשאר רישומן] בהכלים.\n<b>ואיתא</b> (בספר יצירה) <i>[בסימן]</i> [ש]בכל דבר יש חומר וצורה פועל ותכלית. פי', למשל שיר השירים, הפועל הוא שלמה המלך ע\"ה. התכלית הוא הספר כולו בכלל. החומר הם האותיות. והצורה הם תמונת האותיות, דהיינו כל אות בא בתמונה ידועה כפי שקיבל מהפועל. או בענין אחר, שהפועל הוא השי\"ת. והתכלית הוא (שנחזור) [שנחקור] ונעמוד על הדבר, דהיינו מה המציאות שלו. כמו למשל שיר השירים, כשנעמוד עליו <span data-k=\"sm\">[נדע]</span> שהוא אהבת ה' אלינו, והוא תכליתו של שיר השירים. והחומר הם האותיות. והצורה הוא השכל שבאותיות המצרפן (ועושיהו) [ועושה] מאותיות הצירוף שהוא עתה. והמבין[ftnref_2_כח] יבין שהב' דרכים הם אחד, אך שהראשון הוא בעשיה לבדו והב' הוא בכללות.\n<b>ונחזור</b> לענין, שתכלית בריאת האדם היא בכדי שנעלה העולמות לשורשן, דהיינו שמחזירם לאי\"ן כמקודם, על ידי תורה ותפילה ומעשים טובים, ומדבקן להשי\"ת, אך באופן שנחזיק את עצמינו ג\"כ אי\"ן ומ\"ה. וזהו מדת מ\"ה מתקן כל השבירות, דהיינו נפילת העולמות נעשו מתוקנים ועולים על ידי האדם כשהוא במדריגת מ\"ה. והנה כשהוא כן, הגם שאנחנו רואים שהגוף של האדם אין לו עליה והוא עומד במקומו כאשר בתחילה, רק מעשה מצות, דהיינו החומר, נתקשר בו ע\"י עשייתם בהיותו <span data-k=\"sm\">[הוא]</span> הפועל שלהם, והוא מכניס בהם הב' הנותרות, דהיינו תכלית וצורה, (אך) [ו]הוא מעלה אותן אח\"כ להדיבור של מצוה. <span data-k=\"sm\">[כי]</span> אז כשעושה המצוה שורה הדיבור על המצוה והבן. (אך) [ואז] פנימיות העולמות יש לו עליה, דהיינו הדיבור מה שהאדם לומד או מתפלל <span data-k=\"sm\">[ומברך על המצוה]</span>, והדיבור הוא פנימיות, וע\"כ הדיבור בקל יש לו עליה להשי\"ת בהיותו בכוונת הפועל של הדיבור כנזכר. וזו פשיטא, כשאדם במדריגת אי\"ן כנזכר, אז הדיבור הוא בעולם הדיבור <span data-k=\"sm\">[נ\"א: אז יש לו עליה לעולם הדיבור]</span> כי בדבר ה' שמים נעשו. אבל חיצוניות העולמות יתוקנו אי\"ה בביאת הגואל במהרה בימינו, שהש\"י יעלם בעצמו, ולא <span data-k=\"sm\">[ניתנה]</span> להאדם להעלות כזה <span data-k=\"sm\">[נ\"א: אותם]</span>.\n<b>וז\"ש</b> איני יודע אם בעמל של מלאכה, דהיינו שיעלה את העשיה שהוא הגוף, לכך הביא לימוד, שלא על העשיה נאמר כ\"א (בדיבור) [על הדיבור], שהוא פנימיות כנזכר.\n<b>והנה</b> ידוע שמים התחתונים בוכים, שזה קאי על אותיות הדיבור מה שהוא לבד מדיבור התורה ותפילה, שהאיש הנלבב יכול להעלותם בשמיעתם כמבואר במקום אחר. ובזה שמעלה ניצוצות הקדושה, שהם האותיות, עושה נחת רוח <span data-k=\"sm\">[גדול]</span> ליוצרו. <span data-k=\"sm\">[אבל לכתחילה אסור לומר]</span>, (וידוע) [כי ידוע] מ\"ש במקום אחר שהדברים בטלים, הם לשון הרע ורכילות וליצנות וכדומה מה שאסור לדבר, והנה ע\"ש כך נקראים דברים בטלים לפי שאל יאמר אדם הנה הם אותיות אלך ואעלה אותם לשורשם כנזכר, חלילה לומר כן, לפי שיש לאו בדברים בטלים. ואל ידאג מהאותיות שהם נשארים בשבירתן, כי ידוע מ\"ש רז\"ל <span data-k=\"sm\">[רמז כי]</span> לאחר שנטפו ג' טיפין מהכלי אז אין להקפיד על הנשאר בכלי כי הם הפקר. לכך קורא להאותיות ההם דברים בטלים, כי אין להעלותם, והם בטלים מעצמן כי הם הפקר. וזהו עדיין איני יודע אם בעמל של שיחה, דהיינו דברים בטלים שהם אלו הנזכרים, תלמוד לומר והגית בו וגו' כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' צח (קז). אוה\"א לא, א.</b>\n<i>אדם לעמל יולד</i> – איוב ה, ז.<i> איני יודע אם לעמל כו'</i> – סנהדרין צט, ב.<i> והגית בו גו'</i> – יהושע א, ח.<i> רש\"י ז\"ל פירש כו'</i> – ויצא כח, י.<i> כמ\"ש בכתבי האר\"י זלה\"ה כו'</i> – ע\"ח שי\"ח פ\"א.<i> וגם אצל מטי ולא מטי מבואר כן</i> – שם ש\"ו פ\"ה.<i> ואיתא בסימן</i> – לעיל סי' קיד.<i> שה\"ש . . אהבת ה' אלינו כו'</i> – זו\"ח חקת נא רע\"ג. רמב\"ם, הלכות תשובה פ\"י סה\"ג. ס' העיקרים מ\"ג פל\"ז.<i> מדת מ\"ה מתקן כו'</i> – ע\"ח ש\"י פ\"א. שם שי\"ז פ\"ג.<i> בדבר ה' שמים נעשו</i> – תהלים לג, ו.<i> שמים התחתונים בוכים כו'</i> – תקו\"ז ת\"ה יט, ב.<i> כמבואר במ\"א</i> – ראה לעיל סי' סב וסי' סג.<i> מ\"ש במקום אחר</i> – ראה סי' צז וסי' שיד.<i> שיש לאו בדברים בטלים</i> – יומא יט, ב.<i> כי לאחר שנטפו כו'</i> – ב\"ב פז, א.\n----- שולי הגליון -----\n[ftn_1_כז]) <i>הלשון יותר מבורר באוה\"א:</i> דגם אם הצדיק המחיה את מקומו יצא ממקומו, אעפ\"כ הניח רישומו במקום ההוא.\n[ftn_2_כח]) <i>במדל\"י </i>והמבין . . בכללות <i>בסוגריים</i>.\n----- הערות וציונים -----\n<i>שכשיצאו מן הכלים אעפי\"כ נשאר רישומן בהכלים</i> – רג\"כ פרדס רמונים שי\"ד פ\"א. ע\"ח ש\"ו פ\"ו. שם של\"ד פ\"ג ושמ\"ז פ\"ו. של\"ה בית ה' ד\"ה ואז יתברר (ד, א).\n<i>שיר השירים . . שהוא אהבת ה' אלינו</i> – ראה הנסמן במ\"מ וזח\"ב קמד, א.\n<i>שנעלה העולמות לשורשן דהיינו שמחזירם לאי\"ן כמקודם</i> – ראה סי' שעז ד\"ה ופעולת. רג\"כ סי' קכ ד\"ה והנה ידוע.\n<i>אך באופן שנחזיק את עצמינו ג\"כ אי\"ן ומ\"ה כו'</i> – ראה סי' לו ד\"ה ואפשר לומר שזה ג\"כ. סי' צז ד\"ה וזהו. וסי' שעז.\n<i>כשאדם במדריגת אי\"ן כנזכר אז הדיבור כו'</i> – ראה סי' תכד ד\"ה וז\"ש ויקח.\n<i>שמים התחתונים בוכים שזה קאי על כו'</i> – ראה סי' סב.\n<i>אותיות הדיבור כו' להעלותם כו'</i> – ראה בהערות לסי' רנב.\n<i>שאיש הנלבב</i> – לביטוי זה ראה סי' סב ובהערות שם.\n<i>נקראים דברים בטלים כו'</i> – ראה סי' שיד."]]],[400080386,"שכד\n\n<b>הנה</b> ה' רוכב על עב קל. פירוש <span data-k=\"sm\">[הנה]</span> ה' רוכב על אותו אדם שכשעושה איזה עבירה אליו היא עבה וחמורה, אף שהיא קלה בעצם.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סוף סי' קד (קטו). אוה\"א מט, א.</b>\n<i>הנה ה' רוכב גו'</i> – ישעיה יט, א.\n----- הערות וציונים -----\nלהעיר משמועה טובה סט, א ד\"ה בגמ' במקום שבע\"ת עומדין (והזכיר שם פירוש הבעש\"ט עה\"פ אשרי אדם לא יחשוב ה' לו עון, מבלי לפרשו, ופי' הובא בדמ\"א ס\"פ ויקרא ושם פ' בלק רד\"ה ויש עוד עיי\"ש)."]]],[400080387,"שכה\n\n<b>על</b> הר גבוה עלי לך. האבות נקראים הרי\"ם. אך יש ג' מיני אהבות. א' אהבה שבאה מחמת עובדות, שרואה אחד שעשה כלים יפים ומפוארים ואוהבו בשביל זה. ואהבה ב', הבאה מכח דיבורו היפה. והג' אהבה מחמת חכמתו שהוא חכם <span data-k=\"sm\">[גדול]</span>. <span data-k=\"sm\">[ואיתא]</span> בינה ליבא ובה הלב מבין. וקשה, הא בינה היא מהמוחין והם בתלת חללי דגולגלתא. אך היסודות, פירוש התקשרות דתרין ריעין דלא מתפרשין, מתפשטין עד (החכמה) [החזה] כנודע. לכן ההבנה היא בלב, כי שם היא מקבלת ממדריגה עליונה, מקדמות השכל. וצדיק נקרא ציו\"ן, כמ\"ש רשב\"י ע\"ה אנא סימנא בעלמא. פירוש, כי הצדיק במעשים טובים שלו עושה רושם למעלה וגורם תענוג בעולמות עליונים. למשל האבות היו עושים בבארות ומקלות אותם הפעולות שנעשים בתפילין, נמצא כי כשאבות עושים הפעולה הנזכר עיקר התקשרות שלהם היה בעולם המחשבה. על דרך משל, כשראה הבאר נזכר ([ftnref_1_כט]נ\"א ניכר) <span data-k=\"sm\">[נ\"א: נתדבק]</span> במקור מים חיים, בנהר יוצא מעדן. נמצא כי המחשבה היא הר גבוה, והעובדות הם ציון לזה. וגם יותר למעלה <span data-k=\"sm\">[נ\"א: וכשהם מחשבים למעלה]</span> יכולים לעשות רצון, ויכולים לעשות מדבר רע טוב, כמו שמצינו אצל רשב\"י ע\"ה שהיה מדכי שוקי דטבריא, פירוש שוקי הם מדריגות תחתונות, והעלם למעלה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קט (קכא). אוה\"א מט, ב.</b>\n<i>על הר גבוה עלי לך</i> – ישעיה מ, ט.<i> האבות נקראים הרי\"ם</i> – ר\"ה יא, א. שמ\"ר טו, ד.<i> בינה ליבא ובה כו'</i> – תקו\"ז יז, א.<i> בתלת חללי דגולגלתא</i> – זח\"ג קמ, א.<i> דתרין ריעין דלא מתפרשין</i> – ע\"פ זח\"ג ד, א.<i> מתפשטין עד החזה</i> – ע\"ח שי\"ד פ' א-ב. שם של\"א פ\"ג.<i> אנא סימנא בעלמא</i> – זח\"א רכה, א.<i> האבות היו כו' שנעשים בתפילין</i> – ראה זח\"א (ס\"ת) קסב, א. וראה שם קמא, א.<i> רשב\"י ע\"ה שהיה מדכי כו'</i> – זח\"ב לז רע\"א. זח\"ג עב, ב. ראה ירושלמי שביעית פ\"ט סה\"א.\n----- שולי הגליון -----\n[ftn_1_כט]) <i>הנ\"א אינו במקבילות הנסמנים</i>.\n----- הערות וציונים -----\n<i>וצדיק נקרא ציון</i> – ראה סי' נא ד\"ה ונחזור. וסי' קסד.\n<i>למשל האבות היו עושים כו'</i> – להעיר מסי' עא ובהערות שם ד\"ה וזהו.\n<i>יכולים לעשות רצון</i> – ראה סי' פט.\n<i>מדכי שוקי דטבריא</i> – ראה סי' רצה."]]],[400080388,"שכו\n\n<b>תתן</b> אמת ליעקב. אמרו חז\"ל חותמו של הקב\"ה אמ\"ת, ע\"ד אני ראשון ואני אחרון ומבלעדי וגו'. כך א' ריש אתוון, ת' בסוף, מ' באמצע וממוצע בין שניהם. ואיתא בזוהר תלת עלמין אית ליה <span data-k=\"sm\">[וכו']</span>. פי' הענין, באורייתא ברא הקב\"ה <span data-k=\"sm\">[עלמא]</span>, פירוש באותיותיה, ויש בהם ג' מדריגות יחידות עשירות מאות. א' <span data-k=\"sm\">[מאמת]</span> מאותיות יחידות, מ' מאותיות עשירות, ת' מאותיות מאות. והנה (ב') [ג'][ftnref_1_ל] אלו כ\"א כלול מכולם. כי הא' הראשון, <span data-k=\"sm\">[ודאי]</span> כולם נכללין בו <span data-k=\"sm\">[כיון]</span> שיצאו ממנו, והוא ראשית כולם. והסוף ג\"כ כלול מכולם, כי סוף מעשה במחשבה תחילה, וא\"כ מחשבת הסוף התהלכה בכולם, לכן היא כלולה מכולם, וגם אין להם שלימות זולת הסוף. והממוצע המחברם צריך להיות <span data-k=\"sm\">[ג\"כ]</span> כלול משניהם.\n<b>והנה</b> בחוש נראה כי ג' היסודות אש רוח מים מתנענעים. כי האש הוא השלהבת העליונה. ויסוד העפר הוא מונח במקום אחד לפי שהוא מקבל מהם. ולזה רמזו רז\"ל באשה קראו מושב, פירוש המקבל נקרא מוש\"ב שאין לו תנועה, ובאיש קראו מרכ\"ב, שהיסודות המה מורכבים כל א' כלול מכולם. והנה היסוד הד' הוא סוף מעשה במחשבה תחילה, והוא התכלית והשלימות, וזולתו לא היה עדיין שלימות לכל כיון שחסר התכלית. נמצא הוא משפיע שלימות לכל, וא\"כ וודאי שהוא כלול מכולם. ולכן נקרא ד', על שם הארבעה שנכללין בו. ובעשירות הוא מ', ובמאות הוא ת'. וזהו אמ\"ת, א' ריש דרגין, ומ' <span data-k=\"sm\">[ממוצע]</span>, ות' <span data-k=\"sm\">[בסוף]</span>. והנה המים מניחין מקום גבוה ויורדין למקום נמוך, ומדתם (הללו) [זו] נלקחה מהקדמות שקודם הויות <span data-k=\"sm\">[נ\"א: מהקדמות הקדום]</span>, <span data-k=\"sm\">[והוא הבורא ית'].</span> הנה הוא יתברך אין סוף לבדו, ועלה ברצונו (שנתהוה) [שיתהוו] העולמות וישרה שכינתו בהם כנודע, דאיהו ממלא כל עלמין ובלעדיו אין להם חיות כלל. זה היה אצלו יתברך צמצום כמו למים.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קיד (קכה). אוה\"א נא, א. שמועה טובה פג, א.</b>\n<i>תתן אמת ליעקב</i> – מיכה ז, כ.<i> חותמו של הקב\"ה אמ\"ת</i> – שבת נה, א. בר\"ר פא, ב.<i> אני ראשון ואני אחרון גו'</i> – ישעיה מד, ו.<i> א' ריש אתוון כו'</i> – בר\"ר פא, ב וש\"נ. תקו\"ז תס\"ג צד סע\"ב.<i> תלת עלמין אית ליה</i> – זח\"ג קנט, א.<i> באורייתא ברא כו'</i> – זח\"א ה, א.<i> כל א' כלול מכולם</i> – ראה זח\"א לג, א.<i> הא' הראשון כו'</i> – ראה זח\"ב רלד, ב.<i> סוף מעשה כו'</i> – פיוט לכה דודי. ראה זח\"ג רלב סע\"א. תקו\"ז ו, א.<i> באשה קראו מושב ובאיש כו'</i> – פסחים ג, א.<i> באשה . . המקבל</i> – תקו\"ז תנ\"ה פט סע\"א.<i> שהיסודות המה מורכבים כו'</i> – ראה זח\"א לא, א. זח\"ב כד, ב.<i> המים מניחין מקום גבוה כו'</i> – תענית ז, א.<i> דאיהו ממלא כו'</i> – זח\"ג רכה, א.\n----- שולי הגליון -----\n[ftn_1_ל]) <i>כן הוא במקבילות, וקאי על ג' אותיות אמ\"ת. ואולי כתב כאן ב' כדמבאר להלן באותיות א' ות', ורק אח\"כ מבאר דגם המ' צ\"ל כלול מכולם.</i>\n----- הערות וציונים -----\nראה סי' תיז.\n<i>תלת עלמין כו' ג' מדריגות כו'</i> – ראה סי' ר.\n<i>הא' הראשון כולם נכללין בו כו'</i> – ראה ריש סי' רמד ובהערות שם."]]],[400080389,"שכז\n\n<b>ויוציאנו</b> ה' ממצרים <span data-k=\"sm\">[וכו']</span>, זו גילוי שכינה. כי במלך שכולו טוב איך (נ\"א אי\"ן) שייך דין אצלו, אבל אם עושים כלום לבניו <span data-k=\"sm\">[מחמת אהבת בניו]</span> עושה דין. וזהו מ\"ש את היד הגדולה, אהבה, אשר עשה ה' במצרים, זהו דינים שבתוך האהבה, וזהו ביד חזקה, שבתוך אהבה. ובמורא גדול, <span data-k=\"sm\">[דיש לדקדק]</span> למה כתיב גדול, דהא <span data-k=\"sm\">[מורא הוא]</span> די\"ן נוקבא, והוה ליה למימר גדולה. אך כי כאשר היא בבית בעלה אינה בושה להיות תמיד עמו <span data-k=\"sm\">[ומגלות מדותיה]</span>. ולכך כתיב לשון זכר, להורות שהיא תמיד עם בעלה. וזהו גילוי שכינה, <span data-k=\"sm\">[ר\"ל]</span> שיש התגלות <span data-k=\"sm\">[המדות]</span> בשכינה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קכה (קלד). אוה\"א נד, ב.</b>\n<i>ויוציאנו ה' ממצרים [ביד חזקה ובזרוע נטויה ובמורא גדול]</i> – כי תבוא כו, ח.<i> [ובמורא גדול] זהו גילוי שכינה</i> – הגדה של פסח.<i> את היד הגדולה גו'</i> – בשלח יד, לא.<i> היד הגדולה אהבה</i> – ראה זח\"ג רכז, ב. שם רמו, ב. ראה תקו\"ז ה, א. שם ת\"ל עג, ב.<i> דינים . . ביד חזקה</i> – ראה זח\"ג רכז, ב. שם רמו, ב. ראה זח\"ב נט, ב.<i> די\"ן נוקבא</i> – זח\"ג יד, א.\n----- הערות וציונים -----\n<i>כי כאשר היא בבית בעלה כו' לשון זכר</i> – להעיר מריש סי' י ד\"ה והנה איתא ובמ\"מ שם."]]],[400080390,"שכח\n\n<b>הילוכך</b> תהא בנחת עונג קרא לשבת כדת נפש משיבת. משל למלך שהיו לו ב' בנים והיה אוהבם מאוד, ושלחם אל מדינת הים ללמוד דרך ארץ, ונתן להם הון רב על הדרך. ובאו עליהם ליסטים וגזלו מאתם כל אשר היה בידם. ובאו אל מדינה אחת שהפרנסה שם מצויה, וכל משא ומתן יכולים לעשות שם בריוח גדול על חד תלת, אך לא היה להם במה להתעסק שם. והיו חוטבין עצים, והיה להם למשל שכר לכ\"א ה' זהובים ליום, וצורך יציאתם[ftnref_1_לא] היה ג\"כ עשרה זהובים ליום. והנה אחד מהם היה חכם, והיה חושב מה יהיה התכלית והסוף כאשר אוציא כל שכרי על אכילתי, במה אבוא אל אבי המלך. מה עשה, היה מקמץ ומספיק את עצמו בזהוב אחד ליום, והיה יותר מקמץ עד שהרויח הרבה והיה לו סך גדול. ולא עוד, אלא שגם נעשה סוחר גדול בקי בכל משא ומתן בעולם, וקיבץ הון רב ועתיק. ואחיו הב' היה כסיל ואכל כל שכרו שהרויח, ולא היה בידו מאומה. והנה אחיו החכם, בראותו שאין לאחיו מאומה, היה חס עליו ונתן לו סך רב משלו שיעסוק גם הוא במשא ומתן. והלך הכסיל כדרכו והתחיל במשא ומתן גדול שלא בהדרגה, ומתוך שלא הורגל בשום משא ומתן תיכף במשא ומתן הראשון הפסיד הכל.\n<b>והנה</b> גם החכם לפעמים היה מפסיד במשא ומתן גדול. אך החכם, להיותו בקי בכל משא ומתן בעולם, כשראה שאינו מועיל משא ומתן הגדול התחיל במו\"מ הקטן, כי היה יודע בטוב העולם. אבל לא כן הכסיל. והנה החכם הנזכר כשהתחיל פעם ב' במו\"מ הקטן, הלך במדרגה כמו בראשונה והרויח הון רב. ואז עסק במו\"מ גדול כמו בראשונה, ויותר נתעשר כפלים מכמו שהיה. ובא אצל אביו עם הון עתיק ואבנים טובות ומרגליות, והיה לאביו שמחה גדולה עד מאוד, א' שהביא הון רב, ועוד יותר מזה שנתחכם בכל חכמות ובכל מו\"מ. אבל הבן הכסיל בא בעירום ובחוסר כל, כי כאשר הפסיק במשא ומתן הגדול לא הרויח מאז והלאה אף פרוטה אחת, כי לא היה בקי להתעסק מעט בהדרגה. וכשבא לפני המלך גירש אותו מפניו, ואמר לו ריקה היה לך ללמוד ממעשה אחיך החכם.\n<b>והנמשל,</b> הנשמה היא בן המלך, ושלח אותה לעוה\"ז עולם המעשה לסגל מצות ומעשים טובים. אך כשבא לעולם הזה נשכח ממנו מה שלמד בעולם הבא. ואחר כך כשהחכים הבין כי תאוות עוה\"ז אינו כלום נגד תענוג עוה\"ב, מה שהיתה רגילה להתענג בהיותה תחת כסא הכבוד. ומכח זה עזב תענוגי עולם הזה ואוכל רק כדי חיותו, והוגה בתורת ה' תמיד ועוסק במצות ובמע\"ט, ועולה ממדריגה למדריגה. ואח\"כ אפילו כשאירע לפעמים שהוא נופל ממנה, הוא עובד להשי\"ת במדריגה הקטנה, כי הוא בקי בכל דרכי עבודה אף כשהוא בעולם הקטנות. כי השי\"ת מנסה אותו בכל דרכיו ובכולם עמד, והולך ממדריגה למדריגה עד שהוא בא למדריגה עליונה יותר משהיה לו קודם <i>(חסר)</i>.",[["","","----- מקורות ומראה מקומות -----\n<i>הילוכך תהא בנחת כו'</i> – זמירות לשבת, מה ידידות מנוחתך.\n----- שולי הגליון -----\n[ftn_1_לא]) <i>כלומר לשניהם ביחד.</i>\n----- הערות וציונים -----\nראה סי' רה-א. וראה כש\"ט סי' קלט ובהערות שם. וכן שם סי' עז וקג."]]],[400080391,"שכט\n\n<b>לכו</b> ונלכה אל הר ה' וגו', לא כאברהם שקראו הר וכו'. הר הוא המשכה, מקום גבהות שנמשך מלמטה ממקום השוה. ופעולתו שנתרבה שטח הקרקע, וגם העומד עליו ניתוסף ראייתו שטח גדול, ורואה למרחוק. שדה הוא מקום מוכן לחרוש ולזרוע ונמשך ממנו פירות. בית הוא מקום שמתקנים בו הפירות. וכן בעת בריאת העולמות היה מוכרח להיות על ידי ג' אבות. תחילה נתעורר אהבה מלמטה למעלה, על דרך ישראל עלה במחשבה תחילה. ואח\"כ הוצרך להיות צמצום שיוכלו העולמות לסבול. ואח\"כ היה המשכה לתוך העולמות כנגד מדת יעקב. ואהבה ראשונה נקראת ה\"ר להיותה ממטה למעלה. ושד\"ה הוא מדת יצחק להיותו גבורות, ומבחינתו היהת השבירה בכדי להעלות <span data-k=\"sm\">[אחר כך]</span>, כמו השדה שזורעין בתוכה תחילה שתוציא אח\"כ פירות, על דרך לא גלו ישראל אלא בשביל להוסיף גרים. ואח\"כ על ידי שם מ\"ה, מדת יעקב, נתתקן כמו שנתתקן הכל בתוך הבית.\n<b>וכן</b> בעת שירצה לברר[ftnref_1_לב] הוא ג\"כ בבחינת כל הנזכר. כי תחילה נמשך אהבה והחשק מהמחשבה, ואח\"כ מתצמצם מה לדבר ומה שלא לדבר, ואח\"כ מתחבר אל הה' מוצאות הפה, מדת יעקב. והאותיות נקראים בתים, ע\"ד[ftnref_2_לג] והבית בהבנותו. ומדת יעקב (אינה) [היא] מקבלת גרים שהם מהשבירה, ובו לא היה שבירה ולא מיתה <span data-k=\"sm\">[נ\"א: כי בו לא היה שבירה, ועל כן לא מת]</span>. הגם שכתוב בספרים שגם בו היה שבירה, לאו מסטרא דיליה, כי מדתו שם מ\"ה המתקן הכל. על כן יאמרו הגרים נלכה אל ה\"ר ה', דהיינו אהבה הראשונה, ומאהבה הא' אל בית אלהי יעקב.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קכז (קלו). אוה\"א נה, א.</b>\n<i>לכו (ונלכה) [ונעלה] אל הר ה' גו'</i> – ישעיה ב, ג. מיכה ד, ב.<i> לא כאברהם כו'</i> – פסחים פח, א.<i> ישראל עלה במחשבה</i> – זח\"א כד, א. בר\"ר א, ד.<i> לא גלו ישראל כו'</i> – פסחים פז, ב.<i> שם מ\"ה מדת יעקב</i> – ראה זח\"ב קטו, ב. זח\"ג רכז, א.<i> ע\"י שם מ\"ה . . נתתקן</i> – ראה ע\"ח ש\"י פ\"א. שם שי\"ז פ\"ג.<i> והאותיות נקראים בתים</i> – ס\"י פ\"ד מי\"ב.<i> והבית בהבנתו</i> – מ\"א ו, ז.<i> ומדת יעקב [היא] מקבלת גרים</i> – (ראה בהערות).<i> ולא מיתה</i> – ראה תענית ה, ב.<i> ה\"ר ה' דהיינו אהבה הראשונה</i> – ראה זח\"ב סט סע\"ב. שם רנו סע\"ב.\n----- שולי הגליון -----\n[ftn_1_לב]) <i>על פי המשך הדברים אפשר שצ\"ל</i> לדבר.\n[ftn_2_לג]) <i>במדל\"י</i> ע\"ד שאמרו בזוהר, <i>וצ\"ע, ואולי ע\"פ המבואר שם זח\"א עד, א ועיי\"ש במפרשי הזוהר</i>.\n----- הערות וציונים -----\n<i>בעת בריאת העולמות היה מוכרח כו'</i> – ראה סי' ב.\n<i>ומדת יעקב היא מקבלת גרים</i> – להעיר מבר\"ר פד, ד. וראה לקו\"ת להאריז\"ל פ' מקץ ד\"ה לכו אל יוסף. ועיין בספר המקנה (מחברו היה תלמיד הרה\"מ) ריש פ\"ד דקידושין (סח, ב ד\"ה ויש לפרש דזה הוא שהתפלל יעקב כו', ושם ע, ב ד\"ה ואילו בגרים כתיב).\n<i>ובו לא היה שבירה כו' ועל כן לא מת</i> – ראה סי' תצט. וראה מאור עינים ליקוטים ד\"ה יעקב אבינו לא מת, ואמר מורי זללה\"ה שיעקב לא היה בשבירה דמאן דנחית מדרגיה קרי ביה וימת, והוא תיקן הכל, והענין בביאור היא כי ידוע כי יעקב סוד התורה וכתיב תורת ה' תמימה שאין בה שבירה וכו' עיי\"ש.\n<i>הגם שכתוב בספרים שגם בו היה שבירה</i> – ראה ע\"ח ש\"ט פ\"ב. ועיין לקו\"י יג, ג (סי' קנד) ובהערה הסמוכה.\n<i>לאו מסטרא דיליה</i> – עיין בהערות לסי' תצט ע\"פ המבואר בלקו\"י שם ובמדל\"י סי' רסה (רעג)."]]],[400080392,"של\n\n<b>אשריכם</b> זורעי על כל מים. ר\"ל בין בהרהורים טובים או בהפוכים הם עולים ומעלים לעבודת הבורא ית' כנודע ענינו. והנה הם באים מצד הסתכלות הנרמזת במלת שו\"ר, או מצד גסות החומר הנרמזת במלת והחמו\"ר. <span data-k=\"sm\">[וזהו משלחי רגל השור והחמור, ר\"ל ששולחים ההרגל שעל ידי שור וחמור].</span>",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קמא (קמט). אוה\"א ס, א.</b>\n<i>אשריכם זרעי גו' [משלחי רגל השור והחמור]</i> – ישעיה לב, כ.<i> הסתכלות הנרמזת במלת שו\"ר</i> – ע\"פ בלק כד, יז.<i> רגל . . ההרגל</i> – ראה לקו\"ת להאריז\"ל פ' שמות שלהי ד\"ה ויקם.\n----- הערות וציונים -----\n<i>הם באים מצד הסתכלות</i> – ראה במ\"ר י, ב העינים רואות והלב מהרהר.\n<i>הנרמזת במלת שור</i> – ראה סוף סי' מד וסי' תס.\n<i>ובהסתכלות חיוב</i> – ראה סי' רו.\n<i>גסות החומר הנרמזת במילת והחמו\"ר</i> – ראה חדושי אגדות למהר\"ל בכורות ה, ב. ובספרו גבורות ה' פכ\"ט.\n<i>רגל . . ההרגל</i> – ראה כש\"ט סי' נז וקמא."]]],[400080393,"שלא\n\n<b>או</b> יאמר, כי נודע אש ומים הם סוד חימום לדבר מצוה, והכל נכלל במים. וזהו זה לעומת זה וגו', מים מתוקים מים ארורים <i>חסר</i> כי מן המים משיתיהו, שהיה למעלה מן המים. בסוד מים מרומז מש\"ה מלגאו.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ס, ב.</b>\n<i>זה לעומת זה גו'</i> – קהלת ז, יד.<i> מים מתוקים מים ארורים</i> – ראה זח\"ב ו, ב. תקו\"ז ת\"ס צג, ב.<i> כי מן המים משיתהו</i> – שמות ב, י.<i> מש\"ה מלגאו</i> – ראה תקו\"ז תי\"ג כט, א.\n----- הערות וציונים -----\n<i>כי מן המים משיתיהו כו' משה מלגאו</i> – ראה מאור עינים ליקוטים ד\"ה נון שערי בינה נבראו. ולהעיר מגבורות ה' למהר\"ל פי\"ח."]]],[400080394,"שלב\n\n<b>ביום</b> ההוא אקים את סוכת דוד הנופלת. הנה מלת א\"ת (מיוחדת) [מיותרת], <span data-k=\"sm\">[מה באה לרבות]</span>. והנה נקדים משל. אחד הלך בדרך, ונאבד ממנו הדרך <span data-k=\"sm\">[שהוא רצה]</span>, והלך בדרך אחר והיה סבור שהוא הדרך הישר. ואח\"כ נודע לו שהוא תועה מדרך הישר, וביקש אותה ומצאה <span data-k=\"sm\">[והגיע אל מחוז חפצו]</span>. הנה[ftnref_1_לד] בעת מציאתו אותה היה לו תענוג גדול מן הדרך, שמצא הדרך הישר, משא\"כ קודם תעותו. ואע\"פ שהלך בדרך הישר לא היה לו תענוג מן הדרך עצמה, רק אחר כך בהגיעו אל מקום חפצו. והנה האב הרואה את בנו הולך בדרך הישר יש לו תענוג מהדרך עצמה. הגם שהבן לא תעה מעולם, ואז אין להבן תענוג, וזהו מחמת הבן ההולך לפי תומו ואינו יודע אם יש דרך עקלתון לתעות בה. אבל האב הרואה אותה וכמה בני אדם תעו בה, ובנו לא היה כאחד מהם, אז יש לו תענוג גדול. ואם הבן הלך ג\"כ בדרך עקלתון בתחילה ואח\"כ מצא הדרך הישר, שכבר יש להבן תענוג מן הדרך עצמה, אז ניתוספה גם להאב תענוג גדול יותר מבחלוקה הא'. והנה בחלוקה הב' תענוג האב והבן אחד הוא, שהוא מדרך עצמה, מה שאין כן בחלוקה הא' שתענוג האב מדרך עצמה משא\"כ הבן.\n<b>וזהו</b> שאמרנו למעלה כי ביום הכיפורים עוונות נמתקין בשורשם. כי נודע שהם עולמות עד אין מספר, ואלו אלף שנים יחיה לא יגיע עדיין למחוז חפצו. וכל התענוג <span data-k=\"sm\">[של הש\"י ב\"ה]</span> הוא במה (שהוא) [שהאדם] הולך בדרך הישר. אבל אימתי התענוג הזה לבן, אם תחילה עיקם הדרך. אבל כשהוא הולך בתומו שהוא צדיק מתחילה ועד סוף אזי אין לבן תענוג כל כך מהדרך. אלא הקב\"ה, שהוא אב, יש לו תענוג כביכול מהדרך עצמה שהבנים הולכים בדרך הישר, בין מן הצדיק שלא עיקם הדרך ובין מהבעל תשובה. אבל אעפ\"י שהבעל תשובה יש לו תענוג יותר כנזכר, והנה <span data-k=\"sm\">[נ\"א: אבל הבעל תשובה יש לו תענוג גדול יותר מהצדיק, כי]</span> כשהבעל תשובה עושה תשובה נכונה אזי הגיע לתענוג של הקב\"ה מן הדרך עצמה כנזכר. וזהו מ\"ש שהעוונות נמתקין בשורשם, דהיינו שמגיע בהם אל התענוג הא' עם השורש כביכול.\n<b>ונודע</b> מה שדרשו הדרדקי אלף בינה גמול דלים. אכן לפי זה הב' והד' הם נוקבין, כי הב' היא מקבלת מן הא', שהיא אל\"ף לשון לימוד, וכשהוא לומד הוא מבין על דרך יגעתי ומצאתי תאמין, נמצא כי הבינה היא מקבלת מן הלימוד והיא נוקבא אל הלימוד. והד' היא נוקבא על הג', כי הדל מקבל מן הגומל.\n<b>והנה</b> במשל הנזכר, כשהיה הבן תועה מדרך השכל לא היה חסר תענוג, כי היה מתענג בזה הדרך בחשבו שהיא הדרך הישרה, אך לא כל כך תענוג כהאב כנזכר. אך בעת ההוא היה חסר להאב תענוג גדול בידעו בתעות בנו. והנמשל מובן, כי אף שישראל <span data-k=\"sm\">[נ\"א: שאם ישראל]</span> הם ח\"ו בבחינת דלים אינם חסרים תענוג קצת בחשבם שזו הדרך הישרה, ע\"ד בכל מקום שגלו ישראל שכינה גלתה עמהם, אבל הקב\"ה כביכול אינו בתענוג עמהם והבן. ונודע כי תענוג היא נוקבא, שלא יכול להיות תענוג בלא דבר שקדמו, ולמשל אם הוא חכם ויש לו תענוג מחכמתו נמצא התענוג מקבל מהחכמה.\n<b>ונחזור</b> לענין כשישראל עושין רצונו של מקום מוסיפין תענוג למעלה, משא\"כ להיפוך ח\"ו, הגם שהם בעצמם אינם חסרים תענוג כנזכר. וזהו נשבע הקב\"ה שלא יכנס בירושלים של מעלה עד שיכנסו ישראל בירושלים של מטה <span data-k=\"sm\">[ודו\"ק]</span>. היינו שאין לו תענוג מהם כביכול מה שראוי לאב מהבן כמ\"ש בן חכם ישמח אב. ונודע כי התענוג שלמעלה נקרא בינה, וזהו ביוה\"כ שישראל עושים תשובה ומחזירים הכל לשורשו ומוסיפין תענוג למעלה, וגם הם עצמם מביאים תענוג שלהם שהיו <span data-k=\"sm\">[נ\"א: שהיה]</span> בבחינת דל\"ת עד עת מביאים אותו לשורשו, דהיינו שמתענגין תענוג אחד עם השורש כביכול שמצאו הדרך הנכונה. ועל כן <span data-k=\"sm\">[כתיב]</span> בו ב\"ד קודש ילבש, שנתחבר הב' עם הד', דהיינו ב' התענוגים של האב (עם הבן) [והבן] ושניהם יש להם תענוג אחד. ע\"כ ביוה\"כ אסור בתשמיש המטה, לפי שאין כאן <i>חסר</i> <span data-k=\"sm\">[במדל\"י: שאין כאן נוקבא]</span>, ומתענגים במה שלמעלה מהם והבן. ונודע כי התענוג העליון נקרא עלמא דאתכסיא, וכן במשל הנזכר שנעלמה ממנו הדרך והיה באתכסיא, ואח\"כ כשמצא הדרך <span data-k=\"sm\">[שנכנס, הוא בעלמא דאתכסיא, כי הדרך לא זזה ממקומה, אך הוא בא אליה בעלמא דאתכסיא, ודמטמרין מתגליין ליה]</span>, היינו שהוא נכנס אצלה ורואה אותה שם.\n<b>וז\"ש</b> ביום ההוא אקים, ולא פירש מה שיקים, דהיינו התענוג העליון כביכול, ולהיותה עלמא דאתכסיא לא פירש הכתוב רק דרך רמז. ואח\"כ אומר את סוכת וגו', וא\"ת הוא <span data-k=\"sm\">[לשון]</span> ע\"ם, והצעת הכתוב כך הוא: ביום ההוא אקים עלמא דאתכסיא עם סוכת, פי' דהיינו התענוג העליון עם התענוג הבנים יהיו אחד כנזכר <span data-k=\"sm\">[ודו\"ק]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קסא (קסט). אוה\"א סא, ב.</b>\n<i>ביום ההוא אקים גו'</i> – עמוס ט, יא.<i> וזהו שאמרנו למעלה</i> – לעיל סי' קצא.<i> אלף בינה גומל דלים</i> – שבת קד, א.<i> הם נוקבין</i> – ראה תקו\"ז תנ\"ה פט סע\"א.<i> יגעתי ומצאתי תאמין</i> – מגילה ו, ב.<i> בכל מקום שגלו כו'</i> – מגילה כט, א.<i> נשבע הקב\"ה כו'</i> – זח\"ג קמז, ס\"ב.<i> בן חכם ישמח אב</i> – משלי טו, כ.<i> התענוג שלמעלה נקרא בינה</i> – ראה זח\"א קנד, א.<i> וזהו ביוה\"כ כו'</i> – ראה זח\"ג טו, ב.<i> ב\"ד קודש ילבש</i> – אחרי טז, ד.<i> ביוה\"כ אסור כו'</i> – יומא ח, א.<i> עלמא דאתכסיא</i> – (בינה) זח\"א (ס\"ת) קנב סע\"א. שם קנד סע\"א.<i> ודמטמרין מתגליין ליה</i> – ע\"פ תרגום מקץ מא, מה.<i> וז\"ש ביום ההוא</i> – (בינה) זח\"א קנד רע\"ב. שם קעא, ב.\n----- שולי הגליון -----\n[ftn_1_לד]) הנה בעת . . מקום חפצו<i> ליכא במדל\"י</i>.\n----- הערות וציונים -----\n<i>נקדים משל כו'</i> – באורח לחיים פ' נצבים ד\"ה ושבת העתיק כ\"ז מס' מדל\"י בתוס' ביאור.\n<i>ביום הכפורים עוונות נמתקין בשורשם</i> – ראה ריש סי' קצא.\n<i>הב' היא מקבלת מן הא'</i> – ראה סי' תסג ובהערות שם.\n<i>אל\"ף לשון לימוד</i> – ע\"פ איוב לג, לג. וראה פרש\"י שבת קד, א ד\"ה אלף בינה.\n<i>התענוג של מעלה נקרא בינה</i> – להעיר מתקו\"ז תכ\"ד סט, ב.\n<i>וא\"ת הוא ע\"ם</i> – ראה פרש\"י בראשית ד, א ועוד."]]],[400080395,"שלג\n\n<b>והיה</b> בית עשו לקש. הנה אמרו רז\"ל כל מקום שנאמר והי\"ה הוא לשון שמחה, ולכאורה זו שיהיה בית עשו לקש, והלוא אין (בה) [בו] ניצוצות כלל כמו בדבר מאכל. אך (לזה) [זה] הקש ראוי כשתשרפנו ונעשה אפר ותשפוך האפר בשדה אז יגדיל צמחים, שיהיו ניצוצות קדושה בוודאי מהם. נמצא כי מקש נעשה גם כן ניצוצות קדושה כשהאדם אוכל מהם.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כח, ב. כתבי קודש ו, א.</b>\n<i>והיה בית עשו לקש</i> – עובדיה א, יח.<i> כל מקום שנאמר והיה כו'</i> – ויק\"ר יא, ז."]]],[400080396,"שלד\n\n<b>טעמה</b> כי טוב סחרה וגו'. יובן ע\"פ מה שאמרו רז\"ל וירא אלהים את האור כי טוב לגונזו לצדיקים לעתיד לבוא. והנה נאמר כי אין מחסור ליראיו וגו' ודורשי ה' (וגו') [לא יחסרו כל טוב]. נמצא כי מי שיש לו מדת היראה אינו חסר מכל טוב. והטעם מפני שהוא מושרש במדת יראה הנקרא (אשת חיל) [אשה] יראת ה'. והמדה הנזכרת נקראת אוצר בית ה' <span data-k=\"sm\">[כמ\"ש יראת ה' היא אוצרו]</span>, ושם הוא גנוז הטוב <span data-k=\"sm\">[נ\"א: ובאוצר גונזין כל טוב]</span>, ולכן אין מחסור ליראיו. וזהו טעמה, פירוש החזיקו במדת היראה <span data-k=\"sm\">[וטעמו אותה]</span>, ותזכו לטובה הגנוז שם. וזהו כי טוב סחר\"ה, פירוש מסבבת וסוחרת, כי טוב הגנוז בתוכה <span data-k=\"sm\">[נ\"א: וסוחרת טוב הגנוז בתוכה]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י ריש סי' קפח (קצה). אוה\"א עא, ב.</b>\n<i>טעמה כי טוב סחרה גו'</i> – משלי לא, יח.<i> שאמרו רז\"ל וירא כו'</i> – חגיגה יב, א.<i> וירא אלקים את האור גו'</i> – בראשית א, ד.<i> טוב לגונזו</i> – זח\"א מה, ב.<i> כי אין מחסור ליראיו</i> – תהלים לד, י.<i> ודורשי ה' גו'</i> – שם יא.<i> אשה יראת ה'</i> – משלי לא, ל.<i> אוצר בית ה'</i> – יהושע ו, כד.<i> יראת ה' היא אוצרו</i> – ישעיה לג, ו. ראה תקו\"ז תכ\"ח עב, ב.<i> סחרה פי' מסבבת</i> – ע\"פ שבת יג סע\"א.\n----- הערות וציונים -----\n<i>ותזכו לטובה הגנוז שם</i> – להעיר מזח\"א ח רע\"א."]]],[400080397,"שלה\n\n<b>לא</b> תירא לביתה משלג. <span data-k=\"sm\">[איתא בזוהר דמנה דינין מתערין. פי']</span> אי\"ק בכ\"ר גל\"ש וכו', והנה בכ\"ר הוא שני לאי\"ק, ונקרא בכ\"ר לשון ראשון, על שם ראשית חכמה <span data-k=\"sm\">[יראת ה']</span>, שהוא ראשון במספר. והראשון שבכולם <span data-k=\"sm\">[לית מחשבה תפיסא בה כלל ו]</span>אינו בכלל מספר כידוע. לכך השני נקרא בכ\"ר <span data-k=\"sm\">[שהוא בכר לאביו].</span> ועל כן הם אותיות שניות ביחידות ובעשירות ובמאות, שהוא משנה למלך המחבר המלך והעם. כי לפני הב' היא א', מלך שאין לו תפיסה, כי לפני א' מה אתה סופר. ואחר אותיות בכ\"ר הם אותיות גל\"ש, שהוא שג\"ל נוקבא, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סוף סי' קפח (קצו). אוה\"א עא, ב.</b>\n<i>לא תירא לביתה משלג</i> – משלי לא, כא.<i> איתא בזוהר כו'</i> – זח\"ג י סע\"ב. זח\"א קנא, א. זח\"ג סה, א. וראה זח\"ג סד סע\"א<i> אי\"ק בכ\"ר גל\"ש</i> – ראה זו\"ח אחרי מח, ג. פרדס רמונים שכ\"ג פ\"א ערך אי\"ק. ע\"ח שכ\"ד פ\"ו.<i> ראשית חכמה</i> – תהלים קיא, י.<i> והראשון שבכולם אינו בכלל מספר</i> – זח\"א לא רע\"ב.<i> השני נקרא בכ\"ר</i> – (חכמה) תקו\"ז תי\"ד ל, א.<i> א' מלך כו'</i> – (כתר) תקו\"ז תמ\"ב פא, ב. שם ת\"ע קטו, א.<i> לפני א' מה אתה סופר</i> – ס\"י פ\"א מ\"ז.\n----- הערות וציונים -----\nראה סי' כז וסי' נג, ובהערות שם."]]],[400080398,"שלו\n\n<b>פירוש</b> הפסוק כי שבע יפול צדיק וקם. ר\"ל כי האדם צריך לילך בכל הז' מדות של השבירה ולהעלות משם ניצוצות, ומחמת זה יש לאדם זה עלייה גדולה. וזהו שכתוב וקם.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י לא, ד (סי' רנג). אוה\"א עד, א.</b>\n<i>כי שבע יפול צדיק וקם</i> – משלי כד, טז.\n----- הערות וציונים -----\nראה סי' רמח ד\"ה והנה כשהצדיק. ועיין סי' תנא ובהערות שם."]]],[400080399,"שלז\n\n<b>רמז</b> הפסוק וללו\"י אמר. פי' וללוי, אדם שהוא דבוק בהשם יתברך, אמ\"ר, פירוש השם יתברך <span data-k=\"sm\">[בעצמו]</span> אומר לו התורה, ואינו צריך ליגע הרבה בעצמו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י לא, ד (סי' רנד). אוה\"א עד, ב.</b>\n<i>וללו\"י אמר</i> – ברכה לג, ח.<i> וללוי . . שהוא דבוק</i> – ע\"פ ויצא כט, לד ותיב\"ע שם.\n----- הערות וציונים -----\nשייך לרמזי תורה פ' ברכה.\nלהעיר מברכות לב, ב מתוך שחסידים הם כו', והגירסא שניה בירושלמי שם פ\"ה ה\"א ע\"י שהיו חסידים כו'."]]],[400080400,"שלח\n\n<b>איש</b> אזור עור אזור במתניו. על פי מ\"ש רז\"ל בתורתו של רבי מאיר היה כתוב כתנות או\"ר באל\"ף, לפי שרבי מאיר היה מאיר עיני חכמים בהלכה, ולא היה בתורתו בחינת עו\"ר כידוע. ובאליהו לא היה גם כן בחינת עו\"ר, כי היה זך ומזוכך, וזהו אזור עור וכו', ר\"ל שלא היה לו רק חגורה של עור, אבל בגוף לא היה בחינת עור, רק בחינת אור זך ובהיר.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י לא, ג (סי' רמז) אוה\"א עה, ב.</b>\n<i>איש בעל שער ואזור עור אזור במתניו</i> – מ\"ב א, ח.<i> בתורתו של ר\"מ כו'</i> – בר\"ר כ, יב.<i> שר\"מ היה מאיר כו'</i> – עירובין יג, ב.<i> ובאליהו . . כי היה זך ומזוכך</i> – ראה רמב\"ן אחרי יח, ד. ע\"ח של\"ט שלהי פ\"א.\n----- הערות וציונים -----\n<i>בתורתו של ר\"מ כו'</i> – ראה סי' ה ובהערות שם.\n<i>ובאליהו . . זך ומזוכך כו'</i> – ראה כש\"ט סי' שנו ובהערות שם מע\"ח של\"ט פ\"א."]]],[400080401,"שלט\n\n<b>עד</b> מתי עצל תשכב. ר\"ל שיש כמה בני אדם שיושבים <span data-k=\"sm\">[ועוסקים]</span> ושונים כל היום מעוטפים בטלית ותפילין, אך הוא רק מצות אנשים מלומדה, ואינו יודע עיקר העבדות. וזה כמעט גרוע מבעל עבירה. כי בעל העבירה פתאום יכול לבוא לו התעוררות גדולה ויעשה תשובה גמורה, ויתחרט על העבירות שעבר, ויעבוד להשי\"ת בעבודה גמורה ובהתלהבות גדולה. אבל זה האדם אשר הוא צדיק בעיניו, ודומה לו כאלו עשה כל העבודה המוטלת עליו, וזה האדם לא יכול לבוא לעולם לידי מדריגה גדולה וטובה, כי הוא חושב שעבודתו הוא בשלימות, ובאמת הוא רחוק מאתו יתברך ומעבודתו כרחוק מזרח ממערב. <i>חסר הסיום.</i>",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י לא, ב (סי' רמה). אוה\"א עו, א.</b>\n<i>עד מתי עצל תשכב</i> – משלי ו, ט.<i> מצות אנשים מלומדה</i> – ע\"פ ישעיה כט, יג.\n----- הערות וציונים -----\nראה לעיל סי' קפט וסי' רכב, ובהערות שם."]]],[400080402,"שמ\n\n<b>שרפים</b> עומדים ממעל לו. פירוש <span data-k=\"sm\">[שרפים עומדים]</span> הם הצדיקים שבוער בלבם אהבת הבורא יתברך, הוא מחמת שממעל לו, על דרך דע מה למעלה – ממך תדע. כי האדם הוא חלק אלוה ממעל, וכשהוא מדבק מחשבתו למעלה יכול לידע מה שנעשה למעלה, כי כל הדברים הנעשים למעלה עוברים במחשבתו, כמ\"ש רשב\"י ע\"ה אנא סימנא בעלמא. פירוש כל המדות שמתעוררים למעלה הם מתעוררים למטה בצדיק. וזהו פירוש שרפים עומדים ממעל לו[ftnref_1_לה].",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י יז, ד (סי' רכט). אוה\"א עז, ב. לקו\"א מא, א.</b>\n<i>שרפים עומדים ממעל לו</i> – ישעיה ו, ב.<i> דע מה למעלה ממך</i> – אבות פ\"ב מ\"א.<i> חלק אלוה ממעל</i> – איוב לא, ב.<i> אנא סימנא בעלמא</i> – זח\"א רכה, א.\n----- שולי הגליון -----\n[ftn_1_לה]) <i>ראה לעיל סי' ש נ\"א לסימן זה</i>.\n----- הערות וציונים -----\nלעיל סי' ש באו\"א."]]],[400080403,"שמא\n\n<b>בשתים</b> יכסה פניו. פירוש בשתים, באהבה ויראה, והם ב' כנפים שמגביהים המצות למעלה, יכסה פניו, פירוש עושה מלבושים לפנימיות, והוא מדריגות גדולות כי הוא יודע פנימיות של כל הדברים.\n<b>ויש</b> מדריגה אחת שאינו יודע בפנימיות, רק הוא עושה דבר מחמת האמונה, והוא מדריגה קטנה. והוא מדריגת רגלים, כי הם העמדה של הדבר. אם כן כשהוא עושה מצות הוא עושה מלבוש לבחינת הרגלים, שהם נצח והוד.\n<b>ויש</b> מדריגה אחרת, והיא בחינת עיבור, שאין לו האמונה ברובה[ftnref_1_לו] רק הוא משתוקק לזה. והוא פירוש בשתים יעופף[ftnref_2_לז].",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י יז, ד (סי' רל). אוה\"א עז, ב. לקו\"א מא, א.</b>\n<i>בשתים יכסה פניו</i> – ישעיה ו, ב.<i> באהבה ויראה והם ב' כנפים</i> – תקו\"ז ת\"י כה, ב.<i> הרגלים שהם נו\"ה</i> – ראה תקו\"ז יז, א.\n----- שולי הגליון -----\n[ftn_1_לו]) <i>בלקו\"י:</i> האמונה בתוכה, <i>ונראה שצ\"ל בתוכו</i>.\n[ftn_2_לז]) <i>לעיל סי' שא נ\"א לסימן זה.</i>\n----- הערות וציונים -----\nראה לעיל סי' שא ובהערות שם."]]],[400080404,"שמב\n\n<b>מלא</b> כל הארץ כבודו. פירוש <span data-k=\"sm\">[כבודו מ]</span>לשון לבוש, כמו ותחת כבודו ייקד וגו'. ור\"ל שהשי\"ת כביכול מלובש אפילו בכל הגשמיות. וזהו מלא כל הארץ כבודו, אפילו בגשמיות כבוד ה', <span data-k=\"sm\">[פירוש]</span> לבושו, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י יז, ג (סי' רכב). אוה\"א עז, ב.</b>\n<i>מלא כל הארץ כבודו</i> – ישעיה ו, ג.<i> ותחת כבודו ייקד גו'</i> – ישעיה י, טז. ראה פרש\"י שם ע\"פ שבת קיג סע\"א.\n----- הערות וציונים -----\n<i>מלובש אפילו בכל הגשמיות כו'</i> – ראה סי' רלט ובהערות שם. רג\"כ סוף סי' תלד."]]],[400080405,"שמג\n\n<b>צדיק</b> מושל (ב)יראת אלהים, פירוש מושל במלכות. כי האדם שהוא צדיק נקרא כביכול בעלה דמטרוניתא, וזה סוד משה איש האלהים, וד\"ל.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י יח, א (סי' רלג). אוה\"א עח, א.</b>\n<i>צדיק מושל יראת אלקים</i> – ש\"ב כג, ג.<i> במלכות</i> – תקו\"ז ו, א. שם תל\"ג עז רע\"א. זח\"ג קח, א.<i> האדם שהוא צדיק כו' בעלה דמטרוניתא כו'</i> – ע\"ח שמ\"ב (שער כללות אבי\"ע) פ\"ד. שער הגלגולים הקדמה יח.<i> וזה סוד משה איש האלקים</i> – שם. ראה זח\"א רלו, ב.<i> משה איש האלקים</i> – ברכה לג, א.\n----- הערות וציונים -----\n<i>בעלה דמטרוניתא</i> – יראת אלקים דא מלכות, כנסמן במ\"מ, ודא מטרוניתא (זח\"ג בר\"מ כ, א) דאיהי שכינתא (זח\"ג רל, א)."]]],[400080406,"שדמ\n\n<b>לשמרך</b> מאשה זרה. פירוש הקליפה נקראת אשה זרה, שהם מצפים לינוק מאדם שיעשה עבירה ויהיה להם חיות ממנה. לכך נקראת אשה זרה, שהיא מקבלת חיות ממנה. וכתיב אשה יראת ה', שהיא הקדושה שמצפה גם כן לאדם (כביכול) [כדי] שתקבל ממנו חיות מן המצות שיעשה. והחילוק שבין זו לזו, כי בקדושה יש <span data-k=\"sm\">[בו]</span> דכר ונוקבא, כי הקדושה נותן לו כח לעשות מצות, ומצפה לקבל הארה ממנו, אבל הקליפה היא מקבלת ואינה נותנת.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י יז, ג (סי' רכה). אוה\"א עח, א.</b>\n<i>לשמרך מאשה זרה</i> – משלי ז, ה.<i> הקליפה נקראת אשה זרה</i> – זח\"א קכב סע\"א. שם קעב, ב.<i> אשה יראת ה'</i> – משלי לא, ל.<i> הקליפה היא מקבלת</i> – ראה זח\"ב קכח, א.\n----- הערות וציונים -----\nעיין סי' תו ד\"ה האומר."]]],[400080407,"שמה\n\n<b>לך</b> אל נמלה עצל וגו' (אוגר) [תכין] בקיץ לחמה וגו'. רמז הוא אל האדם, כמו שנמלה אין לה מושל ושוטר, כן יש ב' מיני אדם. א' הוא רשע כל ימיו, כמו הנמלה שאין לה שום היכר גדלות הבורא ית'. והמין הב' הוא אשר הולך בדרכי השי\"ת, אך לפעמים נופל ממדריגתו. והחילוק אשר ביניהם הוא זה, הא' חושך <span data-k=\"sm\">[לו]</span> ולא אור כל ימיו. והב' כאשר יתחזק ויכיר חסרונו, יגביר היצר טוב על היצר הרע כפלים מבתחילה. והמשל הוא לשדה, פעמים היא כחושה ואינה עושה פירות כל כך, מניחין אותה בורה כדי שיתחזק כוחה.\n<b>וזהו</b> פירוש אוגר בקיץ. קי\"ץ הוא לשון בו\"ר, כמו קי\"ץ למזבח, וזה האדם שהוא אוגר, ר\"ל מאסף בקיץ, בזה עצמו שהוא בטל ובור מעבודת הבורא ית', כדי שיתחזק אחר כך, הוא בן משכיל.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י טז, ב (סי' רד). אוה\"א פא, א.</b>\n<i>לך אל נמלה עצל גו' אשר אין לה קצין שוטר ומושל תכין בקיץ לחמה</i> – משלי ו, ו.<i> אוגר בקיץ בן משכיל</i> – משלי י, ה.<i> קי\"ץ למזבח</i> – שקלים פ\"ד מ\"ד וראה פי' הר\"ב שם.\n----- הערות וציונים -----\n<i>והמשל הוא כו' מניחין אותה בורה כו'</i> – להעיר מכש\"ט סי' לד, קכא, קעח."]]],[400080408,"שמו\n\n<b>ופרוס</b> <span data-k=\"sm\">[עלינו]</span> סוכת שלום. הכוונה הוא <span data-k=\"sm\">[דרך משל]</span>, אם יש לאדם תענוג מהאב, וחפץ האב להיות לבנו תענוג יותר[ftnref_1_לח], אזי אין הבן יכול לקבל זה התענוג. כן בשבת התענוג מתפשט, אזי אנו מתפללים שנוכל לקבל התענוג, דהיינו צמצום שיצמצם עצמו שיתפשט ברוחב ולא שירד. ועיין הכוונה במשנת חסידים.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כ, ב. כתבי קודש ל, ד.</b>\n<i>ופרוס עלינו סוכת שלום</i> – תפילת השכיבנו בערבית.<i> הכוונה במשנת חסידים</i> – שם מס' ערבית לשבת ספ\"ב. שם פ\"ג א-ז.\n----- שולי הגליון -----\n[ftn_1_לח]) <i>בכתבי קודש:</i> כשאדם רוצה להיות לו תענוג (יותר מבנו) [יורד לבנו].\n----- הערות וציונים -----\n<i>בשבת התענוג מתפשט</i> – להעיר משבת קיח, א (נחלה בלי מצרים), ומאור עינים ר\"פ ויקהל. וראה זח\"א מח, א."]]],[400080409,"שמז\n\n<b>הוא</b> אמר ויהי. אמ\"ר הוא לשון לבוש, כמו בצע אמר\"תו, ויה\"י, כל מקום שנאמר ויה\"י אינו אלא לשון צרה. ר\"ל האין סוף רצה להלביש את עצמו כדי שנקבל טובו <span data-k=\"sm\">[ובהירתו]</span>, היה צריך ויה\"י, צמצום, ואח\"כ פירוש מלבוש, לבושי מדע.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כא, ב. כתבי קודש לא, ב.</b>\n<i>הוא אמר ויהי</i> – תהלים לג, ט.<i> בצע אמר\"תו</i> – איכה ב, יז.<i> כל מקום שנאמר ויה\"י כו'</i> – מגילה י, ב. ויק\"ר יא, ז.\n----- הערות וציונים -----\nשייך לחלק תהלים.\nבכתבי קודש: בשם אלקי רב ב\"ש. וצ\"ע אי קאי על הבעש\"ט או הרה\"מ. ראה במבוא הערה 5.\n<i>ויהי כל מקום כו' ר\"ל כו'</i> – ראה סוף סי' ב (ד\"ה ואפשר) ובהערות שם.\n<i>כדי שנקבל טובו ובהירתו</i> – ראה ע\"ח ש\"א סוף ענף ג. וראה לעיל סוף סי' קפג וסי' שנח."]]],[400080410,"שמח\n\n<b>והחכמה</b> מאין תמצא. ר\"ל מי שעושה עצמו כאי\"ן הוא דבוק באי\"ן העליון, והאי\"ן משפיע לי\"ש והוא חכמה. וזהו חכם מ\"ה הוא אומר, ר\"ל <span data-k=\"sm\">[אומר]</span> מה הוא, ר\"ל שאינו בעיניו לכלום, ומזה משיג החכמה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כא, ב. כתבי קודש ל, ב.</b>\n<i>והחכמה מאין תמצא</i> – איוב כח, יב.<i> והאי\"ן משפיע לי\"ש והוא חכמה</i> – ראה בהערות.<i> חכם מ\"ה הוא אומר</i> – הגדה של פסח.\n----- הערות וציונים -----\nבשמועה טובה נז, א בקיצור: החכמה מאין תמצא, ר\"ל מי שהוא בעיני עצמו כאין אז ישיג השגת חכמה עליונה.\n<i>ר\"ל מי שעושה עצמו כאי\"ן כו'</i> – ראה סוטה כא, ב. וראה סי' שכג ד\"ה ונחזור, וסי' שפז-ג.\n<i>הוא דבוק באי\"ן העליון</i> – ראה סי' רצו.\n<i>לי\"ש והוא חכמה</i> – ראה סי' צה ד\"ה ויובן. סי' קיח ד\"ה והנה מקובל. סי' שנא. ועיין בהערות לסי' א ד\"ה החכמה.\n<i>ומזה משיג החכמה</i> – ראה סי' צז ד\"ה וזהו. סי' שנא. רג\"כ סי' רעז-א ד\"ה וזהו. סי' שע."]]],[400080411,"שמט\n\n<b>כע\"ס</b> בחיק כסילים ינוח. הטעם דהכ' מרמז על הכתר. והע' היא מרמז על אם הבנים, לכן היא גי' ע' שהוא כולל כל הז' מדות. והס' הם ששה מדות. ומדת חכמה ליכא, שאם הוא כועס מסתמא הוא אומר שהוא י\"ש, אבל החכמה מאי\"ן תמצא.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כא, ב. כתבי קודש ל, ב.</b>\n<i>כע\"ס בחיק כסילים ינוח</i> – קהלת ז, ט.<i> דהכ' מרמז על הכתר</i> – זח\"ג רנה, ב. רמג רע\"א. רמז רע\"א. רפ, ב.<i> אם הבנים</i> – תהלים קיג, ט. (שהיא בינה, זח\"א קנד, א. פרדס רמונים שכ\"ג פ\"א ערך אם. פע\"ח שער נפילת אפים פ\"ה).<i> והס' הם ששה מדות</i> – פע\"ח שער הזמירות פ\"ד. שם שער חג המצות פ\"ז.<i> ומדת חכמה ליכא כו'</i> – ראה פסחים סו, ב.<i> החכמה מאי\"ן תמצא</i> – איוב כח, יב.\n----- הערות וציונים -----\n<i>שאם הוא כועס מסתמא כו'</i> – ראה שערי קדושה להרח\"ו ח\"א ש\"ב. להעיר מתניא, אגה\"ק ריש סי' כה.\n<i>החכמה מאין תמצא</i> – ראה סי' שמח."]]],[400080412,"שנ\n\n<b>בדעתו</b> תהומות נבקעו. ר\"ל כי ההבנה הוא מה שמבין דבר מתוך דבר, ודעת הוא אחר השכל וההבנה, כי כבר יוד\"ע כדת מה לעשות. ובזה הדעת נגלים הב' מוחין שלמעלה, והב' מוחין נקראים תהומות, ובזה נבקעו, ר\"ל נתגלו. וזהו בד\"עתו תה\"ומות נבקעו כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כג, ב. כתבי קודש לא, ג.</b>\n<i>בדעתו תהומות נבקעו</i> – משלי ג, כ.<i> ההבנה . . שמבין דבר מתוך דבר</i> – חגיגה יד, א. זח\"ב רעו, ב.<i> וזהו בד\"עתו כו'</i> – ראה זח\"ג רפט סע\"ב.\n----- הערות וציונים -----\n<i>ודעת הוא אחר השכל וההבנה</i> – ראה שערי אורה להרי\"ג ש\"ה (ערך דעת).\n<i>ובזה הדעת נגלים הב' מוחין שלמעלה</i> – להעיר משער מאמרי רשב\"י, שלהי ביאור פ\"ק דסד\"צ (קלז, א-ב)."]]],[400080413,"שנא\n\n<b>(ו)החכמה</b> תחיה (את) בעליה. כי אין להשיג החכמה אלא אם כן עשה עצמו כאי\"ן מוחלט, ואז הקב\"ה שולח לו חיות מכח החכמה שהוא כנגד חיה. והחכמה נקרא י\"ש, ובמה יש התחברות י\"ש באי\"ן. על כרחך יש איזה ממוצע ביניהם ואיזה התקשרות נעלם. וזהו <span data-k=\"sm\">[סוד]</span> הצירוף של אר\"ץ, הא' הוא מרומז על אי\"ן, והר' על ריש דרגין, והתחברות הוא ע\"י צדיק.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כג, ב. כתבי קודש לא, ג.</b>\n<i>החכמה תחיה בעליה</i> – קהלת ז, יב.<i> החכמה שהוא כנגד חיה</i> – ראה זח\"א (ס\"ת) עט סע\"ב. פע\"ח שער ר\"ח פ\"ג. לקו\"ת-טעה\"מ ריש פ' מצורע.<i> והחכמה נקרא י\"ש</i> – זח\"ג רלט, א. שם רנז, ב.<i> והתחברות הוא ע\"י צדיק</i> – ראה זח\"א לא סע\"א.\n----- הערות וציונים -----\nראה סי' שמח ובהערות שם."]]],[400080414,"שנב\n\n<b>טוב</b> (עבד נקלה) [נקלה ועבד לו] ממתכבד וחסר לחם. פי' כי אין סימן לעבודת השם רק אם יודע בעצמו כי נקלה הוא בפני עצמו, אז הוא במדריגה, ואז עבד לו יתברך, ממתכבד, בפני עצמו, וחסר לחם, דהיינו השפע[ftnref_1_לט].",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כח, א. כתבי קודש לב, ד. צוה\"ר סי' קיד.</b>\n<i>טוב נקלה ועבד לו גו'</i> – משלי יב, ט.<i> לחם דהיינו השפע</i> – ראה פרדס רמונים שכ\"ג פי\"ב ערך לחם.\n----- שולי הגליון -----\n[ftn_1_לט]) <i>באוה\"א מד, א נ\"א:</i> טוב נקלה ועבד לו ממתכבד וחסר לחם. על דרך מה דאיתא בזוהר (זח\"א קסו, ב) אמונה דא לחם, כד\"א לחם אלהיו הוא אוכל. כי אין סימן לעבודת הבורא ית' רק אם יודע אדם ערכו שהוא נקלה וחסר אמונה, והוא עבד לו ית'. משא\"כ להיפך ח\"ו, שהוא בעצמו מתכבד. וזה פי' הפסוק, טוב עבד, שהוא עובד ע\"י שנקלה הוא בעצמו, ממתכבד בעצמו, וחסר לחם, בוודאי הוא מחוסר אמונה. כי אם היה מאמין באמת, בוודאי היה רואה בעצמו שפלותו וחסרונו כנ\"ל.\n----- הערות וציונים -----\nלהעיר מפירוש הפסוק בזח\"א קסו רע\"ב (הובא בר\"ח שער הענוה רפ\"ז).\n<i>אין סימן לעבודת ה' רק כו'</i> – ראה סי' קפט. ורג\"כ סי' שעג וסי' שצד."]]],[400080415,"שנג\n\n<b>אלה\"י</b> אברהם אלה\"י יצחק ו\"אלהי יעקב בוי\"ו. כידוע האב מתפאר בבן <span data-k=\"sm\">[בב' בחינות]</span>. בחינה א' מתפאר האב במה שהבן יש לו אהבה כל כך להאב, וזהו <span data-k=\"sm\">[נקרא]</span> אלה\"י אברהם, שהיה עובד את השי\"ת באהבה יותר מכל החיים <span data-k=\"sm\">[נ\"א חשק]</span>. ובחינה אחרת יש שהאב מתפאר שהבן יש לו יראה ממנו, ויש לו שכל גדול בזו היראה, וזהו <span data-k=\"sm\">[מש\"כ]</span> הן יראת ה' היא חכמה, וזהו אלהי יצחק שעבודתו להבורא היתה בזה המדריגה. ויש בחינה פשוטה שהבן עובד להאב באהבה ויראה ובכל <span data-k=\"sm\">[נ\"א: מכל]</span> מה שיבוא לידו, והעיקר שהאב יתפאר בו <span data-k=\"sm\">[וזה כל כוונתו]</span>, וזהו ואלהי יעקב, <span data-k=\"sm\">[שיעבוד את ה' כיעקב],</span> ר\"ל זה וזה נכלל ביעקב, האל הגדול הגבור והנורא וכו', השבח <span data-k=\"sm\">[הזה]</span> הוא בשכל.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א כח, ב. כתבי קודש יח, ב.</b>\n<i>אלה\"י אברהם כו'</i> – ריש העמידה (וכן הוא בשמות ג, ו וטו, שם ד, ה).<i> בוי\"ו כידוע</i> – ראה זח\"ב כו, א. רבנו בחיי שמות ג, טו. פע\"ח שער העמידה פי\"א.<i> אברהם שהיה עובד כו'</i> – ראה זח\"א קיב סע\"ב. זח\"ג רסז, א.<i> הן יראת ה' גו'</i> – איוב כח, כח.<i> יצחק שעבודתו כו'</i> – ראה זח\"א פז, ב. תקו\"ז ת\"ע קכב, א. שם קכה רע\"ב.<i> זה וזה נכלל ביעקב כו'</i> – ראה זח\"א צו, א. שם קמו רע\"א. ושם קסט רע\"א.<i> האל הגדול כו'</i> – ריש העמידה ע\"פ עקב י, יז. ראה זח\"ב עח סע\"ב. תקו\"ז ת\"ע קכג, א.\n----- הערות וציונים -----\nראה סי' רנה. ועיין תהלים – יהל אור להצ\"צ לתהלים קמה, ו.\n<i>הגדול הגבור והנורא</i> – חג\"ת, אברהם יצחק ויעקב, ראה תקו\"ז ת\"ע קכג סע\"א. וראה זח\"ג לא, א וזח\"ב עט רע\"א.\n<i>השבח הזה הוא בשכל</i> – ראה ריש סי' רנה (יעקב ראה בעין השכל), וראה שם בהערות."]]],[400080416,"שנד\n\n<b>עקב</b> ענוה יראת ה'. ר\"ל ענוה היא עקב של יראת ה', כי היא אחר היראה הרוממות, כי אינה יכולה להיות בתמידות, רק כל דבר שבקדושה אחר שמסתלק נשאר שם רושם, והוא רשימו. נמצא כי הענוה אחר היראה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לב, א.</b>\n<i>עקב ענוה יראת ה'</i> – משלי כב, ד.<i> ענוה . . אחר היראה הרוממות</i> – ראה זח\"ג קמה סע\"א. תקו\"ז ה, ב. ר\"ח שער האהבה פי\"א.<i> כל דבר שבקדושה כו'</i> – פרדס רמונים שי\"ד פ\"א. ע\"ח של\"ד פ\"ג. שם ש\"ד ספ\"ג. שמ\"ז פ\"ו. של\"ה, תול\"א בית ה' ד\"ה ואז יתברר.\n----- הערות וציונים -----\nראה סי' תיד. וראה תקו\"ז ה, ב."]]],[400080417,"שנה\n\n<b>(ותפארתך)</b> [ותפארתו] עבור על פשע. ר\"ל כי כמו שהתינוק אשר אוחז בזקן האב, אף על פי שאין זה דרך ארץ, אפילו הכי יש להאב התפארות מזה הדבר בעצמו <span data-k=\"sm\">[נ\"א: יש להאב תענוג מזה הדבר בעצמו ומתפאר]</span>. וידוע כי האין סוף ב\"ה כולו טוב, (ומחשבות) [ומחשבתו] הקדושה הוא בטוב. רק כשמוחל עונות בישראל <span data-k=\"sm\">[נ\"א: בית ישראל]</span> אזי במחשבתו הקדושה <span data-k=\"sm\">[זה העון]</span> ומתלבש מחשבתו בזה העוון ומוחל לו. אף על פי שאין זה דרך ארץ מהבן שבעבורו יתלבש האב בזו המחשבה, אפילו הכי, תפארתך, ר\"ל התפארות, הוא אצלך עבור על פשע, כשאתה (מתלבש) [מלביש] מחשבתך בפשע, ונושא עון, פירוש העוון הוא נושא <span data-k=\"sm\">[לך]</span> כביכול.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לא, ב.</b>\n<i>ותפארתו עבר על פשע</i> – משלי יט, יא.<i> נושא עון ועובר על פשע</i> – מיכה ז, יח.\n----- הערות וציונים -----\nראה סי' תנו ד\"ה ונחזור.\n<i>העוון הוא נושא</i> – ראה בהערות לסי' קז ד\"ה המדה."]]],[400080418,"שנו\n\n<b>זכרתי</b> לך חסד נעוריך. פי' אעשה לך האהבות רעות שיהיו בבחינת זכר, ר\"ל שתלמוד אהבת רוחני מאהבת וחשקת הגשמיים. נמצא כי זה משפיע בזה, ר\"ל אהבת רעות משפיע ברוחניות.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לב, א.</b>\n<i>זכרתי לך חסד נעוריך</i> – ירמיה ב, ב.\n----- הערות וציונים -----\n<i>שתלמוד אהבה רוחני מאהבת וחשקת הגשמיים</i> – ראה סי' רו, רנה ד\"ה וידוע, שיז, שלו ותסה-א. ובענין העלאת חשקת הגשמיים עיין כש\"ט סי' סג וסד. וראה לקמן סי' תא ד\"ה אמנם, וריש סי' תטז."]]],[400080419,"שנז\n\n<b>ורב</b> חסד. מכח גודל האהבה נתגדל הצמצום. לכן כתוב בכתבי האר\"י זלה\"ה ששם הוא גבורה, כי הצמצום הוא גבורה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לב, ב. כתבי קודש כא, ד.</b>\n<i>ורב חסד</i> – כי תשא לד, ו.<i> כתוב בכתבי האר\"י זלה\"ה כו'</i> – ע\"ח שי\"ח פ\"ה. מבו\"ש ש\"א ח\"א פ\"א.\n----- הערות וציונים -----\nראה סי' א ובהערות שם, ולקמן סי' שנח."]]],[400080420,"שנח\n\n<b>כי</b> שמש ומגן ה' אלהים. כי מחמת גודל אהבתו יתברך לבריאת העולמות, וראה שאין העולם יכול לקבל בהירתו, אז מחמת אהבה צמצם עצמו כביכול, כדי שיוכלו לקבל בהירתו, כדאיתא בגמרא כד הוי רחימנא עזה אפותיא דספסירא שכיבנא. נמצא כי מחמת אהבה בא הצמצום, והצמצום הוא שורש של אלהי\"ם. וזהו פירוש הפסוק כמו שמש ומגן (ה' אלהים) שאין מקבלים אור השמש אלא ע\"י מסך ומגן, כך ה' אלהים, לא היו יכולים לקבל בהירות הוי\"ה אלא ע\"י אלהי\"ם.\n<b>ה'</b> אלהי\"ם הוא אהבה ויראה, אלא שאהבה מעוטף ביראה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א לו, ב. כתבי קודש כב, ג.</b>\n<i>כי שמש ומגן גו'</i> – תהלים פד, יב.<i> כד הוי רחימנא עזה כו'</i> – סנהדרין ז, א.<i> והצמצום הוא כו'</i> – ראה מבו\"ש ש\"א ח\"א פ\"א.<i> הוי\"ה אלהי\"ם הוא אהו\"י</i> – ראה זח\"ג רסז, ב. זח\"ב צו, א.\n----- הערות וציונים -----\n<i>מחמת גודל אהבתו כו'</i> – ראה סי' שנז. וראה סי' א ובהערות שם.\n<i>וזהו פירוש הפסוק כי שמש כו'</i> – ראה סי' י ד\"ה כי, ובהערות שם."]]],[400080421,"שנט\n\n<b>דדיה</b> ירווך בכל עת. כי עשה לה דדים במקום בינה, פירוש כי מבינה התחלקות המדות, והם ז' ימי הבנין. ויש י\"ד עתים טובים וי\"ד עתים רעים, וכשהוא רוצה להמתיק עתים הרעים יביא הכל אל הבינה ושם נמתק, כי שם יתפרדו כל פועלי און. וזהו פרוש דדיה ירווך בכל עת, כי בבינה הוא אחדות.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א מ, א.</b>\n<i>דדיה ירוך בכל עת</i> – משלי ה, יט.<i> עשה לה דדים כו'</i> – ברכות י, א.<i> מבינה התחלקות המדות כו'</i> – ראה זח\"ב קסה, א.<i> ויש י\"ד עתים טובים כו'</i> – קהלת ג, ב-ח. תקו\"ז תס\"ט קא, ד.<i> יתפרדו כל פועלי און</i> – תהלים צב, י.\n----- הערות וציונים -----\nראה סי' שפז-ג.\n<i>אל הבינה ושם נמתק</i> – ראה סי' קצח."]]],[400080422,"שס\n\n<b>כה</b> אמר ה' ליעקב אשר פדה את אברהם וגו'. כי רחמנות פודה את האהבה כנזכר. וא\"ת לרבות שגם את יצחק פודה. וז\"ש בתיקונים כולהו אסיין אתי לגבי האי חולה עד דייתי רעיא מהימנא וייתי לה תפוח וארחת בה ואתסיאת. פי' על דרך כי תפוח ג' גוונין אית ליה, לבן אודם וירוק, רמז לג' מדות אהבה ויראה ורחמנות, ורעיא מהימנא נקרא השכל. כי מה שאנו אוהבים אותו יתברך מפני שאנו מאמינים בו יתברך, והאמונה הוא מכח השכל, שאנו מבינים שיש מנהיג ומנהיג את העולם. לכך נקרא השכל רעיא מהימנא, שזן את האמונה. וכשבא השכל בא מכחו אהבה ויראה ורחמנות ואתסיאת כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א מ, ב. לקו\"א לא, א.</b>\n<i>כה אמר ה' ליעקב גו'</i> – ישעיה כט, כב.<i> רחמנות כו' כנזכר</i> – לעיל סי' קצג. וכן לעיל סי' ב ונז.<i> וא\"ת לרבות</i> – ירושלמי ברכות פ\"ט ה\"ה.<i> וז\"ש בתיקונים כולהו כו'</i> – תכ\"ה ע, ב.<i> תפוח ג' גוונין אית ליה</i> – זח\"ג קלג, ב. שם רפו סע\"ב.<i> לבן אודם וירוק רמז לג' מדות כו'</i> – ראה זו\"ח יתרו לא סע\"ג.<i> ורעיא מהימנא נקרא השכל</i> – ראה זח\"ב רכא, א. זח\"ב קיד, ב. זח\"ג פב, א. שער הפסוקים פ' שמות ד\"ה ויקם. ראה ע\"ח, שער הכללים פי\"א. שם של\"ב ה\"א.\n----- הערות וציונים -----\nכבר הובא לעיל סי' קצג עיי\"ש."]]],[400080423,"שסא\n\n<b>עוז</b> בידך וגבורה בימינך, ופירושו יראה. כן כשאדם בעצמו עובד לעצמו, עובד למחשבה שלו, מה שנגמר במחשבה שלו, אבל אחרים עובדים לדיבורו של אדם.\n<b>וזהו</b> פירוש ויתן עוז למלכו וירם קרן משיחו. דאיתא רמה קרני ולא רמה פכי. פי' כי שמואל משח ב' מלכים, שאול ודוד, אך שאול לא נמשך מלכותו לפי ששאול נחבא אל הכלים ואין לו התגלות בזה העולם, כי הוא גבוה משכמו ולמעלה <span data-k=\"sm\">[גבוה מכל העם]</span>. והיינו נחבא אל הכלים, אל הדיבור שהוא התגלות, והוא למעלה מן הדיבור. ועל כן חמל על אגג אף שמן הדין להכריתו, אבל זה הוא לפי זה העולם. אבל רחמניות שאול הוא למעלה מזה העולם, אך אגג לא היה ראוי לזה כי הוא מעלמא דפרודא. ואיתא בגמרא דשביה קשה מכולם, ולכן הותר לעמון ומואב לבוא בקהל כי כבר עלה סנחריב ובלבל וכו'. והענין הוא כן, במה שיש בהירות יותר צריך להיות יותר באתכסיא, כמו ויתרון האור מן החושך, פי' מה שיש יתרון לאור הוא מן החושך. וזהו נקרא חסדים גדולים. ואפילו מי שהוא רע יכול להיות לו שם עליה, וזהו נקרא יום הכפורים.\n<b>ונחזור</b> לענין ראשון. שמואל משח לשאול לא נמשך מלכותו כי אין לו התגלות בעולם הזה כמבואר, ואינו מלך רק לעצמו. לכך כתיב ויתן עוז למלכו. ועל דוד, שנמשך מלכותו שהוא מעולם הדיבור שיש לו התגלות בעוה\"ז, כתיב וירם קרן משיחו. וזהו עוז בידך וגבורה בימינך, פירוש כי בדיבור הוא גבורה מה שמחתך האותיות, ודו\"ק.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א מה, א. כתבי קודש ז, א.</b>\n<i>עוז בידך וגבורה בימינך</i> – עמידה דימים נוראים.<i> ויתן עוז למלכו גו'</i> – ש\"א ב, י.<i> רמה קרני</i> – ש\"א ב, א.<i> רמה קרני ולא רמה פכי</i> – מגילה יד, א.<i> שמואל משח כו'</i> – ש\"א י, א. שם טז, יג.<i> שאול לא נמשך מלכותו</i> – מגילה יד, א.<i> ששאול נחבא אל הכלים</i> – ש\"א י, כב.<i> הוא גבוה משכמו ולמעלה</i> – ש\"א ט, ב. (שם י, כג).<i> חמל על אגג כו'</i> – ש\"א טו, ט.<i> אגג . . מעלמא דפרודא</i> – ראה תקו\"ז תס\"ט קח, ב. וראה זח\"ג קי, א. שם קנט רע\"ב. והג' החיד\"א שם.<i> דשביה קשה מכולם</i> – ב\"ב ח, ב.<i> הותר לעמון ומואב כו'</i> – ידים פ\"ד מ\"ד.<i> ויתרון האור מן החושך</i> – קהלת ב, יג.<i> וזהו נקרא יום הכפורים</i> – ראה זח\"ג ק, ב. שם קא סע\"א.<i> דוד . . מעולם הדיבור</i> – מלכות (זח\"א קמה סע\"א. זח\"ג רכח, א). זו\"ח וישב כט סע\"ג.\n----- הערות וציונים -----\n<i>אחרים עובדים לדיבורו של אדם</i> – ראה סי' קעט-ב ד\"ה ונחזור אל הענין, וריש סי' תכד, ובהערות שם.\n<i>שאול ודוד כו'</i> – ראה לקו\"ת להאריז\"ל ש\"א סי' טז. ספר הליקוטים פ' וישלח סי' לו ד\"ה והמלך הו', ושם ש\"א סי' יט. וראה ע\"ח ש\"ח ספ\"ד.\n<i>וזהו נקרא יום הכפורים</i> – ראה סי' שלב ד\"ה וזה שאמרנו, וסי' שצ."]]],[400080424,"שסב\n\n<b>פירוש</b> הפסוק האלהים בשמים ואתה על הארץ על כן יהיו דבריך מעטים. פירוש, כי נודע כי ד' עולמות הם שורש (המעשה) [המחשבה], והמחשבה, והקול, ודיבור. ונודע כי הוא יתברך ממלא עלמין, מלגאו כל עלמין, ומסבב כל עלמין, ולית אתר פנוי מיניה. ונמצא כי כשאדם מאמין בזה יכול לדבר כל הדיבורים, אפילו אינם דברי תורה, כי ידוע שהדיבורים הם מעולם הדיבור. אבל אדם שאין שם לבו על זה, רק שחושב שהשי\"ת הוא למעלה בשמים והוא על הארץ, אינו רשאי לדבר דיבורים הרבה, כי אינו יכול לתקן הדיבורים. ועל דרך שאמרו רז\"ל עם הארץ אסור לאכול בשר. וזהו פירוש הפסוק כי האלקי\"ם בשמים, פירוש כשאתה חושב כך, יהיו דבריך מעטים כנזכר.\n<b>(</b>[ftnref_1_מ]<b>שם</b> ס\"ג בהיפוך ג\"ס, ששם זה בגדלות).",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קצא (רא).</b><i> שם ס\"ג כו':</i><b> לקו\"י ג, ד (סי' פ).</b>\n<i>אלקים בשמים ואתה גו'</i> – קהלת ה, א.<i> ד' עולמות הם שורש כו'</i> – ראה זח\"ב רסב, ב. ע\"ח שמ\"ז פ\"ב.<i> ממלא עלמין כו'</i> – זח\"ג רכה, א.<i> ולית אתר פנוי מיניה</i> – תקו\"ז תנ\"ז צא סע\"א. שם ת\"ע קכב, ב.<i> עם הארץ אסור כו'</i> – פסחים מט, ב.\n----- שולי הגליון -----\n[ftn_1_מ]) <i>המובא בסוגריים אינו במדל\"י, אלא בלקו\"י, ואין לו שייכות לכאן אלא הוא ענין בפ\"ע. ומסתמא מפני זה הושם בסוגריים</i>.\n----- הערות וציונים -----\nהובא ביושר דברי אמת פי\"ט, ועיי\"ש מש\"כ בזה.\n<i>יכול לדבר כל הדיבורים כו'</i> – ראה סי' תיא וסי' תל.\n<i>שחושב שהשי\"ת הוא למעלה כו'</i> – ראה סי' רטו ובהערות שם.\n<i>כשאדם מאמין בזה יכול לדבר כו'</i> – להעיר מסוכה כא, ב שיחת חולין כו'. ראה סי' צז סד\"ה וז\"ש כי, וסי' שיז.\n<i>ועל דרך . . עם הארץ אסור לאכול בשר</i> – ראה פרדס רמונים שכ\"ד שלהי פ\"י. ספר הליקוטים ר\"פ בראשית ד\"ה ויש עליה אחרת.\n<i>שם ס\"ג בהיפוך ג\"ס כו'</i> – להעיר מזח\"ג רמו, ב. מגלה עמוקות אופן ריג. וראה מש\"כ בכתבי קודש לד, ג ד\"ה וירא משה, בענין בס\"ג הוא ג\"ס."]]],[400080425,"שסג\n\n<b>רמז</b> הפסוק וסוכה תהיה לצל יומם מחורב וגו' מזרם וממטר. נראה לפרש על פי מ\"ש בגמרא תניא אמר רבי יהושע בן חנניא כשהיינו שמחים בשמחת בית השואבה לא ראינו שינה בעינינו וכו'. הנה יש לדקדק על הלשון לא ראינו וכו', וכי הישן רואה השינה בעיניו, אדרבא הישן אינו רואה. ועוד, אומרו כשהיינו שמחים לא ראינו וכו', פשיטא בשעה שהיו שמחים לא היו רואים והוה ליה למימר בימי שמחת בית השואבה <span data-k=\"sm\">[לא היינו רואים שינה]</span>.\n<b>ויש</b> לתרץ על פי הירושלמי שאמרו למה נקראת בית השואבה שהיו שואבים משם רוח הקודש, ר\"ל מתוך שמחה של מצוה והדביקות שהיה להם זכו לרוח הקודש. והנה צריך לתת טעם לזה. הגם שנאמר <span data-k=\"sm\">[והיה]</span> כנגן המנגן וגו', גם זה צריך להבין למה הוא כך. וי\"ל למשל השמחה באה לאדם מחמת שהיה לו איזה תענוג גדול, או <span data-k=\"sm\">[שנתבשר]</span> בשורה טובה, <span data-k=\"sm\">[והיה לו תענוג גדול מזה]</span>, או שראה איזה דבר שיש לו תענוג גדול מהדבר ההוא באה לו השמחה. נמצא מצינו שהשמחה נמשכת מעולם התענוג שהוא רוחני בלתי מושג, והוא עליון עד מאד הנקרא קד\"ש בלא ו'. ומשם נמשך למדריגת (קו\"דש) [קדוש] שהוא התפשטות הקדש בו', ומשם יורד ממדריגה למדריגה עד שבא אל האדם רוח הקודש.\n<b>והנה</b> אמרו רז\"ל על פסוק מה יש לך בבית וגו', שאין השראת שכינה וברכה שורה אלא על איזה דבר שיהיה כלי המקבל השפעה ההוא. ואמרו רז\"ל רצה הקב\"ה לזכות את ישראל <span data-k=\"sm\">[לפיכך]</span> הרבה להם וכו', ר\"ל כי המצות בעצם המה תרי\"ג, אבל כאשר יקיים האדם בכל דרכיך דעהו יוכל לקיים הרבה והרבה פעמים תרי\"ג עד אין קץ, כי כל מעשיו הם לשם שמים. נמצא שהוא מקיים בכל עת ובכל רגע מצות בוראו <span data-k=\"sm\">[ית' שמו]</span>, כמו שאמרו על הלל הזקן על אכילתו היה אומר אגמול חסד עם אכסניא וכו'. וז\"ש לפיכך הרבה להם תורה ומצות, כי בדבר שאין לו קצבה נופל בו לשון ריבוי. משא\"כ אם לא היו כי אם תרי\"ג מה שייך לומר לשון הרבה, וכי בשביל שהם תרי\"ג קורא אותם מרובים. אבל לפי הנזכר אתי שפיר, כי המקיים בכל דרכיך דעהו אין קץ למצותיו כנזכר. ומ\"ש לזכות את ישראל, ר\"ל בעשייתם לשם שמים (הם) מזדככים החומרים שלהם, ויהיו יכולים להתדבק ולהתחבר בקדושה, כי מצו\"ה הוא לשון צוו\"תא והתחברות. ואפשר לומר שלזה רמזו <span data-k=\"sm\">[ואמרו]</span> מצוה גוררת מצוה, פירוש בעשותו המצוה <span data-k=\"sm\">[גוררת ו]</span>גורמת התחברות והתדבקות כנזכר. ועבירה גוררת עבירה, כי עבירה הוא לשון פירוד מבוראו ח\"ו.\n<b>ונחזור</b> אל הענין שבלתי יכולת להמשיך ההשפעה מלמעלה אם לא על ידי כלי המקבל, וצריך לידע הטעם למה הוא כך. מפני שהקדושה העליונה בהירה ומאירה מאוד ואי אפשר לסובלה, ועל ידי עשיית המצוה, שהיא כלי המקבל, מתלבשות בתוכה האור העליון, ויוכל האדם לסובלו ולקבלו, כדמיון אור השמש ששמו הבורא יתברך בתוך נרתיקו בכדי שיוכלו ברואי עולם לסבול אותו.\n<b>ואפשר</b> לומר שזהו רמז הפסוק וסוכה תהיה לצל יומם. אם הוא מדבר (בקימו המצות) [במקיימי מצות] הסוכה אז הוא כפשוטו, וסוכה, ר\"ל מצות סוכה, תהיה להם למגן ולצל המציל מפני האור העליון שיוכלו לקבלו כנזכר, שיהיה להם המצוה הזאת כנרתיק וצל בכדי שיוכלו לסבול האור. וזהו שכתוב יומ\"ם, כידוע שהחסד המתפשט ומשפיע נקרא יומ\"ם, כמו יומם יצוה ה' חסדו, ויהיה להם הסוכה לצל ולקבל בתוכו ההשפעה.\n<b>ואם</b> הוא מדבר באותן השמחים בשמחת בית השואבה, פירוש הפסוק כך הוא. וסו\"כה, פירוש רוח הקודש הנקרא סכיי\"ה, תהיה להם, מחמת שעשו תחילה הצל ונרתיק להשתלשל בתוכו קודש העליון, שהוא עולם התענוג, מתוך השמחה של מצוה, שהוא קדש המתפשט בו' כנזכר, אשר משם שואבים רוח הקודש מעילא לתתא על ידי ו' המתארך, שהוא חסד המתפשט עם כולם, יומא דכלהו. וזהו שסיים <span data-k=\"sm\">[מחורב]</span> ולמחסה ולמסתור (מחורב) מזרם וממטר, <span data-k=\"sm\">[ר\"ל]</span> שהוא כלול מכל הו' קצוות שהם כלולים מחסד וגבורה, שהם אש ומים, לשון חורב ומטר, כי כן גם הצל אשר עשו, שהוא השמחה של מצוה, היתה גם כן כלולה מאהבה ויראה הנקראים חסד וגבורה. על כן תהיה להם למחסה גם כן מחורב מזרם וממטר.\n<b>כי</b> הנה ידוע שיש ב' מיני יצר הרע המחטיא את האדם חס ושלום. א' המבטלו מלקיים מצות עשה, וא' <span data-k=\"sm\">[המסיתו]</span> לעבור על מצות ל\"ת. והנה היצר הרע המבטלו ממצות עשה הוא דמיון המים אשר טבעם קר ולח, כך הוא נותן באדם קרירות וחלישות וכבדות הגוף ועצלות כדי שיהיה נמנע מלקיים מצות בוראו. ויצר הרע הב' הוא המחמם ומלהב את האדם, ר\"ל דמיון האש, לעבור על לא תעשה. וזה שאמר כי בעשותו כל אלה, דהיינו שיעשה המצוה בשלימות, בדחילו ורחימו שהם חסד וגבורה, ויגרמו בזה להמשיך החסד העליון שהוא יומ\"ם, כלול מחסד וגבורה שהם כל הו' קצוות כנזכר, וישאבו רוח הקודש שהיא הסוכ\"ה, תהיה להם למחסה ולמסתור מב' מיני היצר הרע הנקראים חורב ומטר שהם אש ומים כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רנט (רסז).</b>\n<i>וסוכה תהיה לצל גו'</i> – ישעיה ד, ו.<i> בגמרא תניא אמר כו'</i> – סוכה נג, א.<i> למה נקראת בית השואבה כו'</i> – ירושלמי סוכה פ\"ה ה\"א.<i> כנגן המנגן גו'</i> – מ\"ב ג, טו. ראה ירושלמי שם. שבת ל, ב.<i> קד\"ש בלא ו'</i> – ראה זח\"ב קכא סע\"א.<i> ומשם יורד כו' רוה\"ק</i> – ראה זח\"ג סא רע\"א. שם רצז, א.<i> מה יש לך בבית גו'</i> – מ\"ב ד, ב.<i> שאין כו' אלא על איזה דבר כו'</i> – זח\"א פח, א. זח\"ב פז, ב. זח\"ג לד, א.<i> רצה הקב\"ה לזכות כו'</i> – מכות כג, ב.<i> בכל דרכיך דעהו</i> – משלי ג, ו. ראה ברכות סג, ב.<i> כל מעשיו הם לשם שמים</i> – ע\"פ אבות פ\"ב מי\"ב.<i> שאמרו על הלל הזקן כו'</i> – ויק\"ר לד, ג.<i> מצו\"ה הוא לשון צוו\"תא</i> – של\"ה בעשרה מאמרות מאמר ג-ד (נא, ב). שם מס' יומא פרק ד\"ח תוכחת מוסר (רלז, ב). אוה\"ח תצוה כז, כ ושם פנחס כז, כג.<i> מצוה גוררת מצוה</i> – אבות פ\"ד מ\"ב.<i> ועבירה גוררת עבירה</i> – שם.<i> שהחסד המתפשט כו' יומ\"ם</i> – זח\"ג (ר\"מ) קכא, ב. שם קצא, ב.<i> יומם יצוה ה' חסדו</i> – תהלים מב, ט.<i> רוה\"ק הנקרא סכי\"ה</i> – מגילה יד, א.<i> חסד המתפשט עם כולם</i> – זח\"ג קג רע\"ב. שם קצא, ב. ראה זח\"א מו, א. ע\"ח שכ\"ה דרוש ב' כלל ז.<i> מחורב ולמחסה ולמסתור גו'</i> – ישעיה ד, ו.<i> מחו\"ג שהם אש ומים</i> – זח\"ג רנה סע\"א.<i> מאהבה ויראה הנקראים חו\"ג</i> – ראה תקו\"ז ת\"י כה, ב.\n----- הערות וציונים -----\n<i>שהשמחה נמשכת מעולם התענוג כו'</i> – ראה סי' רג ד\"ה ונחזור.\n<i>קד\"ש בלא ו' כו'</i> – ראה סוף סי' תלח.\n<i>ומ\"ש לזכות את ישראל כו'</i> – ראה שמועה טובה סח סע\"ב.\n<i>מצוה הוא לשון צוותא והתחברות</i> – ראה סי' קג וסי' תז.\n<i>עבירה הוא לשון פירוד</i> – ראה סי' מד סד\"ה ובמקום. סי' תנו ד\"ה וכן.\n<i>כל מעשיו הם לש\"ש כו' כמו שאמרו על הלל כו'</i> – ראה סי' תנו ד\"ה ואפשר.\n<i>ב' מיני יצר הרע כו'</i> – ראה ריש סי' מד."]]],[400080426,"שסד\n\n<b>רמז</b> הפסוק טוב שם (טוב) משמן טוב. ויש לומר על דרך הלצה, כי מלת ש\"ם מורה בתרי גווני. יש שם לשבח, כמו ויצא שם דוד, ויש שם לגנאי, כמו אנשי השם, כי מי שהוא נצחן או בעל מחלוקת יש לו שם שהוא נצחן או בעל מחלוקת. וידוע כי שמן טבעו צח ונחת והשקט, וגם הוא גורם נחת והשקט, כדמיון אדם שיכור שרפואתו לסוך אותו בשמן להשקיטו משכרותו. וז\"ש טוב שם (טוב), ר\"ל איזה שם הוא טוב ושבח לאדם, כשהוא נמשך משמן, ר\"ל שהוא איש נח ושקט כמו שמן כנזכר, אבל לא טוב השם מחמת שהוא נצחן ובעל מחלוקת. ואמר טו\"ב פעם ב', משמן טו\"ב, להורות שמלת טו\"ב גם כן הוא נמשך משמן. כי שמ\"ן בא\"ת ב\"ש בי\"ט, והתארכות הי' הוא ו', ונעשה אותיות טו\"ב.",[["","","----- מקורות ומראה מקומות -----\n<i>טוב שם משמן טוב</i> – קהלת ז, א.<i> ויצא שם דוד</i> – דה\"א יד, יז.<i> אנשי השם</i> – בראשית ו, ד.<i> שמן טבעו נח כו'</i> – ראה סנהדרין כד, א ורש\"י שם ד\"ה משמנין. ירושלמי נדה פ\"ג ה\"ג. זח\"ג לט, א.\n----- הערות וציונים -----\n<i>שמ\"ן בא\"ת ב\"ש בי\"ט . . טוב</i> – ראה לקו\"ת להאריז\"ל פ' עקב סד\"ה ארץ זית שמן ודבש.\n<i>והתארכות הי' הוא ו'</i> – ראה סי' קיד סד\"ה ונחזור. סי' רסב רד\"ה ונחזור."]]],[400080427,"שסה\n\n<b>או</b> י\"ל על פי מ\"ש רז\"ל לא כמו שאני נכתב אני נקרא, נכתב <span data-k=\"sm\">[אני]</span> בהוי\"ה ונקרא <span data-k=\"sm\">[אני]</span> באדנ\"י. ויש לתת טעם לזה למה נקרא באדנות. ויש לומר, כי הנה ידוע כי שם אדנ\"י הוא מדת המלכות, ואין מלך בלא עם ואין אדון בלא עבדים. נמצא כי שם אדנ\"י הוא נקרא מחמת שאנחנו עמו ועבדיו. והואיל שנקרא שם אדנ\"י מצידנו, לכן הורשה לנו לקרוא שם אדנ\"י, וכמו כן שאר כינוים מטעם הנזכר. אבל שם הוי\"ה הוא שם העצם המהוה כל הויות, אשר קודם בריאת העולם היה הוא ושמו אחד מיוחד בכתר, לכן אינו נקרא ככתיבתו.\n<b>והנה</b> נקדים לזה מ\"ש במדרש על פסוק ביום השמיני עצרת תהיה לכם, משל למלך שעשה סעודה לכל בני המדינה ז' ימים, והיה לו בת יחידה וחביבה ואמרה אל המלך לכולם עשית סעודה ונהנו ממך וכו', אמר לה המלך חייך וכו', ואמר <span data-k=\"sm\">[המלך]</span> לעבדיו עשו לי ולבתי סעודה קטנה וכו'. גם אמרו במדרש, טוב מלא כף נחת <span data-k=\"sm\">[ממלא חפנים עמל, כף נחת]</span> זה שמיני עצרת, ממלא חפנים עמל אלו ז' ימי החג. והנה יש לתמוה למה קורא אותן מלא חפנים עמל, והלוא ימים קדושים הם הניתנים לישראל לשמוח בהם, כמו שאנו אומרים זמן שמחתינו. וגם יש לדקדק למה אמר עשו סעודה קטנה, וכי כלום חסר מבית המלך, מכל שכן אם היה עושה בשביל בתו האהובה סעודה גדולה היתה נהנית יותר ויותר.\n<b>והנה</b> כפי פשוטו הוא כידוע מאמרם זלה\"ה על פסוק הן עם לבדד ישכון ובגוים לא יתחשב, כשהאומות שמחים ישראל שמחים עמהם ואינו מתחשב להם, וכשישראל שמחים הם לבדם שמחים. כי הנה ידוע שכל עניני <span data-k=\"sm\">[מצות</span>] החג, כמו ע' פרים ונסוך המים, הם מרומזים נגד ע' אומות, כמ\"ש בזוהר על פסוק מים רבים לא יוכלו לכבות את האהבה, שלא יקטרגו ויפרידו הדביקות והאהבה שבין ישראל לאביהם שבשמים, לכך ישראל עושים מצות חג הקדוש ומשפיעים לע' אומות כנזכר. והנה הגם שישראל משפיעים לאומות העולם, מכל מקום השמחה גדולה היא לישראל, שכל האומות הם נכנעים וכפופים להשפעתם, וכל הע' שרים שותים מתמצית ארץ ישראל, וממילא באה מתחילה לישראל השפעה גדולה עד אין קץ, שהם נעשים צינור לכל העולם. ולכן נקרא זמן שמחתינו, הגם שמצוה לשמוח בכל הרגלים, אך עתה השמחה יתירה ומכופלת, א' בשביל ההשפעה גדולה הבאה להם, ועוד שכל האומות נכנעים תחת ידם וכפופים להם. אך עם כל זה, מפני שהוצרכה לכל אלה כדי לסתום פי המקטריגים, נקרא בערכם מלא חפנים עמל, מפני שעדיין לא נתקיים בהם הברכה הן עם לבדד ישכון ובגוים לא יתחשב. ובבוא החג הקדוש הזה שמיני עצרת הם שמחים לבדם, ואז השמחה היא שלמה בתכלית השלימות. ומה שהמשיל שמחתה לסעודה קטנה, לא מפני שהסעודה, שהיא ההשפעה והמזון העליון, קטנה היא משל החג, אלא אדרבא, השפעתה גדולה וגדולה יותר מכל הז' ימים. אלא נקראת קטנה בערך ישראל המקבלים, שהם דמיון הבת האהובה, כלומר ישראל נקראים קטנים כמו שכתוב כי קטן יעקב, ונאמר כי נער ישראל ואוהבהו.\n<b>ונמשיל</b> משל מי שהוא בתכלית השפלות והקטנות, והנה בפתע פתאום מינהו המלך לשררה גדולה ורמה, וישא את כסאו מעל כל השרים. והנה לאיש כזה השמחה והתענוג רבה היא עליו מאוד מאוד עד אין קץ לשמחתו, ממש מאשפות הרימו וגדלו על כל השרים. ולא כן אם היה המלך מגדל ומרומם אחד מן השרים על כולם, לא היה לו השמחה גדולה כל כך מפני שהוא כבר הורגל בגדלות. והנמשל מובן מאיליו. שכן אמר הקב\"ה, עשו סעודה, ר\"ל השפעה רבה וגדולה, שיהיו (לפני) [לבני] שמחה ותענוג גדול כמו התענוג <span data-k=\"sm\">[נ\"א: השמחה]</span> הבאה לקטן ושפל הערך בבואו לגדולה פתאומית כנזכר, וזהו כדי שאהנה <span data-k=\"sm\">[נ\"א: שאהיה]</span> אני ובתי וכו', כי לה' הישועה אם על עמך ברכתך סלה. ומה גם כשישראל בעצמם הם קטנים, שמקטינים את עצמן, וכתיב כמים פנים אל פנים. אם כן גם הקב\"ה כביכול מצמצם שכינתו והשפעתו בתוכם, ויכולים לקבל כל ההשפעה הרב והעצום. משא\"כ מי שהוא <span data-k=\"sm\">[בגבהות ו]</span>בגדלות אינו נהנה מקדושה עליונה, כנזכר בדרושים הקודמים.\n<b>ונחזור</b> אל הענין שכל <span data-k=\"sm\">[עניני]</span> מצות החג הוא כדי להשפיע לע' שרים. וגם הז' הקפות של ימי החג, שהוא הקפה בלולב ומיניו, הוא גם כן רמז אל האומות העולם. הגם שד' מינים אלו מרומזים אל ד' אותיות הוי\"ה, עם כל זה הם אינם רק הארות משם, וענפים מהאילן גופא, כי שורשם הם צמחים שהם תחת המזלות, כמ\"ש רז\"ל אין לך כל עשב ועשב שאין לו מזל ברקיע המכה אותו ואומר לו גדל. וידוע שהכוכבים ומזלות הם תחת ע' שרים, והם נקראים ג\"כ ענפי אילן כידוע מספר הזוהר. נמצא כי כל הקפות החג הוא לתועלת הע' שרים, כי הם שורשם, ולכן הם גדלים וצומחין על ידי המזלות וכוכבים. ומה שאמרו המכה אותו ואומר לו גדל, פי' כי הנה ידוע כי כל דבר <span data-k=\"sm\">[ודבר]</span> התחתון יש לו חשק ותאוה לעלות ולהתדבק בשורשו העליון. והנה בהראות הכוכב או המזל באיזה שעות ידועים לתועלת הצומח, ובהראותו אל הצומח, רוצה הצומח וחושק להתדבק בו לעלות לשורשו, ובזה הוא גדל והולך, והרי הוא כמכה אותו ואומר לו גדל.\n<b>אבל</b> בשמיני עצרת, שההקפות הם בשביל תועלת ישראל, שהם אחוזים ומשורשים בגוף האילן, שהם שמות הוי\"ה בעצמם <span data-k=\"sm\">[נ\"א: בעצם]</span>, לכן ההקפות של שמיני עצרת הם בספר תורה עצמה, שהיא כולה שמהא דקב\"ה. אך מחמת ששמות ההויו\"ת נקראים באדנו\"ת, לכך נקרא החג עצרת שהוא לשון מלכות, שהוא שם אדנ\"י. וזהו שסיים ביום השמיני עצרת תהיה לכ\"ם, לכ\"ם דייקא ולא לאומות העולם, שאין להם אחיזה בזה החג כלל ועיקר.\n<b>ומה</b> שנקרא זה החג שמינ\"י, ואמרו רז\"ל שמיני רגל בפני עצמו, וא\"כ למה נקרא שמינ\"י כאלו הוא נמנה עם ימי החג והוא שמיני להם, והלוא הוא בפני עצמו ויותר עליון מהם. ויש לתרץ ע\"פ מ\"ש בזהר על פסוק כולם בחכמה עשית, כולם במחשבה אתברירו. וכדי לקרב זה אל השכל, נמשיל משל <span data-k=\"sm\">[נאה]</span> למלך שעלה ברצונו לבנות לו בית. הנה בתחילה היה הרצון סתום מאוד בלי שום דבר פרטי, ואח\"כ, כאשר בא הרצון אל המחשבה, נתגלה הרצון בכללות איך יהיה מדת ארכו ורחבו ומספר חדריו ופתחיו וחלונותיו בתכלית השלימות. והנה הגם שיש בזה פרטות, רק מפני שהוא רק במחשבה נקרא כללות, וזהו כלל הראשון. ואח\"כ כאשר התחיל להכין צרכי הבנין, כמו עצים ואבנים וסיד ובעל מלאכה, זה נקרא פרטים. אבל עם כל זה, בכל פרט ופרט יש גם כן <span data-k=\"sm\">[כלל קטן. למשל, כאשר התחיל להכין עצים לצורך הבית עדיין לא היה הפרט שלם. וכאשר הכין די סיפוקו נשלם הפרט. וזהו]</span> כלל קטן שבפרט. ודמיון לזה אמרו כל אחד כלול מי', <span data-k=\"sm\">[כי]</span> הגם שהוא ספירות פרטיות עם כל זה יש בה כללות. וכאשר גמר כל הפרטות ובנה הבית <span data-k=\"sm\">[וגמרו]</span>, זהו נקרא כללא בתראה. וזה הכלל האחרון הוא העיקר, כי הוא המלמד ומורה ומגלה סתומות הכלל הראשון, וגם כל הפרטיות בו בהתגלות. וזהו כלל ופרט וכלל.\n<b>והנה</b> בתחילה עלה ברצונו יתברך, ואח\"כ במחשבה אתברירו בכלל, ואח\"כ על ידי הו' קצוות, ו' ימי הבנין, נעשה הכל בפרטיות, ובשביעית נכללה ונתגלה כל הכלל של המחשבה קדומה וכל הפרטיות כנודע. ולכן הז' הוא קודש, שבו נתגלה עולם התענוג. ונמצא כי בוודאי שעולם התענוג בעצמו שם יש יותר תענוג ושמחה, שבו כללות הרצון העליון, והוא הוא השמיני, מפני שהוא עליון אל השבעה <span data-k=\"sm\">[כנ\"ל]</span>. ([ftnref_1_מא]ואפשר לומר, שידוע כי החכמה נקרא שמ\"ן, ואפשר כי לכך נקרא שמינ\"י שהוא מלשון שמ\"ן, והיו\"ד יתירה מורה על החכמה הנקרא יו\"ד). ולכן נקרא שמיני עצרת, כי עצרת, שהיא מדת המלכות, היא מעולם החכמה ממש, שהוא השמיני כנזכר. והנה ידוע שהמלכות נקראת ש\"ם. וזהו טוב ש\"ם, <span data-k=\"sm\">[ר\"ל מלכות]</span>, משמ\"ן, <span data-k=\"sm\">[ר\"ל]</span> כאשר אבא יסד ברתא, שהוא עולם הטוב והתענוג העליון, אז טוב השם כנזכר.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רס (רסח).</b>\n<i>לא כמו שאני נכתב אני נקרא כו'</i> – פסחים נ, א.<i> שם אד' הוא מדת המלכות</i> – זח\"ג יא רע\"א. תקו\"ז ת\"ע קכג סע\"א.<i> ואין מלך בלא עם</i> – רבנו בחיי וישב לח, ל. ראה פדר\"א פ\"ג. זח\"ג רעא, ב. תקו\"ז תכ\"א ס רע\"ב.<i> שם הוי\"ה הוא שם העצם</i> – מו\"נ ח\"א פס\"א. של\"ה תול\"א בית ה'.<i> קודם בריאת העולם היה כו'</i> – פדר\"א פ\"ג (וש\"נ בביאור הרד\"ל).<i> מ\"ש במדרש על כו'</i> – ראה במ\"ר כא, כד. סוכה נה, ב. זח\"א סד סע\"א. זח\"ג כד סע\"א. שם קד, ב ושם רנו רע\"ב.<i> ביום השמיני עצרת גו'</i> – פנחס כט, לה.<i> טוב מלא כף נחת גו'</i> – קהלת ד, ו.<i> הן עם לבדד ישכון גו'</i> – בלק כג, ט.<i> כשהאומות שמחים כו'</i> – תנחומא בלק יב. במ\"ר כ, יט.<i> כמ\"ש בזוהר על כו'</i> – זח\"ג רנו, א. שם רנט, א. ראה זח\"ב קפו סע\"ב. זח\"א סד, א. סוכה נה, ב.<i> מים רבים גו'</i> – שה\"ש ח, ז.<i> שלא יקטרגו כו'</i> – זח\"ב קפז רע\"א. זח\"א סד, א.<i> וכל הע' שרים שותים כו'</i> – זח\"ב רט, ב. ראה תענית י רע\"א.<i> ובבוא חג כו' הם שמחים לבדם</i> – זח\"א סד סע\"א. זח\"ג לב, א.<i> כי קטן יעקב</i> – סליחות ליום שני קמא וליום ה' דימי הסליחות, ד\"ה אלהים בישראל גדול, אות כ, ע\"פ עמוס ז, ב וה.<i> כי נער ישראל ואוהבהו</i> – הושע יא, א.<i> לה' הישועה גו'</i> – תהלים ג, ט.<i> אם על עמך ברכתך</i> – זח\"ג צ, ב.<i> כמים הפנים גו'</i> – משלי כז, יט.<i> כנזכר בדרושים הקודמים</i> – לעיל סי' קמ ורמח.<i> שד' מינים כו' ד' אותיות הוי\"ה</i> – זח\"א סג סע\"ב. שם רכ רע\"ב. פע\"ח שער הלולב פ' א-ב.<i> אין לך כל עשב כו'</i> – בר\"ר י, ו.<i> והם נקראים ג\"כ ענפי אילן כו'</i> – זח\"ב נח סע\"ב.<i> כל דבר כו' לעלות ולהתדבק בשורשו</i> – ראה רמב\"ם הלכות יסוה\"ת פ\"ד ה\"ב. מו\"נ ח\"א פע\"ב.<i> בהראות הכוכב כו' באיזה שעות ידועים כו'</i> – ראה זח\"ב קעא, ב.<i> בשמ\"ע כו' בשביל תועלת ישראל</i> – זח\"א סד סע\"א.<i> ישראל שהם אחוזים כו'</i> – זח\"ב נח סע\"ב. שם נ, א.<i> ההקפות של שמ\"ע הם בס\"ת עצמה</i> – ראה זח\"ג רנו רע\"ב. שם צז רע\"א. ריד, ב. תקו\"ז תכ\"א נו סע\"א.<i> שהיא כולה שמהא דקב\"ה</i> – זח\"ב קכד רע\"א. שם פז סע\"א. צ' רע\"ב.<i> עצר\"ת שהוא לשון מלכות</i> – זח\"ג רנו רע\"ב.<i> מלכות שהוא שם אד'</i> – זח\"ג יא רע\"א. תקו\"ז ת\"ע קכג סע\"א.<i> לכ\"ם דייקא כו'</i> – זח\"א סד סע\"א.<i> שמיני רגל בפני עצמו</i> – סוכה מז, א.<i> כולם בחכמה עשית</i> – תהלים קד, כד.<i> כולם במחשבה אתברירו</i> – זח\"ב רנד סע\"ב. ע\"ח שי\"ח פ\"ה. שם שי\"ט פ\"ט ושל\"ט פ\"א. שעה\"מ פ' עקב.<i> כל אחד כלול מי'</i> – תקו\"ז תי\"ז לא סע\"א. תמ\"ז פד, א. שם תס\"ט קטז, ב. פרדס רמונים ש\"ח פ\"ב.<i> בתחילה עלה ברצונו ית'</i> – ע\"ח ש\"א ענף ב. שם שער הכללים רפ\"א.<i> ובשביעית נכללה ונתגלה כו'</i> – ראה זח\"ב קכז, א. תקו\"ז תס\"ט קטז, ב.<i> ולכן הז' הוא קודש</i> – ראה זח\"ג סא רע\"א. שם רצז, א.<i> החכמה נקרא שמ\"ן</i> – זח\"ג לד סע\"א. שם לט, א.<i> החכמה הנקרא יו\"ד</i> – זח\"ב קכג, ב. זח\"ג י, ב.<i> שהמלכות נקראת ש\"ם</i> – זח\"ג ערה, ב. תקו\"ז תמ\"ט פה סע\"ב.<i> טוב שם משמן טוב</i> – קהלת ז, א.<i> אבא יסד ברתא</i> – זח\"ג רנו סע\"ב. שם רנח, א.\n----- שולי הגליון -----\n[ftn_1_מא]) <i>הסוגריים גם במדל\"י</i>.\n----- הערות וציונים -----\n<i>למה נקרא באדנות כו'</i> – ראה סי' קפב וסי' שצ.\n<i>וכל הע' שרים שותים כו'</i> – ראה סי' עז ועח.\n<i>נמשיל משל נאה למלך כו'</i> – השוה סי' קנב ד\"ה וסוף.\n<i>כי לה' הישועה אם על עמך ברכתך סלה</i> – ראה לקו\"י סי' קכג בביאור אין עומדין להתפלל אלא מתוך כובד ראש \"וכשיענה בתפילתו ויהיה לה' הישועה יקויים ג\"כ סוף הפסוק על עמך ברכתיך סלה\".\n<i>וזהו כלל ופרט וכלל</i> – ראה שמועה טובה נח, א."]]],[400080428,"שסו\n\n<b>רצה</b> והחליצנו וכו'. פי' כי יש לפעמים שאנו לוקחים יראת הבורא יתברך מכח שאנו רואים שכל העולמות יראים ממנו ואוהבים אותו. נמצא כי אנו לוקחים מדתנו מהברואים. אבל בשבת קודש אנו לוקחים המדות מהבורא יתברך לבד, ואז אנו נחלצים מהברואים ודבוקים בהבורא יתברך[ftnref_1_מב].",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י לב, ב (סי' רנט). כתבי קודש לג, ג.</b>\n<i>רצה והחליצנו וכו'</i> – ברכת המזון לשבת.<i> מכח שאנו רואים שכל העולמות כו'</i> – ראה רמב\"ם הלכות יסוה\"ת פ\"ב ה\"ב. שם פ\"ד הי\"ב.\n----- שולי הגליון -----\n[ftn_1_מב]) <i>נ\"א בכתבי קודש:</i> רצה והחליצנו. כי יש גבורות שלוקחים מגבורות אנשים. אבל בשבת עובדים להשי\"ת מהיראה שלו. וזה החליצנו מהאנושיות, והבן.\n----- הערות וציונים -----\nלהעיר מסי' שעח עיי\"ש."]]],[400080429,"שסז\n\n<b>שונא</b> מתנות יחיה. פי' כי הנה הנשמות באים לעולם הזה כדי דלא ליכלו נהמא דכסופא במתנה. והנה כשאדם בעולם הזה אוהב מתנות, אז יכול הוא למות וליקח גם שם במתנה. אבל מי שהוא שונא מתנות יחיה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י לב, ב (סי' רס). כתבי קודש לג, ג.</b>\n<i>שונא מתנות יחיה</i> – משלי טו, כז.<i> נהמא דכסופא במתנה</i> – ירושלמי ערלה פ\"א ה\"ג."]]],[400080430,"שסח\n\n<b>ברבות</b> הטובה רבו אוכליה ומה (יתרון) [כשרון] לבעליו כי אם ראות עיניו. על[ftnref_1_מג] דרך משל[ftnref_2_מד] למי שראה מלחמה ובא וסיפר לאחד, וזהו שסיפרו לו באה לו המחשבה הזאת והעלה את המחשבה לשורשה, ועשה זיווג, יחוד[ftnref_3_מה], לשון אכיל\"ה. כי כל המחשבות זרות אינם במקרה, רק בכל דבר שבקדושה רוצה המחשבה להתדבק מעין כיוצא בה, כמו אהבה לאהבה, והתפארות לתפארת וכיוצא <span data-k=\"sm\">[בזה]</span>. ואם האדם מעלה אותה אז שכרו גדול, כי עת לכל חפץ, וכמ\"ש ובהגיע תור נערה ונערה, ועיין לעיל. כי זאת המחשבה נקרא נוקבא שרוצה לקבל מהקדושה[ftnref_4_מו]. נמצא כי זאת המחשבה היתה בין עמקי הקליפות, כדמיון הראשון שראה המלחמה בין הגוים, וכאשר סיפר לחבירו עשה מעשה <span data-k=\"sm\">[נ\"א: נעשה מעשיה]</span> דיבור, ואח\"כ באה לידי מחשבה. ונמצא רבו אוכליה, ר\"ל העושים יחוד זה, <span data-k=\"sm\">[כי אכילה הוא לשון זיווג]</span>, ומה יתרון לבעליו וגו'.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רלח (רנא). כתבי קודש ט, ד.</b>\n<i>ברבות הטובה רבו גו'</i> – קהלת ה, י.<i> זווג יחוד לשון אכיל\"ה</i> – ע\"ח שט\"ז ספ\"ד ע\"פ משלי ל, כ.<i> עת לכל חפץ</i> – קהלת ג, א.<i> ובהגיע תור נערה ונערה</i> – אסתר ב, יב.<i> ועיין לעיל</i> – סי' קכג.<i> נוקבא שרוצה לקבל</i> – ראה תקו\"ז תנ\"ה פט סע\"א.\n----- שולי הגליון -----\n[ftn_1_מג]) <i>במדל\"י נ\"א בשנוי הסדר (והנוסח שם מבורר יותר):</i> דהנה ידוע כי כל מה שאדם רואה או שומע אינו במקרה, רק בכל מקום יש נצוצות קדושים ואותיות קדושים וחושקים ומתאוים תמיד לשרשם וכל אחד רוצה וחושק להתדבק מעין כיוצא בו כמו אהבה לאהבה <i>(כבפנים)</i>.\n[ftn_2_מד]) <i>במדל\"י הובא המשל קרוב לסוף הדרוש (כשיצוין), ובנ\"א (דומה לנוסח המובא לעיל סי' קצו):</i> על דרך משל אחד שראה איזה מלחמה וסיפר לאדם צדיק, וצדיק זה העלה אותה במחשבתו להש\"י.\n[ftn_3_מה]) <i>נראה שצ\"ל</i> ועשה יחוד, זיווג לשון אכיל\"ה.\n[ftn_4_מו]) <i>במדל\"י בא כאן המשל הנ\"ל</i>.\n----- הערות וציונים -----\n<i>כי כל המחשבות זרות אינם במקרה כו'</i> – ראה סי' קכג ד\"ה והנה ידוע, ובהערות שם. וראה סי' קטו. וסי' תצז."]]],[400080431,"שסט\n\n<b>ערום</b> יעשה בדעת וכסיל יפרוש אולת. פי' מי שהוא חכם, אף על פי שהוא עושה צרכי עצמו הוא עושה הכל בדעת, כלומר בדביקות השי\"ת. ודע\"ת הוא לשון התקשרות ודביקות, כמו ויד\"ע אדם, וכן נאמר ד\"ע את אלקי אביך, ר\"ל התקשר והתדבק עם אלק\"י אביך בתמידות בכל מעשיך. וכסיל יפרוש <span data-k=\"sm\">[אולת]</span>, כלומר אף על פי שהוא פרוש מהעולם ולומד תמיד, רק שלומד או מתפלל בלי דביקות והתקשרות, אולת היא לו[ftnref_1_מז].",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רלז (רנ). אוה\"א מב, א. כתבי קודש ו, ג. צוה\"ר סי' צח.</b>\n<i>ערום יעשה בדעת גו'</i> – משלי יג, טז.<i> ויד\"ע אדם</i> – בראשית ד, כה.<i> ד\"ע את אלקי אביך</i> – דה\"א כח, ט.\n----- שולי הגליון -----\n[ftn_1_מז]) <i>בצוה\"ר ואוה\"א וכתבי קודש בקיצור:</i> כל ערום יעשה בדעת. פירוש, מי שהוא חכם יעשה אפילו משא ומתן שלו בדעת. וכסיל, אפילו כשהוא פרנס או ראש [<i>נ\"א:</i> פרוש מתאוות העולם, אעפ\"כ] אולת הוא.\n----- הערות וציונים -----\nבנו\"א בדמ\"א פ' קדושים ד\"ה אל תפנו: כמו שאמר הרה\"מ המנוח מו\"ה דוב בער זללה\"ה כל ערום יעשה בדעת היינו אפילו עשיות גשמיות ואפילו ערמה שעושים הכל הוא בדעת קונו, כמו אביגיל [ראה מגילה יד, ב], וכסיל יפרוש היינו אפילו עושה דבר פרישות וקדושה אולת יחשב אע\"פ שהוא דבר מצוה וחכמה כמו שנים שאכלו פסחיהם וכו' [ראה נזיר כג, א] ע\"ש.\n<i>אף על פי שעושה צרכי עצמו כו' הכל בדעת כו'</i> – ראה צוה\"ר סי' צד (ובהערות שם). להעיר מרמב\"ם הלכות דעות פ\"ג. טושו\"ע או\"ח סי' רלא."]]],[400080432,"שע\n\n<b>כי</b> ארץ הנגב נתתני ונתת לי <span data-k=\"sm\">[גו']</span> את גלות עליות ואת גלות תחתיות. כי משה היה קשור ודבוק לאי\"ן, ולכך היה יכול לצרף אחת אל אחת והיה מקים את המשכן ולא אחר. כי משה הביא אי\"ן לכאן, כי שם חלקת מחוקק ספון, <span data-k=\"sm\">[ר\"ל]</span> כי החקיקה והצרופים ספון. אך כשהענין בדחילו ורחימו נעשה מעצמו <span data-k=\"sm\">[נ\"א: אך הענין כשעושין בדחילו ורחימו אזי נעשה הדבר מעצמו]</span> על ידי שבא לאי\"ן, כמ\"ש במקום אחר. ולכך בשלמה כתיב בהבנותו, שנבנה מעצמו, ובאי\"ן לא יכול למות <span data-k=\"sm\">[נ\"א: לא שייך שם מיתה]</span>, כי החכמה תחיה (את) בעליה ואין שייך בו שבירה, ולכך מ\"ה מתקן כל השבירה, (ואין) [והאי\"ן אין] יכול לקשר עצמו בתענוגים התחתונים, ולכך משה היה פרוש מן האשה. ולכך בפטירתו נסתם ממנו מעינות החכמה, מעיי\"ן החכמה הוא אי\"ן, <span data-k=\"sm\">[ואז היה יכול למות]</span>. ועתניאל בן קנז החזיר בפלפולו, שבא ממדריגות התחתונים (להשיג) [והשיג] אי\"ן, ובזה היה מחזיר ההלכות. והיה לו חשקה גדולה להתקשר שם (במשה) [כמו משה], אף שלא בא בוודאי למדריגת משה, אך <span data-k=\"sm\">[נ\"א: אך אעפ\"כ השיג מדריגה זו קצת]</span> והיה גם כן מובדל מן האשה. וזהו ארץ הנגב, אהבה רבה כנזכר, שאין בו טוב הגנוז בתחתונים כנזכר, אלא תורה ופרישות. ונתת לי גלות עליות, שיגיל בעליות, וגלות תחתיות, שיביא תענוג למדריגות תחתונות, והבן היטיב והדברים ברורים למבין.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רלב (רמו).</b>\n<i>כי ארץ הנגב גו' את גלות עליות גו'</i> – יהושע טו, יט.<i> והיה מקים את המשכן ולא אחר</i> – פקודי מ, יח. נשא ז, א. תנחומא תשא לא. שם פקודי יא. במ\"ר יב, יא. זח\"ב רלה סע\"ב.<i> כי שם חלקת מחוקק ספון</i> – ברכה לג, כא.<i> אזי נעשה הדבר מעצמו</i> – ראה תנחומא פקודי יא.<i> כמ\"ש במ\"א</i> – ראה מדל\"י סי' רכה (רלז).<i> בהבנותו</i> – מ\"א ו, ז.<i> שנבנה מעצמו</i> – שמ\"ר נב, ד. זח\"א עד, א. זח\"ב רכב סע\"ב.<i> החכמה תחיה בעליה</i> – קהלת ז, יב.<i> מ\"ה מתקן כל השבירה</i> – ע\"ח ש\"י פ\"א.<i> משה היה פרוש כו'</i> – שבת פז, א.<i> בפטירתו נסתם כו'</i> – סוטה יג, ב.<i> החכמה הוא אי\"ן</i> – תקו\"ז תמ\"ב פא, ב. שם ת\"ע קכז סע\"א וקלג רע\"ב.<i> ועתניאל בן קנז החזיר בפלפולו</i> – תמורה טז, א.<i> ארץ הנגב אהבה רבה</i> – ראה זח\"א קנג רע\"א.\n----- הערות וציונים -----\n<i>משה היה קשור ודבוק לאי\"ן</i> – ראה סי' שצד. וראה סי' רמח סד\"ה ולפי.\n<i>משה הביא אי\"ן לכאן</i> – ראה סי' יג סד\"ה וכשעשו, ובהערות שם.\n<i>ואין שייך בו שבירה</i> – ראה ריש סי' רצו.\n<i>והאי\"ן אין יכול לקשר כו'</i> – ראה סי' רמח סד\"ה והנה בצדיקים, וסי' תכד סד\"ה ותרין צדיקים, דאי\"ן אינו מתאוה לכלום."]]],[400080433,"שעא\n\n<b>קהלת,</b> שקיהל חכמות הרבה. ר\"ל שקיבץ כל החכמות אלוהו\"ת והקדושה מהשבירה. וסוד[ftnref_1_מח] השבירה הוא מרומז בפסוק הכל הבל[ftnref_2_מט], ורעו\"ת הוא לשון שבירה.",[["","","----- מקורות ומראה מקומות -----\n<i>קהלת . . מהשבירה:</i><b> מדל\"י סי' רכב (רלד). </b><i>וסוד השבירה כו':</i><b> שם ססי' רכ (במהדורת תו\"א צרפו לסוף סי' רלד).</b>\n<i>קהלת</i> – קהלת א, א.<i> שקיהל חכמות הרבה</i> – פרש\"י שם.<i> הכל הבל ורעו\"ת [רוח]</i> – קהלת א, יד.<i> ורעו\"ת הוא לשון שבירה</i> – תרגום ומפרשים עה\"פ.\n----- שולי הגליון -----\n[ftn_1_מח]) וסוד השבירה כו' <i>אינו במקבילו במדל\"י, אלא הוא שם בסוף סי' רכ (המובא לקמן סי' תצז)</i>.\n[ftn_2_מט]) <i>ע\"פ סגנון הספר בכלל נראה שחסר כאן המשך הפסוק וצ\"ל</i> הכל הבל ורעות רוח, ורעו\"ת <i>(כבפנים)</i>.\n----- הערות וציונים -----"]]],[400080434,"שעב\n\n<b>השיבה</b> שופטינו כבראשונה ויועצינו כבתחילה. ר\"ל שופטינו הם היצר טוב והיצר הרע, כמ\"ש רז\"ל צדיקים יצ\"ט שופטן ורשעים יצה\"ר שופטן. והם הב' מלאכים המלוים לאדם. וכשאדם מטיב מעשיו, מלאך הרע עונה אמן בעל כרחו כידוע, ואז שניהם הם השופטים אותו ומנהיגים אותו. וכן היה במעמד הר סיני, כי אז פסקה זוהמתן, והיו ב' השופטים שניהם כאחד טובים. ואנו מתפללים עתה השיבה שופטינו כבראשונה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ד, ד (סי' קג).</b>\n<i>השיבה שופטינו כבראשונה כו'</i> – עמידה לימי חול.<i> כמ\"ש רז\"ל צדיקים כו'</i> – ברכות סא, ב.<i> הב' מלאכים המלוים לאדם</i> – זח\"א קמד, ב. שם קסה סע\"ב.<i> וכשאדם כו' עונה אמן בע\"כ</i> – שבת קיט, ב. זו\"ח רות פה, א.<i> אז פסקה זוהמתן</i> – שבת קמו, א."]]],[400080435,"שעג\n\n<b>ידע</b> מה בחשוכא ונהורא עמיה שריא. ר\"ל הקב\"ה מקושר עם זה האדם שעושה את עצמו למ\"ה, ר\"ל ללא כלום, ולא עוד, אלא אפילו בחשוכא, כלומר אפילו כשהוא בין עניים הנקראים חשוכי\"ם, הוא משפיל את עצמו <span data-k=\"sm\">[נגדם]</span> מגודל הענוה, עם זה האדם הקב\"ה מקושר. ואם תאמר שאפשר שאדם הזה באמת הוא נמי שפל הערך (כמוהו) [כמותם], ואם כן מה רבותיה בענוותנותיה, לזה אמר ונהורא עמיה שריא, ר\"ל שהוא אדם גדול מאוד ואעפ\"כ הוא משפיל עצמו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ד, ד (סי' קא).</b>\n<i>ידע מה בחשוכא גו'</i> – דניאל ב, כב.<i> ידע . . מקושר</i> – ע\"פ בראשית ד, א.<i> למ\"ה ר\"ל ללא כלום</i> – ע\"פ בשלח טז, ז.<i> עניים הנקראים חשוכי\"ם</i> – ביצה לב, ב.\n----- הערות וציונים -----\nראה סי' שצד. רג\"כ סי' שמח ובהערות שם.\n<i>הקב\"ה מקושר עם כו'</i> – ר\"ל ידע לשון חבור והתקשרות (תקו\"ז תס\"ט צט, א) כדאיתא בדוכתי טובא בספר זה.\n<i>אפילו כשהוא בין עניים כו'</i> – להעיר מצוה\"ר סי' יב וסי' מח."]]],[400080436,"שעד\n\n<b>הוי</b> עיר הדמים, במדרש הוי מקמי קרתא (דשופכי) [דשפכו] דמים בגוה. ויש לפרש, כי הנה אמרו רז\"ל לא יאכל אדם עד שיתפלל שנאמר לא תאכלו על הדם. פירוש, דכתיב כי נפש כל בשר דמו בנפשו הוא, נמצא כי עיקר האדם הוא על שם הדם שבו. ולמה נקרא אד\"ם ולא נקרא ד\"ם, רק <span data-k=\"sm\">[נ\"א: אלא]</span> כשמדבק את עצמו בבורא יתברך וממשיך בקרבו אלופ\"ו של עולם, נתחבר האלף אליו, ואז נקרא אד\"ם. וזהו לא תאכלו על הד\"ם, ר\"ל כשעדיין לא חיבר אליו אלופו של עולם. רק אחר התפילה, כשחיבר דמו לאלופו של עולם ואז נקרא אד\"ם, אז מותר לו לאכול ולא קודם כנזכר. וזהו הוי עיר הדמים, פי' שהם נקראים דמי\"ם שאינם מחברים אלופו של עולם. והנה קשה למדרש והלוא כל העולם קודם תפילה נקראים ד\"ם, ומה זה הו\"י, ומתרץ המדרש דשפכ\"ו, פירוש לשון תפילה כמו אשפוך שיחו[ftnref_1_נ], עכ\"ז דמים בגוה, פירוש שהיו מתפללין שלא בכוונה והוי כאילו לא התפללו.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רטז (רכז)</b>\n<i>אוי עיר הדמים</i> – יחזקאל כד, ו.<i> במדרש אוי מקמי כו'</i> – איכ\"ר פתיחתא ה.<i> לא יאכל אדם כו'</i> – ברכות י, ב.<i> לא תאכלו על הדם</i> – קדושים יט, כו.<i> כי נפש כל בשר גו'</i> – אחרי יז, יד.<i> אלופ\"ו של עולם . . האלף</i> – זח\"ג לא, א.<i> אשפוך לפניו שיחי</i> – תהלים קמב, ג.\n----- שולי הגליון -----\n[ftn_1_נ]) <i>במדל\"י</i> אשפוך שיחי <i>ע\"פ תהלים קמב, ג אשפוך לפניו שיחי. או אפשר ע\"פ תהלים קב, א ישפך שיחו. בכל אופן צריכים לתקן הלשון</i>.\n----- הערות וציונים -----\n<i>ולמה נקרא אד\"ם כו' ואז נקרא אד\"ם</i> – ראה סי' קלד."]]],[400080437,"שעה\n\n<b>אין</b> כאלקינו הוא בעולם עשיה, שהוא כמו ספר שבוודאי אי אפשר לטעות. מי כאלקינו הוא בעולם היצירה, שאפשר חלילה לטעות, כמו אחר שטעה שראה מטטרו\"ן וכו'. אך אני איני טועה כי מי כאלקינו. נודה לאלקינו הוא בעולם הבריאה, ששם אי אפשר לטעות מפני שקרובה לאצילות. ובאצילות אומר לנוכח אתה הוא אלקינ\"ו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ד, ב (סי' צו).</b>\n<i>אין כאלקינו כו'</i> – סידור בסוף תפלת השחר.<i> אין כו' בעולם עשיה, מי כו' נודה כו' אתה כו'</i> – סידור האריז\"ל להר\"ש שם (קיד, ב).<i> אחר שטעה כו'</i> – חגיגה טו, א.\n----- הערות וציונים -----\nבסידור האריז\"ל להר\"ש שם דבבא דברוך נגד אצילות שהוא ברוך מהא\"ס כו' ובבא דאתה הוא נגד עולמות הנעלמים וכולהו אקרי א\"ס וכו'."]]],[400080438,"שעו\n\n<b>סוד</b> כי חפץ חסד הוא האמור במדות דאריך אנפין, ובזעיר אנפין נאמר ורב חסד. ובמקום אחר נקרא זעיר אנפין חסד סתם, כמ\"ש חסד לאברהם.\n<b>ויש</b> לומר משל על זה. יש אדם שהוא מכניס אורח, והוא נקרא בעל חסד. היינו כשרואה אורח מכניסו לתוך ביתו ועושה עמו חסד, אבל אין לו התלהבות וחשקות תמיד להכניס אורחים ולעשות עמם חסד ולחזור אחר זה, אלא אם נזדמן לו אורח עושה עמו חסד. ויש שאינו נפסק מרצונו הזה, שהוא חושק תמיד בלי הפסק לעשות חסד עם בני אדם ומחזיר תמיד אחר זה. כמו אברהם אבינו ע\"ה, שהיה מצטער מאוד כשלא היה לו אורחים לעשות עמם חסד. והמדה הזו היא באריך אנפין שנקרא רצו\"ן, כי רצונו תמיד לעשות חסד. לכן כתיב במדותיו כי חפץ חסד הוא, ורצונו תמיד לעשות חסד. ובזעיר אנפין הוא מדה סתם, שאין לו רצו\"ן זה כמו באריך אנפין. אך בשעה שאריך אנפין מאיר בזעיר אנפין, נקרא אז זעיר אנפין ורב חסד, כי אז קיבל מאריך אנפין חסדים הרבה. לכן בי\"ג מדות שקיבל זעיר אנפין מאריך אנפין נאמר ורב חסד.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ד, ב (סי' צב).</b>\n<i>כי חפץ חסד הוא</i> – מיכה ז, יח.<i> האמור במדות דא\"א</i> – זח\"ג קלא, ב.<i> ובז\"א נאמר ורב חסד</i> – זח\"ג קמ סע\"א.<i> ורב חסד</i> – שלח יד, יח.<i> ובמ\"א נקרא ז\"א חסד סתם</i> – זח\"ג קמ, ב. זח\"ב קעז סע\"ב.<i> כמ\"ש חסד לאברהם</i> – מיכה ז, כ.<i> אברהם אבינו ע\"ה שהיה מצטער כו'</i> – פרש\"י וירא יח, א.<i> והמדה הזו היא בא\"א שנק' רצו\"ן</i> – זח\"ג רפח, ב. שם קכט, א.\n----- הערות וציונים -----\n<i>משל על זה כו'</i> – המשל בהבדל בין חפץ חסד ורב חסד הובא בקיצור באוה\"א נה, א, ושמועה טובה סז, ב. ובענין חפץ חסד באורח לחיים פ' וירא ד\"ה וה' אמר (ושם פ' וארא רד\"ה הוא אהרן ומשה). וראה עוד בענין חפץ חסד ורב חסד בסי' קמ ד\"ה והנה אמרו. וראה מדל\"י סי' צז (קו)."]]],[400080439,"שעז\n\n<b>עיניך</b> בשדה אשר יקצורון. <span data-k=\"sm\">[פי' דכתיב טוב עין הוא יבורך]</span>. כי עי\"ן נקרא חכמ\"ה, ובאמת ההסתכלות הוא מדריגה תחתונה של החכמה. ומי שהוא טוב עי\"ן, דהיינו עי\"ן החכמה <span data-k=\"sm\">[נ\"א: חכמה טובה]</span>, כשהוא מסתכל בדבר מביא ברכה באותו דבר. לפי שהוא יודע <span data-k=\"sm\">[נ\"א: כי כשמסתכל בדבר יודע]</span> שהדבר ההוא כאין נגדו יתברך, דהיינו שהוא באמת אפס ואי\"ן בלתי אלקותו ית' השרוי בתוכו, דהיינו כח הפועל בנפעל, <span data-k=\"sm\">[וזולתו הוא אפס, על דרך ונחנו מה]</span>. אז על ידי הסתכלות הזה ממשיך חיות יותר לאותו דבר מאלקותו יתברך. וזהו טוב עי\"ן הוא יברך אותו דבר <span data-k=\"sm\">[נ\"א: יבורך לאותו דבר]</span>. וכן להיפך ח\"ו, מי שהוא רע עי\"ן, כשהוא מסתכל על הדבר אומר <span data-k=\"sm\">[נ\"א: ומתמיה עליו, דהיינו]</span> מה נאה דבר זה, ועושה אותו הדבר לדבר בפני עצמו, והוא ח\"ו נרגן מפריד אלוף, שעל ידי הסתכלותו נפרד אותו הדבר מהשורש ומהחיות, <span data-k=\"sm\">[דהיינו]</span> אלקות שבו. כי ההסתכלות עושה כלי <span data-k=\"sm\">[ועל ידי זה בא עין הרע ר\"ל</span>[ftnref_1_נא]<span data-k=\"sm\">]</span>. ועיקר השבירה היתה מחמת זה שכל אחד אמר אני אמלוך. פירוש, כי מדת מלכות נקרא בכל דבר <span data-k=\"sm\">[ובכל מדה]</span> שהוא בפני עצמו לגמרי, <span data-k=\"sm\">[וזהו נקרא מלוכה של הדבר וגמרו. וכן כל מלך הוא ג\"כ על שם כך, שהוא מלוכה בפני עצמו וגמרו]</span> ואינו צריך שוב לשום דבר. <span data-k=\"sm\">[וכן בכל דבר מדת מלוכה של אותו דבר הוא שיהיה דבר בפני עצמו, ושיהיה נקרא דבר. דרך משל, מדת חסד כשנקרא אותו מדה מדת חסד הוא נקרא גמרו של הדבר ומלכותו]</span>. ובאמת לא שייך זה כי אם באלקותו יתברך בלבד, ולא על שום דבר, כי כולם צריכים לינק משורש אלקותו, <span data-k=\"sm\">[ובלעדיו כולם לאפס ותוהו נחשבו]</span>. ומתחילה כשנמשכין המדות <span data-k=\"sm\">[מעט]</span> משורש אלקות\"ו <span data-k=\"sm\">[עדיין]</span> היה מוטבע בהם מדת אני אמלוך כמו שהוא בשורש, כי בשורש שייך מדה זו <span data-k=\"sm\">[כמבואר]</span>, והם היו נעלמים תחילה בהשורש, ועל כן גם אח\"כ היה להם בטבע מדת אני אמלוך. ובאמת <span data-k=\"sm\">[עכשיו]</span>, כשכבר נמשכו, לא שייך להם מדה זו, ועל כן נפסקו מהשורש, <span data-k=\"sm\">[דהיינו שנפסק]</span> ויצא החיות שלהם. ובעת <span data-k=\"sm\">[נ\"א: ואח\"כ בעת]</span> התיקון היה <span data-k=\"sm\">[התיקון]</span> על ידי <span data-k=\"sm\">[שם]</span> מ\"ה, על דרך ונחנו מה.\n<b>ופעולת</b> השבירה היה <span data-k=\"sm\">[צורך העולם, כי אם היה כל דבר וכל מדה דבוקה בהשורש והיתה כאי\"ן בעיני עצמה, לא היה קיום לכל העולמות]</span>. על דרך משל, אם היה דביקות בהם תמיד בלי שכחה, רק תמיד היו דבוקים בהבורא יתברך, היו כולם בטלים ממציאות[ftnref_2_נב]. על כן הוכרח להיות השבירה, ועי\"ז נעשה שכחה מהשורש, <span data-k=\"sm\">[ויכול כל אחד להרים ידו לעשות מעשה]</span>. ואח\"כ בתורה ותפילה מדבקים את עצמן להשורש לאין, <span data-k=\"sm\">[על דרך ונחנו מ\"ה]</span>, ומעלים <span data-k=\"sm\">[נ\"א: ובזה מעלים]</span> ניצוצות מהשבירה <span data-k=\"sm\">[נ\"א: של עולם העשיה, וכן בכל עולם עד רום המעלות]</span>, וגורמים תענוג גדול אל השי\"ת. כי אינו דומה תענוג תמידי לתענוג זה, <span data-k=\"sm\">[על דרך משל אב שלא ראה את בנו זה זמן רב ואחר כך בא אצלו, גורם להאב תענוג גדול יותר שאם היה אצלו תמיד, וגם הבן שלא ראה את האב זמן רב יש לו יותר חשק ומתאוה יותר לראות עצמו עם אביו]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קו (קיז). אוה\"א לו, א.</b>\n<i>עיניך בשדה גו'</i> – רות ב, ט.<i> טוב עין הוא יבורך</i> – משלי כב, ט.<i> עי\"ן נקרא חכמ\"ה</i> – ע\"ח ש\"ד פ\"א. שם ש\"ח פ\"א.<i> נרגן מפריד אלוף</i> – משלי טז, כח.<i> ההסתכלות עושה כלי</i> – ע\"ח ש\"ד פ\"ג.<i> ועיקר השבירה היתה כו' אני אמלוך</i> – ראה ע\"ח היכל הנקודים, ובפרט שי\"א פ\"ה. מבו\"ש ש\"ב ח\"ב.<i> התיקון היה ע\"י מ\"ה</i> – ע\"ח ש\"י פ\"א.<i> ונחנו מה</i> – בשלח טז, ז.\n----- שולי הגליון -----\n[ftn_1_נא]) <i>הר\"ת</i> ר\"ל <i>צ\"ע אי קאי אדלעיל, ופי'</i> רחמנא ליצלן, <i>או אדלקמן, ופי'</i> רצה לומר עיקר השבירה כו' <i>(כפי' הנוסח אשר במדל\"י משם העתקתי הנ\"א)</i>.\n[ftn_2_נב]) <i>נ\"א במדל\"י:</i> דרך משל, עולם העשיה אלו היה דבוק להבורא תמיד בלי שום שכחה*, לא היו עושים שום דבר כי היו עושים שום דבר כי היו מחזיקים את עצמם לאי\"ן, וגם מחמת גודל היראה והבושה מהשורש היו כולם בטלים ממציאותם והיו מתדבקין עצמן להשורש לאי\"ן, וכן בכל העולמות. <i>(ולהעיר ששם נכפלו המילים \"היו בטלים ממציאותם והיו מתדבקים א\"ע להשורש לאי\"ן\" במקום שנסמן בכוכב (בתוספת מלת חיבור \"וכן\"), שלא במקומן שהוא בהמשך הדברים כדלעיל)</i>.\n----- הערות וציונים -----\n<i>ההסתכלות הוא כו' אז ע\"י הסתכלות הזה כו'</i> – ראה סי' יג סד\"ה וכשעשו, ובהערות שם.\n<i>וכן להיפוך ח\"ו כו' לדבר בפני עצמו כו'</i> – להעיר מסי' תמב.\n<i>ועיקר השבירה היתה מחמת כו'</i> – עיין לקו\"ת לאדה\"ז פ' תזריע כג רע\"א מש\"כ בשם הרה\"מ. וראה סוף סי' קעו ובהערות שם.\n<i>התיקון על ידי מ\"ה כו'</i> – ראה סי' לו ד\"ה ואפשר לומר שזה, ובהערות שם.\n<i>הוכרח להיות השבירה כו'</i> – להעיר מע\"ח שער הכללים פ\"ב. שם שי\"א פ\"ו. שער מאמרי רז\"ל, אבות רפ\"ה. ורג\"כ פרדס רמונים שכ\"ה פ\"ג.\n<i>כי אינו דומה תענוג תמידי כו'</i> – דתענוג תמידי אינו תענוג, ראה בהערות לסי' לה.\n<i>על דרך משל כו'</i> – השוה סי' תכד סד\"ה וז\"ש ויקח, וסי' תנה ד\"ה ומה."]]],[400080440,"שעח\n\n<b>דע</b> את אלקי אביך, שתהיה מקושר אליו בהתפשטות הגשמיות <span data-k=\"sm\">[ותהא רואה שיש אלהים בעולם, ואף אם הכופרים אומרים [לך] מנא לך הא, לא יציית אותם. כמשל אחד ראה בגשמיות שדבר זה הוא זהב, אע\"פ שאומרים לו שאינו זהב, אף על פי כן יודע האמת שהוא זהב. כך כשרואה בעין שכלו את הש\"י לא מפסיד באמונתו שום דבר (נ\"א: לא יפסוד שום דבר את אמונתו).]</span>.\n<b>ומתחילה</b> נופלת עליו יראה שירא לעצמו שימות מיד, ואם יקבל על עצמו אף מיתה, אזי תפול עליו יראה העיקרית. וזהו כבוד נאצל. כי העבודה הפשוטה הוא כבוד נברא. פי' כבוד נברא הוא מחמת שרואה כל הנבראים שבעולם, ומחמת זה מכיר כבודו יתברך ועובד אותו, כי מכח גדולת העבד ניכר גדולת רבו. והוא נקרא עבד להש\"י, שעובד אותו מחמת עבדיו. אבל בשביל כבוד נאצל יבוא למדריגת בן, כמו הבן שאוהב את אביו אע\"פ שלא עשה לו שום טובה. ונאצל הוא לשון הפרשה, שנפרש ממנו השגת ידיעת השי\"ת כלל. וכל מה שיש יותר העלמה, העבודה יותר חשוב אצלו, ובשביל זה אוהב אותו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י טו, ג (סי' קצג). אוה\"א ג, א. לקו\"א לד, א.</b>\n<i>דע את אלקי אביך</i> – דה\"א כח, ט.<i> דע . . מקושר</i> – ע\"פ בראשית ד, א.<i> בהתפשטות הגשמיות</i> – ראה טושו\"ע או\"ח ריש סי' צח.<i> כבוד נאצל . . כבוד נברא</i> – תקו\"ז ו, ב.<i> מכח גדולת העבד כו'</i> – כתר מלכות לרשב\"ג, סוף הבבא מי יכיל. ר\"ח שער היראה פ\"ב. של\"ה, תושב\"כ פ' יתרו ד\"ה לא יהיה לך.<i> ונאצל הוא לשון הפרשה</i> – פרש\"י תולדות כז, לו.\n----- הערות וציונים -----\n<i>דע . . שתהא מקושר</i> – ראה סי' שסט.\n<i>כבוד נאצל . . כבוד נברא</i> – ראה אוה\"א כח, א (ובכתבי קודש כג, ד עד \"אלקותו ית'\"): יש כבוד נאצל ויש כבוד נברא, כבוד נברא הוא מלכות דבריאה שהוא עובד הקב\"ה מחמת בחי' הברואים ומהברואים נקרא השי\"ת בשם הברואים [אלקים] שהברואים מקבלים אלקותו ית'. וכבוד נאצל הוא מלכות דאצילות שהוא עובד הקב\"ה מחמת עצמותו ית', ושם הוי' ב\"ה נקרא עצמותו, שם העצם. ובכתבי קודש ט, ד: כבוד נאצל הוא כשעלה ברצונו להשיג עילויו ומבינו בשכלו שלו, כי העילוי הוא א\"ס. וכבוד נברא כשרוצה להשיג ומביט בברואים ומכח הברואים ומבינו בבורא ית', נמצא זה מיעוט והבן. וראה סי' נב בענין תפארת בריאה ותפארת אצילות.\n<i>מחמת שרואה כל הנבראים שבעולם ומחמת זה מכיר כו'</i> – ראה סי' שסו."]]],[400080441,"שעט\n\n<b>וחנה</b>[ftnref_1_נג] מדברת על לבה. פירוש, וחן הה' מוצאות הפה כשהם (מחונכי') [מחוננים] לפני הקב\"ה, מדברת, ר\"ל הם נדברים, על לבה, כביכול למעלה (מ)[ב]עולם המחשבה. וזהו ואתחנן אל ה', ר\"ל וא\"ת, הם כ\"ב אותיות, חנ\"ן, חנינות <span data-k=\"sm\">[נ\"א: חננתי]</span>, אל ה' בעת ההיא לאמר. שיש כ\"ח עתים י\"ד טובות וי\"ד רעות, וזהו בעת ההיא, <span data-k=\"sm\">[ע\"ת]</span> שהיא נוקבא דהיינו עת רעה, לאמר, רצה לומר הביאותם לעולם המחשבה, אמירה היא מחשבה <span data-k=\"sm\">[בלב]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' סד (עז). אוה\"א יז, ב.</b>\n<i>וחנה מדברת על לבה</i> – ש\"א א, יג.<i> ואתחנן אל ה' בעת ההיא לאמר</i> – ואתחנן ג, כב.<i> וא\"ת הם כ\"ב אותיות</i> – זח\"א טו, ב. שם כט, ב. אליהו רבה פי\"ח.<i> שיש כ\"ח עתים כו'</i> – קהלת ג, ב-ח. תקו\"ז תס\"ט קא, א.<i> אמירה היא מחשבה</i> – זח\"ב יז, א. זח\"ג קסא, א.\n----- שולי הגליון -----\n[ftn_1_נג]) <i>סי' שעט-שפ לעיל סי' קפז בשנויים קלים</i>.\n----- הערות וציונים -----\nכבר הובא לעיל סי' קפז."]]],[400080442,"(שפ)\n\n<b>כנפים</b> נקראים מה שהולכים ממדריגה למדריגה בעבודת השי\"ת, <span data-k=\"sm\">[וזהו בעמדם, ישראל בתפלה, תרפינה כנפיהם]</span>. שהמלאכים אומרים בלבם שעבודתם אינה כלום נגד עבודת בני אדם. כי המלאך הוא גדול כמו שליש עולם, והאדם הוא הקטן. וכאשר האדם יתן אל לבו לדבר באהבה ויראה הלוא השכינה משתוקקת לדברים אלו כמו האם המשתוקקת שידבר בנה דבר של שכל כדי שתתחשב לפני בעלה. כך כשהדיבורים באים למעלה מכח האדם מקושטים בזה הכח, נולד התפארות גדול, והמלאכים אומרים מי כעמך ישראל גוי אחד בארץ. ולכך עדיף שיאמר <span data-k=\"sm\">[אפילו]</span> תיבה אחת <span data-k=\"sm\">[בתפלה]</span> באהבה ויראה, כי בזה מעורר שכל המלאכים אומרים שירה להקב\"ה. וגם הוא מעורר כל העולמות, כשהוא עובד להקב\"ה כל העולמות עובדים אותו יתברך.\n<b>וזהו</b> <span data-k=\"sm\">[שיר השירים]</span>, כשאדם אומר למטה שיר אחד מעורר למעלה השירים, דהיינו שירים הרבה. <span data-k=\"sm\">[אימתי]</span>, אשר לשלמה, ר\"ל כאשר הוא להקב\"ה, <span data-k=\"sm\">[ברצון מלך שהשלום שלו]</span>, דהיינו בדחילו ורחימו. כי בלא דחילו ורחימו לא פרחא לעילא.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' סד (עז) אוה\"א יז, ב. [המשך לסי' שעט]</b>\n<i>[בעמדם ישראל בתפילה כו'</i> – ראה תנחומא קדושים ו.<i> בעמדם תרפינה כנפיהם</i> – יחזקאל א, כד].<i> המלאך הוא גדול כו'</i> – בר\"ר סח, יב.<i> והמלאכים אומרים מי כו'</i> – זח\"ב קנה, ב. זח\"ג קג, ב.<i> מי כעמך ישראל גו'</i> – דה\"א יז, כא. (בזוהר שם מש\"ב ז, כג).<i> בזה מעורר שכל המלאכים כו'</i> – ראה חולין צא סע\"ב. זח\"א מ, א.<i> שיר השירים</i> – שה\"ש א, א.<i> לשלמה כו' להקב\"ה</i> – ראה במ\"ר יב, ד.<i> בלא דו\"ר לא פרחא לעילא</i> – תקו\"ז ת\"י כה, ב.\n----- הערות וציונים -----\nראה הערות וציונים לעיל סימן שפ."]]],[400080443,"שפא\n\n<b>ומועדים</b> לשמחה. פי' מי שאינו הולך <span data-k=\"sm\">[נ\"א: שרגיל לילך]</span> במלבושים נאים, ופעם אחת לובש מלבוש יפה מאוד, אז יש לו שמחה גדולה. וכן הוא ביום טוב, שאז כל העולמות לובשים מלבושים יקרים רוחניים והשכליים, לכן השמחה מתרבה בהם.",[["","","----- מקורות ומראה מקומות -----\n<b>כתבי קודש כד, ג.</b>\n<i>ומועדים לשמחה</i> – עמידה דיו\"ט.\n----- הערות וציונים -----\nהובא באה\"ת להצ\"צ פ' פנחס ע' א'רג בתוס' ביאור. ולהעיר משו\"ע או\"ח ריש סי' תקכט בענין בגדי יו\"ט. ולעיל סוף סי' פו."]]],[400080444,"שפב\n\n<b>וקוי</b> ה' יחליפו כח וגו' ירצו ולא ייגעו וגו'. דאיתא בספר יצירה אין למעלה מעונג ואין למטה מנגע. ואפשר לומר כי עונג הוא עולם התענוג <span data-k=\"sm\">[היינו החכמה]</span>, וההשגה נקרא גם הוא עולם התענוג. ונאמר ראשית חכמה יראת ה', <span data-k=\"sm\">[ר\"ל]</span> שיש למדה זו בושה גדולה נגד מה שלמעלה ממנו, הואיל שהוא <span data-k=\"sm\">[משיג יותר ו]</span>קרוב יותר למלכות מאוד, ומגודל (התענוג) [ההכנעה] אינו מרגיש התענוג <span data-k=\"sm\">[נ\"א: בתענוגו]</span>. למשל השר העומד לפני המלך תמיד, מגודל הבושה והתענוג אינו <span data-k=\"sm\">[מרגיש את עצמו ואינו משיג בתענוג הגדול, לפי שכבודו בטל ממציאות נגד התענוג הגדול. אבל מי שאינו בתמידות אצל המלך מרגיש התענוג יותר, כשבא לביתו ומרגיש ומשיג את עצמו ומחשב שהוא קרוב למלכות יש לו תענוג. אבל מי שהוא בתמידות אצל המלך, מגודל הבושה והתענוג אינו]</span> משיג כבודו כלל. וזהו סייג לחכמה שתיקה, כי חכם אינו מדבר לפני מי שהוא גדול ממנו. ואדם עומד תמיד לפני המלך מלכו של עולם, ולכך אינו ראוי לדבר לפניו. וזהו אי\"ן למעלה מעונג, כלומר אי\"ן הוא למעלה מן העונג <span data-k=\"sm\">[ר\"ל שהוא גדול יותר מהתענוג כנ\"ל]</span>. ואי\"ן למטה וכו', כי הקב\"ה הוא סובל כל עלמין וסובב כל עלמין והוא בתוך כל עלמין וממלא כל עלמין, כי הקב\"ה כביכול מצמצם אורו אפילו במדריגה הפחותה שבגשמיות. נמצא כשתחקור ותבין כל הדברים ישיג עצם כבודו ית' <span data-k=\"sm\">[אפילו שם]</span>, וזהו אין למטה מנגע.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רכד (רלז).</b>\n<i>וקוי ה' יחליפו כח גו'</i> – ישעיה מ, לא.<i> אין למעלה מעונג כו'</i> – ס\"י פ\"ב מ\"ד.<i> ראשית חכמה גו'</i> – תהלים קיא, י.<i> סיג לחכמה שתיקה</i> – אבות פ\"ג מי\"ג.<i> הקב\"ה הוא סובל כו'</i> – זו\"ח יתרו לד, ד. זח\"ג רכה, א.\n----- הערות וציונים -----\nכאן חסר ההמשך שהובא במדל\"י עם ביאור הפסוק בד\"ה. ובקדושת לוי, שלהי לקוטים בד\"ה איתא במדרש: ששמעתי מכבוד אדמ\"ו מוה' דוב בער זצל\"ה נ\"ע ע\"פ וקוי ד' יחליפו כח היינו שמחליפים את כחם כאדם שמחליף דבר על דבר, כן קווי ה' מחליפים את כחם בעבודתם בביטול במציאות להקב\"ה ועי\"ז נמשך להם מהבורא ב\"ה השגת אלקות בתורה ומצות. (וראה מש\"כ שם בפ' ראה בד\"ה ראה אנכי (הב').)\n<i>עולם התענוג היינו חכמה</i> – ראה סי' סז ד\"ה ואפשר. וראה סי' שסג ד\"ה ויש.\n<i>וזה סייג לחכמה שתיקה כו'</i> – ראה סי' תעח."]]],[400080445,"שפג\n\n<b>להגיד</b> בבוקר חסדיך ואמונתך בלילות. פי' כשאדם בבהירות, ר\"ל בדביקות, חסדיך. ואמונתך בלילות, פירוש כשאדם לפעמים נופל ממדריגה והוא בחשיכה בענין הדביקות, אז על כל פנים יהיה לאדם זה האמונה הידוע. וזכור כי בוקר ויום הנזכר בפסוק הוא לשון בהירות, וערב ולילה הנזכר בפסוק הוא לשון (עבירה) [עכירות][ftnref_1_נד].",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י ד, ד (סי' ק)</b>\n<i>להגיד בבוקר חסדיך גו'</i> – תהלים צב, ג.\n----- שולי הגליון -----\n[ftn_1_נד]) <i>בלקו\"י</i> לשון עבירות.<i> ונראה שצ\"ל </i>לשון עכירות, <i>לעומת בהירות דבוקר ויום, וכנ\"ל \"והוא בחשיכה בענין הדביקות\"</i>.\n----- הערות וציונים -----\nשייך לחלק תהלים.\nכבר הובא לעיל סי' רעט."]]],[400080446,"שפד\n\n<b>וכל</b> בניך למודי ה' <span data-k=\"sm\">[ר\"ל שמלמדין את ה' האיך לעשות].</span> על דרך תפילתו של חוני המעגל שהיתה משנה כביכול רצון הבורא יתברך. וכן משה רבינו ע\"ה, כדאיתא בזוהר זכור לאברהם ליצחק (וליעקב) [ולישראל עבדיך], אחיד ליה בדרועיה וגופיה. פי' כמשל אחד שלוקח את חבירו אצל היד ואינו מניח אותו לילך ומשנה רצונו. כך כביכול אחז אותו באהבה ויראה ומשנה רצונו יתברך. וכן רבי יהושע אמר אין משגיחין בבת קול, ואמר הקדוש ברוך הוא נצחוני בני. וזהו <span data-k=\"sm\">[וכל]</span> בניך למודי ה' שלומדים כביכול את השי\"ת[ftnref_1_נה].",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ב, א. לקו\"א לג סע\"א. [מדל\"י סי' קמט (קנז).]</b>\n<i>וכל בניך למודי ה'</i> – ישעיה נד, יג.<i> תפלתו של חוני המעגל כו'</i> – תענית יט, א.<i> זכור לאברהם גו'</i> – כי תשא לב, יג.<i> אחיד ליה כו'</i> – תקו\"ז תכ\"א נד, ב. ראה זח\"ב קצג, ב.<i> רבי יהושע אמר אין משגיחין כו'</i> – ברכות נב, א, ב\"מ נט, ב.<i> ואמר הקב\"ה כו'</i> – ב\"מ נט, ב.\n----- שולי הגליון -----\n[ftn_1_נה]) <i>במדל\"י כמה שנויים קלים בנוסח וסדר הדברים. ובכל המקבילות כאן המשך: </i>הבן מעלה באביו התפארות [שמתפאר בבן שלו] וכל המדות אהבה ויראה [נולד בו]. וכן [כביכול] למעלה, כשאנו עושין מעשים טובים שיהיה להקב\"ה תענוג, אנו מגדלין להקב\"ה כביכול [נ\"א: מגדילין כביכול אהבה ויראה והתפארת]. <i>והשוה מדל\"י סוף סי' קיב (קכג):</i> הכל תלוי בידי אדם, אם כן זה שכתוב וכ\"ל בני\"ך, ר\"ל מי שהוא על דרך הכל בן. שיש אדם שלפעמים עובד מאהבה הנקרא בן, ולפעמים אפילו עבד אינו. אבל מי שהוא הכל בן, הוא למודי ה', כביכול כאלו מלמד להש\"י האיך לעשות, כר' יהושע וכר' חנינא בן דוסא.\n----- הערות וציונים -----\nכן עד\"ז במדל\"י סי' קיא-קיב (קכג). וראה ג\"כ מאור עינים ליקוטים ד\"ה וזהו פי' הפסוק ואני תפילתי: וזה אמר מ\"ו וכל דבריך יהיו בנח\"ת, וכשהבן עושה רצון אביו מפני הנחת רוח מתרחב דעתו של אביו, וזהו וכל בניך למודי ה' שמלמדים את הש\"י כב\"י לעשות רצונם וחפצם כמאמר הכתוב צדיק מושל גו'. ועיי\"ע לקו\"י סי' קכד.\n<i>וכן רבי יהושע אמר כו'</i> – ראה סי' רנח ד\"ה אבל, ובהערות שם."]]],[400080447,"שפה\n\n<b>למה</b> היו הראשונים מתפללים ונענים, מפני שהיו מתפללים בשם. פי' כמו שהשושבין רוצה להביא את הכלה לפני החתן, כך החתן רוצה שיביאו את הכלה לפניו. וזהו שהיו מתפללים בשם, שמה שהם רוצים היה רוצה. <span data-k=\"sm\">[נ\"א: שמה שהיו רוצים, הוא שיהיה השם רוצה]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ב, א. לקו\"א לג, א.</b>\n<i>מתפללים בשם</i> – ראה מדרש תהלים צא, ח. פסיקתא רבתי סוף פ' כב.\n----- הערות וציונים -----\nבס' דברי אמת להחוזה ס\"פ נשא באו\"א: שמעתי מהרב המגיד מראוונא האיש האלקים ז\"ל מפני מה ראשונים התפללו ונענו שהיו מתפללים בשם, פי' שהיה כוונתם להשי\"ת, כי כשאדם יש לו צער חלק אלקי ממעל שבו יש לו צער ופשוט, שאיתא בש\"ס ר\"מ [סנהדרין מו, א] אפילו יחיד המצטער שכינה מה היא אומרת קלני מראשי וכו'. (ראה מזה כש\"ט סי' כ וסי' קכו והנסמן שם בהערות. וראה לעיל סי' נו ובהערות שם). ושם פ' שופטים ד\"ה ושרת: שמעתי בשם רבי ז\"ל הרב המגיד מראוונא . . פי' שהתפללו בשביל שמו ית'.\n<i>שמה שהם רוצים היה רוצה</i> – ראה סי' ס ד\"ה והנה נמשיל, ובהערות שם."]]],[400080448,"שפו\n\n<b>כשנופלת</b> לו מחשבה זרה בתפילתו אזי יתבושש עד מאוד, כי דחפו אותו מהיכל המלך, וישוב לתוך ההיכל בבושה רבה ובהכנעה רבה. ועוד, כי מחשבה זרה היא עבירה <span data-k=\"sm\">[גדולה]</span> כמו מוליד ממזר, על דרך רחילא בתר רחילא אזלא <span data-k=\"sm\">[כאשה כן בתה]</span>, כי כמו שהמחשבה היא דכר ונוקבא כך הקול והדיבור הם דכר ונוקבא. ואם יש לו מחשבה זרה ומדבר דברי קודש הוי כמו ממזר, שיש לו צורה כמו אדם הפשוט <span data-k=\"sm\">[נ\"א: הכשר]</span> רק הפנימיות הוא רע. כך הקול והדיבור הוא באותיות קדושות, רק המחשבה היא רעה, שחושב דבר אחר ומוליד ממזר דיבור קודש. ועוד יחשוב כי הקב\"ה אומר <span data-k=\"sm\">[מדוע באתי ואין איש]</span>, מדוע באתי בהתיבה ואין איש בהתיבה[ftnref_1_א], כי מחשבתו משוטטת בדברים אחרים.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ב, א. צוה\"ר סי' פט. לקו\"א לג, א.</b>\n<i>דחפו אותו מהיכל המלך</i> – ראה זח\"ב רמה, ב.<i> רחילא בתר רחילא אזלא</i> – כתובות סג, א.<i> שהמחשבה היא דו\"נ</i> – (או\"א) ראה זח\"ג רכט סע\"ב.<i> הקול והדיבור הם דו\"נ</i> – תקו\"ז תס\"א צג סע\"ב.<i> מדוע באתי גו'</i> – ישעיה נ, ב.\n----- שולי הגליון -----\n[ftn_1_א]) <i>בצוה\"ר:</i> ומדוע באת בהתיבה ואין אני בהתיבה.\n----- הערות וציונים -----\n<i>כי דחפו אותו מהיכל המלך</i> – ראה סי' נ ד\"ה וזהו פי' וימלוך. סי' שיד ד\"ה וזה קול. סי' תו ד\"ה האומר. מדל\"י סי' מז (נג). צוה\"ר ריש סי' פז.\n<i>כשנופלת לו מ\"ז היא עבירה כמו מוליד ממזר כו'</i> – עיין מדל\"י סי' קמח (קנו). וראה סי' קז ד\"ה או ראה. להעיר מענין ממזר תמורה (מס' כלה פ\"א. נדרים כ, ב), עיין לקו\"י סי' צ.\n<i>הקול והדיבור הם דכר ונוקבא</i> – ראה ריש סי' קה."]]],[400080449,"שפז-א\n\n<b>אלקיכם</b> כהן הוא. פי' דאין עובדים את השי\"ת אלא בכח שנתן, ובמחשבה ובדיבור זאת היא עולם המחשבה ועולם הדיבור. נמצא כי מחמתו עובדים אותו. וזהו הקב\"ה כהן הוא, שעובד בעצמו כביכול את עצמו[ftnref_1_ב].",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ב, א. לקו\"א לג, ב. מדל\"י סי' קנ (קנח) </b><i>[עד נמצא]</i><b>.</b>\n<i>אלקיכם כהן הוא</i> – סנהדרין לט, א.\n----- שולי הגליון -----\n[ftn_1_ב]) <i>במדל\"י:</i> אלהיכם כהן הוא, ר\"ל שעובד את עצמו. כי מחמת כח הניתן במחשבה מעולם המחשבה, ובדיבור מעולם הדיבור, האדם מחשב ומדבר.\n----- הערות וציונים -----\nלהעיר מסי' רעג ובהערות שם. וראה מדל\"י סי' קמו (קנד): יחשוב שעולם הדיבור מדבר בו וזולתו א\"א לדבר כמ\"ש אד' שפתי תפתח, וגם כן מחשבתו א\"א להיות כ\"א ע\"י עולם המחשבה, והוא כשופר, כי מה שתוקעין בתוכו אותו הקול הוא מוציא ואם יפרוש ממנו התוקע אז לא יצא קול, כך בהעדר ח\"ו ית' ממנו אינו יכול לדבר ולחשוב. ובאורח לחיים פ' האזינו בד\"ה זכור: שמעתי בשם הרב בוצ\"ק מהו' דוב בער זללה\"ה פירוש הפסוק כשופר הרם קולך ר\"ל האדם צריך לחשוב א\"ע כאין ואין בו שום זכות ומע\"ט ואעפ\"י שעושה מצות ומעשים טובים הוא אינו עושה כי עושה בכח הש\"י ובשכלו ובחסדו ובטובו שהיטיב לו, ע\"ד מי הקדימני ואשלם, וגם בתפלתו יחשוב שעולם הדיבור מדבר בו ומחשבתו הוא עולם המחשבה והוא כשופר שאין בו שום קול רק מה שתוקעין, וזהו כשופר הרם קולך, ודפח\"ח. ועד\"ז בתפארת עוזיאל לר\"ה: שמעתי ממורי ורבי הגאון החסיד מו\"ה דוב בער ז\"ל נבג\"ם עה\"פ והיה כנגן המנגן ותהי עליו רוח אלקים דהנה זה נראה לעיני כל אדם המנגן יפה בעת שמנגן יש לו כמה פניות ומכוון הכל להתפאר בקולו, לא כן הכלי שמנגן בו הוא דומם ובודאי אין יכולת בהכלי לעשות שום פניה, וזה היה כנגן המנגן ר\"ל אם יהיה המנגן הוא האדם, כנגן, ר\"ל כהכלי שמנגן בו, שאף לו לא תהיה שום פנייה כמו הכלי שאין לו שום פנייה אז ותהי עליו רוח אלקים. [ולהעיר שכן מבוארים פסוקים אלו בס' בינה לעתים, עת משפט דרוש ה' (ז, ז).]\n<i>שעובד בעצמו כביכול את עצמו</i> – ראה סי' רצ."]]],[400080450,"שפז-ב\n\n<b>כי</b> קביר למשה <span data-k=\"sm\">[במה טביל]</span>. <span data-k=\"sm\">[פי']</span> משה יקרא השכל. ולפעמים אין יכול האדם לעבוד את השי\"ת מחמת שנסתלק השכל. במאי טביל, כלומר מה תקנה יש לו, אמר ליה בנורא, פירוש בהתלהבות, שנופלת על האדם התלהבות גדולה שאפילו אדם פשוט יכול לבוא למדריגה זו על ידי זה[ftnref_1_ג]. כי המדריגה הזאת אין מחמת עובדא <span data-k=\"sm\">[לכן]</span> יכולים לבוא לה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ב, א. לקו\"א לג, ב.</b>\n<i>כי קביר למשה במאי טביל כו' בנורא</i> – סנהדרין לט, א.\n----- שולי הגליון -----\n[ftn_1_ג]) <i>ע\"פ המקבילות יש כאן שילוב ב' נוסחאות. בלקו\"א: </i>למדריגה זו. <i>ובאוה\"א:</i> למדריגה גדולה על ידי זה.\n----- הערות וציונים -----\n<i>משה יקרא השכל</i> – ראה סוף סי' שצג. וראה בהערות לסי' קלח."]]],[400080451,"שפז-ג\n\n<b>וצריך</b>[ftnref_1_ד] לאחוז את עצמו לאי\"ן, שכשהוא חושב את עצמו ליש, אז אין הקב\"ה מתלבש בו (יתברך), שהוא יתברך אין סוף, ואין כלי יכולה לסובלו. אבל כשהוא חושב שהוא אי\"ן ושוכח בעצמו, שאינו מבקש על עצמו כלום רק על השכינה, שאם הוא מבקש על עצמו הוא דבוק בגשמיות ובזמניות, אבל כששוכח בעצמו ואינו דבוק כלל בתאוות עוה\"ז אז הוא יכול לבוא למעלה מזמניות, דהיינו לעולם המחשבה, ששם הכל שוה, חיים ומות ים ויבשה. וזהו פי' בזוהר מה תצעק אלי דבר אל בני וגו', אלי דייקא, דהא האי מילתא בעתיקא תליא. והיו צריכים להפקיר את עצמן ולשכוח בצרתם כדי שיבואו לעולם המחשבה, ושם הכל שוה, והיו יכולים לילך אפילו בים. אבל אם אדם דבוק בתאוות <span data-k=\"sm\">[נ\"א: בטבעיות]</span> עוה\"ז אינו יכול להפשיט עצמו מהגשמיות. שכשהוא מתאוה לאיזה דבר נמצא הוא בהתחלקות טוב ורע, וזהו בז' ימי הבנין, והאיך יבוא למעלה מזמניות ששם הכל שוה, אחדות פשוטה, דהיינו בינה. וזהו שלהבת י\"ה, חכמה ובינה. ואז כשיש זיווג אהבה ויראה, נולד תנועה באיברים, בידים, שאהבה ויראה העליונים, דהיינו חכמה ובינה, מתגלים בידים שהם חסד וגבורה, ולפעמים נולד השתנות בקול.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קנא (קנט) </b><i>[עד אחדות פשוטה]. </i><b>אוה\"א ב, א. לקו\"א לג, ב.</b>\n<i>שכשהוא חושב א\"ע ליש אז אין כו'</i> – ראה סוטה ה, א.<i> פי' בזוהר מה כו'</i> – זח\"ב נב, ב.<i> מה תצעק אלי גו'</i> – בשלח יד, טו.<i> שלהבת י\"ה</i> – שה\"ש ח, ו.<i> י\"ה חכמה ובינה</i> – זח\"ג קנג, ב. תקו\"ז ג, א. שם ז רע\"א. ת\"ד יט, א.<i> אהבה ויראה העליונים דהיינו חכמה ובינה</i> – תקו\"ז ת\"י כה, ב.<i> בידים שהם חסד וגבורה</i> – זח\"א כג רע\"א. שם כו רע\"ב. תקו\"ז יז, א.\n----- שולי הגליון -----\n[ftn_1_ד]) <i>במדל\"י בנ\"א:</i> צריך האדם לחשוב את עצמו כאין, וישכח את עצמו מכל וכל, ויבקש הכל בכל תפילתו על השכינה. ואזי יכול לבא למעלה מזמן, דהיינו לעולם המחשבה, ששם הכל שוה חיים ומות ים ויבשה. וזהו מ\"ש בזוהר אלי דייקא דא בעתיקא תליא. שהיו צריכין להפקיר את עצמן ולשכח בצרתן כדי שיבואו לעולם המחשבה, וששם הכל שוה. משא\"כ כשהוא דבוק בגשמיות עולם הזה הוא דבוק בהתחלקות טוב ורע, דהיינו ז' ימי הבנין, ואיך יבא למעלה מזמניות ששם אחדות גמור. וכן כשחושב את עצמו ומבקש צרכיו, אז אין הקב\"ה יכול להתלבש בו, שהוא ית' אין סוף ואין כלי יכול לסובלו, משא\"כ כשחושב את עצמו לאין כנ\"ל.\n----- הערות וציונים -----\n<i>שכשהוא חושב את עצמו ליש כו'</i> – ראה סי' קמ ד\"ה והנה אמרו בזוהר (ואילך), ובהערות שם. וראה כש\"ט סי' תז-ב.\n<i>שאינו מבקש . . רק על השכינה</i> – ראה סי' נו ובהערות שם.\n<i>אם הוא מבקש על עצמו הוא דבוק בגשמיות ובזמניות</i> – ראה סי' נג ד\"ה וירכב, וריש סי' שצא ובהערות שם.\n<i>למעלה מזמניות דהיינו לעולם המחשבה</i> – ראה סי' רמה ד\"ה או יאמר, וסי' תמד. להעיר מסי' קה סד\"ה בפסוק, ומדל\"י סי' רכה (רלז).\n<i>וזהו פי' בזוהר מה כו'</i> – ראה סי' צ ד\"ה וזהו מה, ובהערות שם ד\"ה ששם.\n<i>אחדות פשוטה דהיינו בינה</i> – ראה סי' שנט. ולהעיר מכש\"ט סוף סי' שצ."]]],[400080452,"שפח\n\n<b>אין</b> אשה אלא ליופי. פירוש, דהקב\"ה ברא את הגשמי <span data-k=\"sm\">[נ\"א: עולם</span>] הזה וברא בתוכו את האדם בצלמו, כדי שישרה בו. כמשל בית השרים בבית הוועד שרושמים מבחוץ שזה ביתו של פלוני. ולמה עשה זאת <span data-k=\"sm\">[נ\"א: כן]</span>, הלוא כל המלאכים הם שליש עולם ואורות מצוחצחות, פי' עולמות יפים מאוד, (איך) [אך] שיפה (את) הדבר הזה מאד <span data-k=\"sm\">[נ\"א: ואורות יפות ומצוחצחות עד מאד, עם כל זה יש לו יותר תענוג מן האדם]</span>. כמשל הציפור המדברת לפני המלך, אף על פי שמדבר דברי שטות, יש למלך יותר תענוג מכל הדברים שמדברים דברי שכל <span data-k=\"sm\">[נ\"א: מכל מליצות השרים המשוררים]</span>. כך כשהחומר העכור <span data-k=\"sm\">[נ\"א: האדם החומרי]</span> כשמעלה במחשבתו את כל העולמות <span data-k=\"sm\">[נ\"א: במחשבתו עולמות עליונים]</span>, נופל עליהם חיל ורעדה מחמת יראתם של השי\"ת, ורואים <span data-k=\"sm\">[נ\"א: מיראתו של הקב\"ה, ורואה]</span> אור גדול מצוחצח. וכל זה נתגלה מחמת האדם שבעולם השפל, ונולד התפארות גדול מאוד <span data-k=\"sm\">[בהקב\"ה]</span>. וזהו אין אשה, פירוש הגו\"ף נקרא אש\"ה, שמחמת הגוף נולד יופי גדול <span data-k=\"sm\">[נ\"א: אין אשה, דהיינו החומר, אלא ליופי, ר\"ל שהיופי היינו התפארת העליון נתגדל מזה מאד]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' קנב (קס). אוה\"א ב, ב.</b>\n<i>אין אשה אלא ליופי</i> – תענית לא, א.<i> המלאכים הם שליש עולם</i> – בר\"ר סח, יב.<i> הגו\"ף נקרא אש\"ה</i> – זח\"א קפא, ב.\n----- הערות וציונים -----\nראה לקו\"י יד, ב (סי' קס) [ובאוה\"א עו סע\"ב]: עיקר הסוד מה שהקב\"ה שולח נשמה בגוף השפל הזה כי אדרבא מזה יש להקב\"ה נחת ותענוג גדול מאוד, כי אף שהנשמה בכלי מלוכלך מאוד, כי אין דבר גרוע ויותר גשמי מעפר ואעפ\"כ נותנת תמיד שבח והודיה לבוראה וזה חידוש גדול, לכן יש להקב\"ה מאלו השבחים יותר תענוג מכל העבודות והשבחים של המלאכים כי עליהם אין חידוש כי אין להם גוף עכור. וז\"ש בגמרא אין האשה אלא לנוי, ר\"ל הגוף נקרא אשה, וזהו אין האשה, כלומר לא ברא הקב\"ה את הגוף העכור הזה אלא לנוי, להנות ממנו שיהא לו תענוג ממנו כנ\"ל. וכן באוה\"מ ר\"פ חיי שרה עיי\"ש ובהערה הסמוכה.\n<i>דהקב\"ה ברא את הגשמי כו'</i> – עיין לעיל סי' שי ובהערות שם.\n<i>ברא את הגשמי כו' כדי שישרה בו</i> – להעיר מתנחומא נשא טז (בשעה שברא הקב\"ה את העולם נתאוה שיהא לו דירה בתחתונים כו').\n<i>הגוף נקרא אש\"ה</i> – ראה מו\"נ ח\"א פי\"ז. ושם ח\"ג פ\"ח. וראה תקו\"ז תכ\"א סא רע\"א."]]],[400080453,"שפט\n\n<b>יהי</b> רצון שיהא מורא שמים עליכם וכו', אמרו לו עד כאן ותו לא, אמר להו הלואי, תדעו כשאדם עובר עבירה אומר שלא יראני אדם. פירוש כי יש ב' מיני יראה. א' שמתירא בפני המלך שלא יעניש אותו. והב' שיש לו בושה לעשות דבר בפני המלך. והם סברו שבירך אותם כמורא בשר ודם מחמת יראת עונש, לכך אמרו ותו לא. אמר להם הלואי <span data-k=\"sm\">[וכו']</span> שלא יראני אדם, שזהו מחמת בושה.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ג, א. לקו\"א לד, א.</b>\n<i>יהי רצון שיהא כו'</i> – ברכות כח, ב.\n----- הערות וציונים -----\nלהעיר מתורת הבעש\"ט במאור עינים פ' בראשית ד\"ה אמנם באמת (וכן שם פ' וירא ד\"ה הבעש\"ט, ופ' פנחס ד\"ה וזהו ואיש) בענין זה."]]],[400080454,"שצ\n\n<b>נגד</b> שמיה אבד שמיה. שהקב\"ה קודם שברא את העולם היה כביכול לא ניכרת מלכותו, כי אין מלך בלא עם. כי המדריגה עליונה לא ניכרת עד שיש מדריגה קטנה. ושכלו וגדלו ועוצם יכולתו אינם יכולים להשיג כל העולמות, (רק) [לפיכך] עשה צמצום אחר צמצום עד שיכולים לסובלו יתברך, ועל[ftnref_1_ה] ידי זה נקרא אדון בשביל שיש לו עם, וכל זה שיש לו עם הוא מכח שצמצם את עצמו כביכול. כמשל האב שצמצם את דעתו <span data-k=\"sm\">[ושכלו]</span> בשביל בנו, ועושה מעשה נערות בשביל <span data-k=\"sm\">[בנו שיהיה לו תענוג. ולמה עושה מעשה נערות, בשביל]</span> שאין הבן משיג את שכלו הגדול. כך הוא יתברך מצמצם את עצמו בשביל שיהא לנו תענוג. לכן אין אנו רשאים (לומר) [לקרותו] רק בשם אדנ\"י, לכן אין אנו משיגים רק השכל <span data-k=\"sm\">[נ\"א: מדרגה קטנה]</span> שבעולמות שבצמצום, והוא מכח שרצה להיות אדו\"ן, אבל <span data-k=\"sm\">[שם]</span> הוי\"ה ב\"ה <span data-k=\"sm\">[שהוא]</span> שם העצם יתברך אין אנו משיגים. וכן כל העולמות אינם יכולים להשיג רק בהתפשטות הגשמיות והתגברות כח הרוחני. כמו כהן גדול ביוה\"כ שאז הוא שבת שבתון, כי קדושת שבת משפיע בכל העולמות וששה ימי המעשה, ויוה\"כ קדושתו למעלה שאין בו אכילה ושתיה, (ויכול) [ואז יכול] להשיג מקצת השכל שלמעלה מהעולמות, לפיכך הזכיר את השם המפורש שהוא שם העצם יתברך. וזהו נגד שמיה, שרצה להיות נגיד ואדון, אבד שמיה, שהוצרך לצמצם <span data-k=\"sm\">[נ\"א: להעלים]</span> שם העצם ית', על דרך כי יד על כס י\"ה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' רב (ריב). אוה\"א ד, א. לקו\"א לו, א.</b>\n<i>נגד שמיה אבד שמיה</i> – אבות פ\"א מי\"ג.<i> אין מלך בלא עם</i> – רבנו בחיי וישב לח, ל. ראה פדר\"א פ\"ג. זח\"ג רעא, ב. תקו\"ז תכ\"א ס רע\"ב.<i> הוי\"ה ב\"ה שם העצם ית'</i> – ראה מו\"נ ח\"א פס\"א. של\"ה תול\"א בית ה'.<i> שאז הוא שבת שבתון</i> – אחרי טז, לא. אמר כג, לב.<i> קדושת שבת משפיע בכל העולמות</i> – ראה זח\"ב פח, א. זח\"ג צד, ב. שם צה, א.<i> וששה ימי המעשה</i> – זח\"א עה, ב. זח\"ב סג, ב. שם פח, א.<i> ויוה\"כ . . שאין בו אכילה ושתיה</i> – יומא עג, ב. ראה זח\"א רכ, ב. זח\"ב קב, ב.<i> הזכיר את השם המפורש כו'</i> – יומא סו, א.<i> כי יד על כס י\"ה</i> – בשלח יז, טז. ראה תנחומא תצא יא.\n----- שולי הגליון -----\n[ftn_1_ה]) ועל ידי זה . . כביכול<i> ליכא במדל\"י</i>.\n----- הערות וציונים -----\n<i>שהקב\"ה קודם שברא כו'</i> – ראה סוף סי' קמג ד\"ה והנה נודע. סי' תלה סד\"ה והנה חכמה. וראה אוה\"מ רות ד\"ה ותאמר אליהן: ואני שמעתי מהמגיד זללה\"ה פ\"ה נגד שמא אבד שמיה וביאר נגד משמעו לשון המשכה, והכוונה כל מה שהקב\"ה נגד והמשיך שמותיו כינויו הקדושים למרחוק בכדי שבאמצעותם יכולין רעיון לבות בני אדם לתופסו ולקרותו בשם מצד פעולותיו, בין כך אבד שמיה העצם, כי כל מה שנתפשט יותר למרחוק להתלבש בשמות וכינוים ובמעט הכרתם של התחתונים שכוח מלוח לבם שם הגדול והקדוש שם העצם ברוך הוא עכ\"ל.\n<i>כמשל האב שצמצם כו'</i> – ראה סי' א, וסי' רמח ד\"ה והנה נאמר.\n<i>לכן אין אנו רשאים לקרותו רק בשם אד' כו'</i> – ראה סי' קפב ובהערות שם, וריש סי' שסה."]]],[400080455,"שצא\n\n<b>אליהו</b> חי לעולם, אעפ\"י שהוא מורכב מד' יסודות, והם בזמניות. אך השורש של הד' <span data-k=\"sm\">[יסודות]</span> הם אחדות, וכשממשיך האחדות בהם הם מתגדלים ובאים למעלה מזמניות ובאים לאחדות פשוט, ויכול לחיות לעולם.\n<b>וזהו</b> פירוש יפה שעה אחת של קורת רוח בעולם הבא מכל חיי העולם הזה. שהאדם כשרוצה לילך מהלך ת\"ק שנה צריך לילך הרבה, ובחלום יכול לילך ברגע אחד מפני שהוא למעלה מזמניות. והתענוג שיש לו ברגע אחד שם, שהוא למעלה מהזמניות, אין יכול כאן עולם הזה לסבול כי הוא בזמן, והיה הזמן בטל ממציאות. כי הזמן הוא בריאה, ואינו יכול לקבל מה שלמעלה מן הזמן.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י מ, ג (סי' רצ). אוה\"א ו, ב. לקו\"א לח, ב.</b>\n<i>אליהו חי לעולם</i> – ויק\"ר כז, ד.<i> מד' יסודות והם בזמניות</i> – ראה רמב\"ם הלכות יסוה\"ת פ\"ד. מו\"נ ח\"א פע\"ב.<i> השורש של הארבעה יסודות כו'</i> – ראה ע\"ח שמ\"ב פ\"א.<i> יפה שעה אחת כו'</i> – אבות פ\"ד מי\"ז.<i> הזמן הוא בריאה</i> – אמו\"ד לרס\"ג מ\"ב פי\"א. מו\"נ ח\"ב פי\"ג. שם ריש פ\"ל.\n----- הערות וציונים -----\n<i>מד' יסודות והם בזמניות כו'</i> – ראה סי' שפז-ג ובהערות שם.\n<i>וזהו פירוש יפה שעה כו'</i> – ראה סי' תמד. וכן בסי' רמה סד\"ה או יאמר.\n<i>כי הזמן הוא בריאה</i> – ראה סידור עם דא\"ח לאדה\"ז שער הק\"ש, בריש ד\"ה להבין פ' ראשונה (עה סע\"ד): ידוע בשם הה\"מ ז\"ל משום דהזמן עצמו הוא בא ונמשך בבחי' בריאה יש מאין והוא בחי' נברא מחודש כו' כשאר כל הנבראים, וכן בבחי' האצילות הזמן דשם הוא בבחי' נאצל מאין ליש כו' והיינו שנמשך ובא מלמעלה מהזמן דאין שם בחי' זמן כלל. ועיין מה שהאריך בזה כ\"ק אדמו\"ר זי\"ע באגרות קודש ח\"א ע' רצג ואילך."]]],[400080456,"שצב\n\n<b>חומר</b> בקודש מבתרומה. התורה שבע\"פ מוכיחה את האדם כאם את בניה, ואומרת כמה אוהב אתכם הקב\"ה. כמשל מי שיש לו בן אהוב, אף על פי שרחוק ממנו מצייר מחשבתו בתמונותיו <span data-k=\"sm\">[נ\"א: מצייר תמונתו במחשבתו]</span>. אף על פי שהמחשבה הוא רוחניות נתהוה (בתמונת) [בה תמונת] גוף. כך הוא יתברך, אפילו הגופים (שלא) [שלנו] הם תמיד במחשבתו. וזהו חומר בקודש, האיך בא החומריות בו ית', מבתרומה, מכח המדריגה התחתונה. וכמה יש (לו) [לי] לרחם עליו ית', שכל מה שאני מגשם את עצמי מביא כביכול כך למעלה, (וכשאתה) [וכשאדם] מוליך את המלך ומוליך אותו למקום מלוכלך אזי הוא מורד במלכות חס ושלום.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ו, ב. לקו\"א לט, א.</b>\n<i>חומר בקודש מבתרומה</i> – חגיגה כ, ב.\n----- הערות וציונים -----\nראה לקמן סי' תב.\n<i>כמשל מי שיש לו בן כו'</i> – ראה סי' סד ד\"ה והנה כשהאב, ובהערות שם."]]],[400080457,"שצג\n\n<b>תפילין</b> דמארי עלמא מה כתיב בהו ומי כעמך ישראל וגו'. דאיתא בכתבי האר\"י זלה\"ה תפילין נקראים מוחי\"ן. פירוש, מוחי\"ן נקרא תענוג והתלהבות ממה שאנו דבוקים לו ית'. וראו כל עמי הארץ כי שם ה' נקרא עליך, כביכול אתה נקרא בשם הוי\"ה ית', שאתה נעשה אחדות עמו ית'. והתענוג הזה נקרא תפילין שלנו. והתענוג שלו ית', שנתענג מחמת שאנו דבוקים לו ית', נקרא תפילין שלו. <span data-k=\"sm\">[וזהו]</span> ומי כעמך ישראל גוי אחד בארץ, כשהם דבוקים לו ית' נעשים <span data-k=\"sm\">[נ\"א: נעשה]</span> אחדות, שבאים למעלה ממספר, והמספר הוא בידם, כמה דאיתא במדרש אימתי ר\"ה, אמר הקב\"ה אני ואתם נלכו לבית דין של מטה. כשהם עושים רצונו של מקום הזמן הוא בידם לעשות כמו שרוצים, שהם למעלה מהזמן, והוא ית' דבוק בנו. רק המניעה הוא מכוחינו <span data-k=\"sm\">[נ\"א: מצדנו]</span>, על דרך שובו אלי ואשובה אליכם. שהוא ית' שורה בהמחשבה, וכשאדם חושב בדברי שטות ח\"ו דוחה אותו ית'. <span data-k=\"sm\">[וזהו]</span> ולא יכול משה לבוא אל אוהל מועד, השכל אינו יכול לשרות בהאדם, כי שכן עליו הענן, כי החשכות שורה בו.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י מ, ג (סי' רצא). אוה\"א ז, א. לקו\"א לט, א.</b>\n<i>תפלין דמארי עלמא כו'</i> – ברכות ו, א.<i> מי כעמך ישראל גו'</i> – דה\"א יז, כא.<i> דאיתא בכתבי האר\"י זלה\"ה כו'</i> – פע\"ח שער התפילין פ\"א. ראה זח\"ג קמ, א.<i> וראו כל עמי הארץ גו'</i> – כי תבוא כח, ב.<i> דאיתא במדרש אימתי כו'</i> – דב\"ר ב, יד.<i> שובו אלי גו'</i> – מלאכי ג, ז.<i> ולא יכול גו' כי שכן עליו גו'</i> – פקודי מ, לה.\n----- הערות וציונים -----\n<i>והתענוג שלו ית' כו'</i> – ראה סי' תלז. ולהעיר מסי' קכט.\n<i>הזמן הוא בידם כו'</i> – ראה סי' פו ד\"ה והנה זהו.\n<i>שהוא ית' שורה כו'</i> – ראה סי' שצט."]]],[400080458,"שצד\n\n<b>כל</b> מקום שאתה מוצא גדולתו <span data-k=\"sm\">[של הקב\"ה]</span> אתה מוצא ענותנותו. ע\"ד הן שמים לא זכו בעיניו. שמי\"ם נקרא האדם החסיד, ר\"ל שם מים, והשכל נקרא מי\"ם, לא זכו בעיניו, אין מחזיק את עצמו ליש בעיניו, שהם תמיד לפני הקב\"ה ורואים בגדולתו ית' לפיכך אין מחזיקים את עצמן לכלום[ftnref_1_ו]. כמשל מי שיש לו ב' אלפים מחזיק עצמו לעשיר לפני מי שיש לו (ד' אלפים) [דינר אחד], אבל לפני <span data-k=\"sm\">[נ\"א: נגד]</span> המלך אינו מחשיב עצמו לכלום. ומחמת זה יכול לזכות לכמה מדריגות. כי החיות יורד בעולמות מטי ולא מטי, כי אין הגוף יכול לסבול החיות. ולכך קודם המיתה כשרואה את השכינה ונתרבה חיותו, מיד הוא מת, כי אינו יכול לסבול <span data-k=\"sm\">[רוב החיות]</span>. אבל מי שהוא עניו אזי הוא למעלה מן המדות.\n<b>וזהו</b> ידע מה בחשוכא <span data-k=\"sm\">[ונהורא עמיה שרא. ידע מה בחשוכא]</span>, הקדוש ברוך הוא מקשר את עצמו עם מי שמחזיק <span data-k=\"sm\">[את עצמו]</span> למ\"ה, בחשוכא, אפילו בין הרשעים. ונהורא עמיה שרא, הוא אור זרוע לצדיק, האור שלמעלה מן המדות עמו שריא, כי מחזיק עצמו לאי\"ן ואינו כלל מהמדות <span data-k=\"sm\">[נ\"א: במדה]</span>, לפיכך הוא יתברך שורה בו, שוכן את דכא ושפלי שפלים <span data-k=\"sm\">[נ\"א: ושפל רוח]</span>. וגם זה הוא מחמת ענותנותיה <span data-k=\"sm\">[ית']</span>, שהרי הוא גדול <span data-k=\"sm\">[גבור]</span> ונורא, והאדם הוא שפל וחוטא. אך כי זהו יותר ענוה, שאף על פי כן שורה עם האדם. ולכן נתן את התורה על הר סיני, קטן שבהרים, פי' בשביל מדריגה קטנה שבמדות. שאם נתן בשביל מדריגה גדולה, לא היתה הקטנה יכולה לקבלה. וכל כך למה, בשביל שלא חשבה הקטנה את עצמה שבשבילה יתנו התורה, וזהו עדיף מהגדולים שחשבו שבשבילם יתנו התורה. ומשה רבינו ע\"ה היה פרוש מן האשה, פירוש מן החומריות, שלא היה משגיח על המדריגות התחתונות ושלמטה ממנו, רק להקב\"ה, והיה מחשב עצמו לאי\"ן, כאור הנר לפני האבוקה. שמי שאינו רואה אלא אור הנר סובר שזה אור גדול, אבל כשרואה אור השמש אומר <span data-k=\"sm\">[נ\"א: מבין]</span> שאין אור זה כלום כנגד אור השמש.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א ח, א. לקו\"א מ, ב.</b>\n<i>כל מקום שאתה מוצא כו'</i> – מגילה לא, א.<i> הן גו' ושמים לא זכו בעיניו</i> – איוב טו, טו.<i> שמים . . שם מים</i> – חגיגה יב, א.<i> והשכל נקרא מי\"ם</i> – ראה זח\"ב קעה, ב.<i> מטי ולא מטי</i> – זח\"א טז, ב.<i> קודם המיתה כשרואה כו'</i> – זח\"א (מדה\"נ) צח, א. זח\"ג נג רע\"א. שם פח סע\"א. קכו סע\"ב. ראה תנחומא חקת טז.<i> ידע גו' ונהורא גו'</i> – דניאל ב, כב.<i> אור זרוע גו'</i> – תהלים צז, יא.<i> שוכן את דכא כו'</i> – ע\"פ ישעיה נז, טו.<i> גדול גבור ונורא</i> – ע\"פ עקב י, יז.<i> נתן את התורה כו' קטן שבהרים</i> – מדרש תהלים סח, ט.<i> ומשה רבינו ע\"ה היה פרוש כו'</i> – שבת פז, א.<i> כאור הנר בפני האבוקה</i> – פסחים ח, ב.\n----- שולי הגליון -----\n[ftn_1_ו]) <i>בלקו\"א:</i> לא זכו, פי' אין מחזיקים בעצמם לזכים. כמשל <i>(כבפנים)</i>.\n----- הערות וציונים -----\n<i>ורואים בגדולתו ית' לפיכך כו' כמשל כו'</i> – ראה סי' תלא.\n<i>כי החיות יורד בעולמות מטי ולא מטי כו'</i> – ראה סי' רנה ד\"ה הואיל (ואילך) ובהערות שם.\n<i>וזהו ידע מה בחשוכא כו'</i> – ראה סי' שעג.\n<i>ומשה רבינו ע\"ה היה פרוש כו'</i> – ראה סי' כג. סי' עו ד\"ה והנה משה. וסי' קלו."]]],[400080459,"שצה\n\n<b>עסקתי</b> בתורה בכל עשר אצבעותי ולא נהנתי אפילו באצבע קטנה שלי. <span data-k=\"sm\">[פירוש]</span> עשר אצבעות נקראים הי' שכליים נבדלים <span data-k=\"sm\">[נ\"א: י' מדות, שהם כמו אצבעות ש]</span>כמו עם אצבע מטלטלין מה שצריך, כך עם המדות נעשים כל דבר כידוע. וזהו עסקתי בתורה בכל י' אצבעותי, הם חכמה ובינה וכו' אהבה ויראה וכו' <span data-k=\"sm\">[נ\"א: שהם י' ספירות, בחכמה ובינה וכן כולם]</span>, עם הכל עבדתי את השם יתברך. ולא נהנתי וכו', על דרך <span data-k=\"sm\">[שאמרו רז\"ל]</span> אבר קטן יש באדם מרעיבו שבע משביעו רעב. פירוש, התקשרות בו יתברך <span data-k=\"sm\">[שנקרא אות ברית]</span> מרעיבו <span data-k=\"sm\">[שבע, ר\"ל]</span> כשאומר בלבו שאינו מקושר <span data-k=\"sm\">[כלל]</span>, אזי הוא שבע, פי' מקושר, <span data-k=\"sm\">[כי הוא משתוקק תמיד להתקשר בו יותר]</span>. משביעו, דהיינו שאומר <span data-k=\"sm\">[בלבו]</span> שהוא מקושר, הוא רעב. והברית נקרא אצבע קטנה מלשון לא כל האצבעות שוים. וזהו פירוש אפילו באצבע קטנה, פי' <span data-k=\"sm\">[אפילו]</span> בשעת הזיווג.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' פג (צד). אוה\"א ח, ב.</b>\n<i>יגעתי בעשר אצבעותי בתורה כו'</i> – כתובות קד, א.<i> עשר אצבעות נקראים כו'</i> – ראה ס\"י פ\"א מ\"ג. ספר הבהיר סי' קכד.<i> אבר קטן כו'</i> – סוכה נב, ב.<i> לא כל האצבעות כו'</i> – פסחים קיב, ב.\n----- הערות וציונים -----\n<i>כשאומר בלבו כו' משתוקק כו' משביעו כו'</i> – ראה סי' רמב. ולהעיר מכש\"ט סי' כט ובהערות שם."]]],[400080460,"שצו\n\n<b>אלו</b> ואלו דברי אלקים חיים, פי' בין האוסרים ובין המתירים. כי בדעת חדרים ימלאו, כל המדות הם באים מכח הדעת. <span data-k=\"sm\">[ר\"ל]</span>, מכח שאם נודע שזה אהובי אני אוהב אותו, ומכח שאני יודע שיש גדול לפני <span data-k=\"sm\">[נ\"א: ממני]</span> אני בוש ונכנע ממנו <span data-k=\"sm\">[ומכבדו, וכן כיוצא בזה]</span>. וכל אחד המשיך ממדת הדעת שיהיו הצירופים של הדיבורים כך, וזה המשיך כך. שזה המשיך מהדעת מדת אהבה, שיהיה הביצה מותרת <span data-k=\"sm\">[שיהא זה במעשה כך]</span>, וזה המשיך מהדעת מדת יראה והביצה אסורה. וכשאחד היה רוצה לשנות הלכה, כמו רבי יהושע שאמר אין משגיחין בבת קול, החזיר את הדין הזה למדת דעת, ומשם המשיך הדין למדה אחרת.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' פח (צח). אוה\"א י, א. כתבי קודש י, ב </b><i>(ד\"ה הנה בדעת)</i>.\n<i>אלו ואלו דא\"ח</i> – עירובין יג, ב.<i> ובדעת חדרים ימלאו</i> – משלי כד, ד.<i> רבי יהושע שאמר כו'</i> – ברכות נב, א. בבא מציעא נט, ב.\n----- הערות וציונים -----\nראה כש\"ט סי' נא-א: ביאר מורי זלה\"ה . . אע\"פ שאלו אוסרין ואלו מתירין, היינו בו' קצוות זעיר אנפין, אבל למעלה, בבינה שנק' אלקים חיים, הכל אחדות אחד, וז\"ש אלו ואלו דא\"ח ודפח\"ח. ועיי\"ש בהערות.\n<i>כל המדות הם באים מכח הדעת</i> – עיין מדל\"י סי' ו (ז). ולקמן סי' תצט. רג\"כ ריש סי' תמח. ולהעיר מלקו\"י סי' רלא. ראה עוד תניא, אגה\"ק סי' טו, ולקמן סי' תד.\n<i>וכשאחד היה רוצה לשנות הלכה כו'</i> – ראה סי' רנח ד\"ה אבל, ובהערות שם."]]],[400080461,"שצז\n\n<b>או</b> יאמר אלו ואלו דברי אלקים חיים, ויובן על דרך משל. מלך שלמה כשנפל ממלכותו, כי היה מלך והדיוט, ואם היו מכירים אותו אומרים זה לזה נעשה לו מלבושים נאים של משי, וזה אומר אין נאה לו כך אלא כזה <span data-k=\"sm\">[יותר]</span> נאים. והמלך נהנה אפילו מזה האיש שאינו אומר כל כך נאים, רק באים בתוכו גדולתו ותפארתו, מחמת שחולקים על כבודו, זה אומר כך כבוד נעשה לו וזה אומר כך <span data-k=\"sm\">[כבודו]</span>, ויש לו (כבוד) [תענוג] מחמת החלוקה.\n<b>כך</b> התורה שבעל פה, הפלפול, הוא קישוטי כלה. שיש להקדוש ברוך הוא תענוג אפילו מזה שאומר שלא כהלכה, מחמת שחולק על כבודו ית', זה אומר אסור הוא כבוד שלו וזה אומר מותר הוא כבוד שלו יתברך[ftnref_1_ז].",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א יד, א. מדל\"י ססי' פח (צח), וכתבי קודש לא, ב (בקיצור).</b>\n<i>אלו ואלו דא\"ח</i> – עירובין יג, ב.<i> שלמה כו' מלך והדיוט</i> – גיטין סח, ב.<i> התושבע\"פ כו' קישוטי כלה</i> – זו\"ח שה\"ש סג סע\"ד ואילך.\n----- שולי הגליון -----\n[ftn_1_ז]) <i>במדל\"י ובכתבי קודש בקיצור, בלי המשל:</i> אלו ואלו דברי אלהים חיים. פירוש שתורה שבעל פה הם קישוטי כלה, וזה אומר שכך צריך להיות הקישוט, וזה אומר שזה אינו נאה וכך נאה יותר. ויש למלך תענוג שהם חולקין בקישוטין שכל אחד רוצה לפאר המלך.\n----- הערות וציונים -----\n<i>על דרך משל כו'</i> – כמשל זה (וקרוב יותר לנוסחא במדל\"י ובכתבי קודש) הובא שם בזו\"ח שה\"ש סד, א. וראה מזה בס' דמ\"א בסוף הליקוטים ד\"ה מה שכותבין."]]],[400080462,"שצח\n\n<b>אליהו</b> לא נענה כי אם בתפילת המנחה. <span data-k=\"sm\">[וקשה]</span>, והלוא <span data-k=\"sm\">[המנחה]</span> עת דין הוא. אך גבי מנחת עני כתיב בנוצתה, אף על פי שהיא חיצונית <span data-k=\"sm\">[קרבנו]</span>, חביב <span data-k=\"sm\">[הוא]</span> אצלו ית', דעבירות <span data-k=\"sm\">[שלו]</span> נעשו לו כזכיות, אפילו מכח עבירה <span data-k=\"sm\">[נ\"א: אפילו מעבירה]</span> נעשה מצוה, כי מפני עניותו עשה העבירה. נמצא מכח שהוא בבחינת די\"ן <span data-k=\"sm\">[נ\"א מבחוץ]</span> אוהב אותו הקב\"ה <span data-k=\"sm\">[נ\"א: הקב\"ה מרחמו ואוהבו]</span>. ובמנחה שהיא עת דין, וכאשר האדם מדבק הדין בתפילתו ובכוונתו למעלה חביב אצלו ית' מאוד, כי הדין נעשה אהבה <span data-k=\"sm\">[נ\"א: וכוונתו למעלה להש\"י, הוא חשוב אצלו יותר, ומהדין נעשה אהבה]</span>. לפיכך נענה בתפיל\"ת המנחה, פירוש <span data-k=\"sm\">[תפילת לשון]</span> התדבקות <span data-k=\"sm\">[והתחברות]</span>, המנחה, שהביא הדין לחסד.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' עו (פז). אוה\"א יא, א.</b>\n<i>אליהו לא נענה אלא כו'</i> – ברכות ו, ב.<i> עת דין הוא</i> – זח\"א קלב, ב. זח\"ג פח סע\"ב.<i> בנוצתה</i> – ויקרא א, טז.<i> דעבירות נעשו לו כזכיות</i> – ראה יומא פו, א.<i> בתפלת . . התדבקות</i> – ת\"א ופרש\"י ויצא ל, ח. תקו\"ז תמ\"ז פד, ב.\n----- הערות וציונים -----\n<i>גבי מנחת עני כתיב בנוצתה כו'</i> – ראה פרש\"י ויקרא א, יז ע\"פ ויק\"ר ג, ה.\n<i>מכח שהוא בבחינת דין אוהב אותו כו'</i> – להעיר מסי' לב.\n<i>תפילת לשון התדבקות</i> – ראה סי' רנה ד\"ה ולזה רמזו, ובהערות שם."]]],[400080463,"שצט\n\n<b>הרחק</b> משכן רע. כי היום הוא בקל להשיג רוח הקודש יותר מזמן הבית. כמשל המלך שיצא מביתו לדרך, אזי אפילו בן כפר שאינו הגון לבוא לפני המלך בהיותו בבית מלכותו, ובדרך יכול לדבר עם המלך ולהביא אותו אצלו בפונדקי שלו. כך האדם, מיד כשחושב בדביקות הש\"י אזי שורה עמו. וכשיזדמן לו איזה תאוה אל יעשה אותו, או איזה מחשבה זרה אל יפנה אליה, שלא יפרוד ממנו ית', ויעשה הכל לשמו ית'. וזהו הרחק משכן רע, מכח השכן הגדול השורה אצלך הרחק הרע[ftnref_1_ח].",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' עז (פח). אוה\"א יא, א.</b>\n<i>הרחק משכן רע</i> – אבות פ\"א מ\"ז.\n----- שולי הגליון -----\n[ftn_1_ח]) <i>במדל\"י נ\"א:</i> דהנה היום בזמן הגלות הוא בקל להשיג רוח הקודש יותר מבזמן הבית. כמשל המלך כשהוא בבית מלכותו אי אפשר להתקרב אליו כל כך כמו שהוא בדרך, שאז יוכל להתקרב אליו כל מי שירצה. אפילו בן כפר שאינו הגון לבא לפני המלך בבית מלכותו, ובדרך בפונדק שלו יכול לבוא לפניו ולדבר עמו. כך היום בגלות, כשהאדם מחשב בדביקות הש\"י ב\"ה אזי מיד שורה עמו ושוכן אצלו. בכן ראוי לאדם שיתרחק עצמו מן התאות ומחשבות זרות בכדי שלא יפרד ממנו ית', רק יעשה כל מעשיו לשמו ית'. וזהו הרחק משכן, ר\"ל ממי ששוכן אצלך, הרחק הרע.\n----- הערות וציונים -----\n<i>כי היום הוא בקל להשיג רוח הקודש כמשל כו'</i> – ראה נועם אלימלך פ' וישב ד\"ה או יאמר (הב'. בביאור שם זבולון): ששמעתי משל מתוק מפי אדומ\"ו הרב המגיד דק\"ק ראויני זלה\"ה והוא שאנו רואים שכעת אשר אנחנו בגלות המר יש בני אדם שזוכים לרוח הקודש בקל יותר מבימי הנביאים שהיו צריכין השבעות והתבודדות רב כידוע כדי שישיגו הנבואה ורוח הקודש. ואמר משל נפלא ומתוק למשל המלך שהוא במקום כבודו בביתו בחצירו בפלטין שלו ויבא איזה אוהב המלך וירצה להזמינו לסעודתו לביתו אזי בוודאי יכעוס עליו המלך כי אין זה כבוד של מלך לצאת מפלטין שלו לבית אחרים גם אם יהיה הסעודה גדולה עד למאוד, ובלתי אפשרי שיזמין את המלך לביתו עד שיכין כל הכנות ויעמוד מליצים ופרקליטין גדולים שימצא חן בעיני המלך שיבא לסעודתו. אבל כשהמלך נוסע בדרך ורוצה ללון בדרך אזי כאשר ימצא מקום נקי באכסניא נקי אף אם בית המלון הוא בכפר אם הוא רק נקי אזי זה בית מלונו ללון שם. והנמשל מובן ממילא בזמן שבית המקדש קיים והיה שכינת כבודו בבית קדשי הקדשים אזי אם היה אדם רוצה לשאוב רוח הקודש או נביאות היה צריך עבודה גדולה כמו שמצינו בשמחת בית השואבה ששם היו שואבים רוח הקודש. אבל עתה בגלות המר הגם השכינה קדושה גלתה עמנו ובעוונותינו הרבים היא נע ונד בארץ ותשוקתה מאוד מצוא מקום דירה לשכון בה, ואם מצאה מנוח מקום נקי אדם שהוא רק נקי מעבירות וחטאים אזי שם היא דירתה ודפח\"ח.\nובעבודת ישראל ר\"פ מסעי: וכבר הקדים לנו אדומו\"ר ז\"ל הנ\"ל רמז בפסוק כל רודפיה השיגוה בין המצרים, דהיינו כל מי שרודף להמליך את הבורא יוכל להשיג יותר דוקא בימים אלו בין המצרים, למשל כי כשהשר יושב בביתו אז אימתו מוטלת אשר לא כל איש ואיש יכול לבא פנימה, מה שאין כן אם השר עובר בשוקים וברחובות חוץ לפלטרין שלו אז הוא קרוב לכל קוראיו ויאזין שועת כל הקוראים בשמו. וכן הנמשל לדעת כי בזמן הזה כי כצפור נודדת מקנה וגו', לכן הרשות נתונה לכל אדם להתקרב אל מלכו של עולם והוא עונה אליהם עכ\"ל. (וכן שם אבות פ\"ד מ\"ז.)\n<i>וזהו הרחק משכן רע כו'</i> – ראה אוה\"מ ר\"פ נח: המגיד ע\"ה זללה\"ה ביאר משנה הרחק משכן רע, ודקדק מהראוי לכתוב התרחק משכן רע שקאי על האדם שיתרחק א\"ע והרחק משמע פועל יוצא כאשר דקדק בזה במדרש שמואל, ופירש הרחק משכן, ממי ששוכן אצלך הוא הקב\"ה השוכן בתוך אבריו של אדם מראש ועד עקב, הרחק בשבילו רע ממלא קומתך לבלתי יאחז שום כיעור וטינוף ודבר מגונה ואזי תגרום שיסלק מעליך ח\"ו, למשל אדם שרוצה להזמין אצלו מלך ב\"ו בתוך ביתו כמה טרח ומשתדל בכל התאמצות לפנות ביתו ומחנתו הרחק מן המחנה כמלא עינו מן הכיעור והדומה ורוח רע, וכ\"ש וק\"ו בן ק\"ו מהראוי להיות שיטהר האדם את לבו מתאות הבהמיות ומ\"ז בכדי שישרה הקב\"ה בתוך לבו ורמ\"ח איבריו וכל פרטי מעשיו יעשה לשמו הגדול לבלתי יפרוד ויסתלק ממנו."]]],[400080464,"ת\n\n<b>[בן</b> <span data-k=\"sm\">בג בג אומר]</span> הפוך בה. פי' על דרך לעלוקה שתי בנות הב הב, פי' שרוצין לקבל השפע מן הקדושה, ואתה הפוך שיבוא ב\"ה[ftnref_1_ט]. פי' כי אין דיבור בלא מחשבה, כי הנה האדם חושב מקודם מה שרוצה לדבר[ftnref_2_י]. אך בלא דעת נפש לא טוב, ר\"ל כשלומד או מתפלל רק מהשפה ולחוץ, מצות אנשים מלומדה, אינו כלום. אך כשחושב לפני מי הוא מדבר, שצריך לירא מהדיבורים, ואינו יכול לירא מהדיבורים אם לא בנותנו אל לבו שהעולם הדיבור מדבר בו, שכל המדות כלולים בה אהבה ויראה והתפארות וניצוח והודיה וכו', וזהו הדיבור הוא מדריגת מלכות, השכינה, זה עולם הדיבור, וירא מזה הדיבור, שמעורר את השכינה. וזהו עושה דברו, שעושים מהדיבור מעשה, ובמעשה צ\"ל יצירה בריאה אצילות. אמנם כשמדבר בדעת, ובדעת חדרים ימלאו, הוא ית' שורה בהאותיות הוי\"ה ית'. וכשמביא את אלקו\"ת בהם, אזי יש בהם הכל.\n<b>וכשבאה</b> לו מחשבה זרה, אזי יביא אותה בבינה. והם צועקים הב הב, פי' כי זו ה' היא ה' מוצאות הפה, שהיתה השבירה (מהדיבור) [בדיבור], והם רוצים לקבל מהב'[ftnref_3_יא], מהבינה. אבל אתה תהפוך שיהיו ב\"ה, שיהיו ה' מוצאות מהשבירה למעלה מהבינה כביכול. כי הבינה נקרא עלמא דחירות, אפילו עבד הבא לשם נעשה בן חורין, ושם נתתקנו הה' מוצאות של השבירה. ויש לו יתברך תענוג יותר מאותן האותיות של השבירה מן האותיות של הקדושה שהם היו תמיד אצלו. והם היו גרים והרגישו באותן ניצוצות שהיו בקליפות, והתענוג אח\"כ כשבאו לקדושה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' עח (פט). אוה\"א יא, ב.</b>\n<i>הפוך בה</i> – אבות פ\"ה מכ\"א.<i> לעלוקה שתי בנות גו'</i> – משלי ל, טו.<i> בלא דעת נפש לא טוב</i> – משלי יט, ב.<i> מצות אנשים מלומדה</i> – ע\"פ ישעיה כט, יג.<i> שהעולם הדיבור הוא השכינה</i> – זח\"ג רכח, א. תקו\"ז ב סע\"ב.<i> שכל המדות כלולים בה כו'</i> – זח\"ג רל סע\"ב.<i> הדיבור הוא מדרגת מלכות כו'</i> – ראה זח\"א קמה סע\"א. זח\"ג רכח, א. תקו\"ז ב סע\"ב.<i> עושי דברו</i> – תהלים קג, כ.<i> ובדעת חדרים ימלאו</i> – משלי כד, ד.<i> הבינה נקרא עלמא דחירות</i> – זח\"ג (ר\"מ) קפ, ב. שם רמג, ב. זח\"ב קיד, א.<i> אפילו עבד כו'</i> – ראה זח\"א קכד, ב.<i> [וזהו סוד נשמת גרים</i> – ראה שער הגלגולים, הקדמות ב, לד, לו.<i> התנא הזה שהיה גר</i> – (בן בג בג שאמר הפוך בה) תוספות חגיגה ט, ב ד\"ה בר הי הי. דרך חיים למהר\"ל אבות פ\"ה מכ\"ב].\n----- שולי הגליון -----\n[ftn_1_ט]) ואתה הפוך שיבוא ב\"ה <i>ליכא במדל\"י</i>.\n[ftn_2_י]) <i>מכאן ואילך נוסח וסדר אחר במדל\"י:</i> והנה כשחושב קודם התפלה מה שידבר ולפני מי ידבר, בודאי יפול עליו יראה ובושה שיהיה ירא מהדיבורים עצמם. כשנותן אל לבו שהעולם הדיבור הוא השכינה כביכול מדברת בו, והיא כלולה מכל המדות אהבה ויראה והתפארת וכן כולם כידוע, ואיך לא יהיה יראה ובושה שמתעורר השכינה וכל המדות כביכול. וזהו עושי דברו, שעושים מדיבור מעשה, ובמעשה צריך ג\"כ להיות כלול אצילה בריאה יצירה. אך כשמדבר בדעת ובדעת חדרים ימלאו, כי הוא משרה בהאותיות אלהות ית', וכשמביא בהם אלהות אזי יש בהם הכל. וכשבא לו איזה מחשבה זרה שהם ה' מוצאות שנפלו מהשבירה, אזי יראה להעלותן בשרשן על ידי מחשבתו ובינתו כנ\"ל שהוא דבוק בהש\"י ב\"ה, ובבינה נמתקו, כי היא למעלה מהשבירה שהיא נקרא עלמא דחירו. משא\"כ אם אינו מעלה אותה מחשבה זרה כנ\"ל, אז הם צועקים ה\"ב, ר\"ל שה' מוצאות הנ\"ל רוצים לקבל שפע מהבינה כנ\"ל שנקראת ב'. וזהו הפוך ב\"ה, ר\"ל שיתעלו עד הבינה ויתתקנו מהשבירה. ויש להש\"י ב\"ה תענוג גדול מזה יותר מהאותיות שהם תמיד בקדושה. וזהו סוד נשמת גרים שעלו ג\"כ נצוצות מה שנפלו בקליפות, ולכך הרגיש התנא הזה, שהיה גר, בדבר הזה.\n[ftn_3_יא]) <i>נראה שצ\"ל</i> מה\"ב.\n----- הערות וציונים -----\n<i>אין דיבור בלא מחשבה כו'</i> – ראה סי' קמו, וסי' רג ד\"ה ויש לומר.\n<i>לירא מהדיבורים</i> – ראה צוה\"ר סי' פח ובהערות שם. מדל\"י סי' מה (מט), ושם סי' קמד (קנב). וראה לעיל סוף סי' רעז-א ולקמן סי' תו.\n<i>שכל המדות כלולים בה</i> – רג\"כ זח\"ב קנח, א. תקו\"ז תס\"ט קח סע\"א.\n<i>השבירה בדיבור</i> – ראה סי' קמו.\n<i>ויש לו ית' תענוג יותר כו'</i> – ראה סוף סי' שעז. סוף סי' תד. וסי' תכד סד\"ה וז\"ש ויקח.\n<i>והם היו גרים</i> – במדל\"י: התנא הזה (כלומר בן בג בג). ונראה שהנוסחא דידן כאן קאי על בן בג בג ובן הא הא (ראה תוספות חגיגה ט, ב ד\"ה בר הי הי. פירוש התויו\"ט לאבות פ\"ה מכ\"ב)."]]],[400080465,"תא\n\n<b>נשאת</b> ונתת באמונה קבעת עתים לתורה. פי'[ftnref_1_יב], כשנשאת ונתת, באמונה היתה, שהיית מחשב בהשי\"ת בכל עת ובכל רגע, לא הפסקת מחשבותיך ממנו יתברך? ואם תאמר יש יצר הרע, קבעת עתים לתורה, על דרך בראתי יצר הרע בראתי <span data-k=\"sm\">[לו]</span> תורה תבלין. ואם תאמר שהתבלין הם ממתיקין את התבשיל והתבשיל הוא העיקר, והא התורה עיקר.\n<b>אמנם</b> הפי' על דרך שפעם אחת לא היה היצר הרע, אפילו ביעתא בת יומא לא משתכח. כי יש ב' מיני תפילות בהתלהבות, הא' <span data-k=\"sm\">[מה]</span> שאדם עושה לעצמו הכנה, וא' מה שמתפלל בלי שום הכנה רק הזמן הוא גורם. וזהו ביעת\"א, לשון תפיל\"ה, בת יומא, שהזמן גורם, לא אשתכח. כי היצר הרע נקרא כח התאוה והוא החשק, וכמו שאדם רוצה מהפך החשק, אם לטוב מתפלל בחשק ובהתלהבות.\n<b>וזהו</b> פי' סולו לרוכב בערבות בי\"ה שמו. הקב\"ה שורה בערבות, במי שמעורב אצלו אהבה ויראה ביחד. וזהו בי\"ה שמו, כי שם י\"ה מורה על דחילו ורחימו. וזה כאשר מתפלל בהתלהבות. אמנם בלא התלהבות, אע\"פ שמתפלל בכוונה, לא. כי אם היה מתפלל בכוונה[ftnref_2_יג] היה הקב\"ה שורה והיה הרוח מפזר את העננים. רו\"ח נקרא מדת התפארת, שזהו מדת יעקב שבו היו כל המדות אהבה ויראה והתפארות, <span data-k=\"sm\">[כמ\"ש]</span> ויאה\"ב יעקב וגו', מה נורא המקום <span data-k=\"sm\">[הזה]</span>. וזהו אלה\"י אברהם, הכח השורה באהבה, אב\"ר מ\"ה, ששורה הקב\"ה עליו. <i>[חסר כאן]</i>.\n<b>נחזור</b> לראשון, מכל חטאתיכם לפני ה' תטהרו. פי' ע\"ד נודע בשערים בעלה, <span data-k=\"sm\">[ואיתא בזוהר]</span> כל חד כפום שעורין דיליה, על ידי המדות אהבה ויראה הקדוש ברוך הוא מקשר את עצמו כביכול עם האדם[ftnref_3_יד].",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' עט (צ). אוה\"א יב, א.</b>\n<i>נשאת ונתת באמונה כו'</i> – שבת לא, א.<i> בראתי יצה\"ר כו'</i> – קידושין ל, ב.<i> שפעם א' לא היה היצה\"ר כו'</i> – יומא סט, ב.<i> ביעת\"א לשון תפילה</i> – ב\"י טור או\"ח סי' תעג בשם הכל בו (סי' נ), שו\"ע הרב או\"ח סי' תעג סעיף כ. ספר מהרי\"ל, הגדה סעיף ו.<i> סולו לרוכב גו'</i> – תהלים סח, ה.<i> שם י\"ה מורה על דו\"ר</i> – זח\"ג קכג, ב. תקו\"ז ת\"י כה, ב.<i> רו\"ח נקרא מדת התפארת</i> – תקו\"ז תכ\"א מט, ב. תקוזו\"ח צד, ג.<i> התפארת שזהו מדת יעקב</i> – זח\"א קנז, ב. ראה זח\"ב רנו, ב.<i> ויאה\"ב יעקב גו'</i> – ויצא כט, יח.<i> מה נורא גו'</i> – ויצא כח, יז.<i> אלק\"י אברהם</i> – ויצא כח, יג.<i> אברהם . . אב\"ר מ\"ה</i> – לקו\"ת להאריז\"ל פ' לך לך רד\"ה ויאמר ה' אל אברם. ראה זח\"א ג, ב ובמ\"מ שם ד\"ה כד אתא אברהם.<i> מכל חטאתיכם גו'</i> – אחרי טז, ל.<i> נודע בשערים בעלה</i> – משלי לא, כג.<i> כל חד כפום כו'</i> – זח\"א קג רע\"ב. תקו\"ז ת\"ע קלה, ב.\n----- שולי הגליון -----\n[ftn_1_יב]) <i>במדל\"י שנויי נוסחאות מרובים, וז\"ל:</i> פירוש שצריך לישא וליתן, ר\"ל שיהיה כל המעשים והמחשבות באמונה, ר\"ל באחדות הבורא ית'. ואם תאמר יש יצר הרע, לזה אומר קבעת עתים לתורה, על דרך בראתי יצה\"ר בראתי תבלין תורה. והנה יש לדקדק הלא התבלין הם ממתקים את התבשיל והתבשיל הוא העיקר, ובכאן הלא התורה היא העיקר. אך הענין הוא על דרך מה שאמרו רז\"ל אי מסר בידייהו יצרא דעבירה אפילו ביעתא בת יומא לא הוה אשתכח. דהנה יש ב' מיני תפלות בהתלהבות, הא' שהאדם עושה לעצמו הכנה, וב' מה שמתפלל בלי שום הכנה רק הזמן הוא גורם, כמו בשבתות ויו\"ט שאז הוא השראת הקדושה בעולם. וזהו אפילו ביעתא, ר\"ל תפלה, בת יומא, שהזמן גורם, לא אשתכח. כי יצה\"ר נקרא כח התאוה והוא החשק, וכמו שהאדם רוצה כך מהפך החשק, אם לטוב הוא מתפלל בחשק ובהתלהבות.\nוזהו פירוש סולו לרוכב בערבות ביה שמו. ר\"ל הקב\"ה נקרא רוכב בערבות, במי שמעורב אצלו אהבה ויראה יחד הוא שורה עליו. וזהו בי\"ה שמו, כידוע ששם י\"ה מורה אהבה ויראה. וכל זה אם הוא מתפלל בהתלהבות. משא\"כ אם אינו מתפלל בהתלהבות אינו שורה עליו. כי אם היה הקב\"ה שורה עליו היה הרוח מפזר עננים. רוח נקרא מדת תפארת, שהוא מדת יעקב שבו היו כל המדות אהבה ויראה, כמ\"ש ויאהב יעקב כו', מה נורא המקום הזה. וזהו אלהי אברהם, ר\"ל הכח השורה באהבה, אב\"ר מ\"ה, ששורה הקב\"ה עליו (חסר כאן).\nנחזור לענין ראשון, מכל חטאתיכם לפני ה' תטהרו. פי' דהנה כתיב נודע בשערים בעלה, ואיתא בזוהר כל חד לפום שיעורא דיליה, ע\"י המדות אהבה ויראה הקב\"ה מקשר את עצמו כביכול עם האדם.\n[ftn_2_יג]) <i>בהקשר המבואר נראה שצ\"ל</i> בהתלהבות.\n[ftn_3_יד]) <i>במקבילות ממשיך כאן עם המובא לעיל סי' רצו</i>.\n----- הערות וציונים -----\n<i>אמנם הפי' כו'</i> – ראה אורח לחיים פ' בראשית רד\"ה ויאמר ה': הרב בוצינא קדישא מו' דוב בער זללה\"ה אמר פירוש הגמרא קידושין דף למ\"ד בראתי יצר הרע ובראתי לו תורה תבלין והלא אין המשל דומה לנמשל כי בבשר משימין תבלין והעיקר הוא הבשר ולא התבלין וכאן אמר שהתורה הוא התבלין, ואמר שהאמת הוא כן שהיצר הרע הוא העיקר וצריך האדם לעבוד הש\"י בהתלהבות הנמשך מיצה\"ר, ואמר שזהו פי' מה שארז\"ל במס' יומא דף ס\"ט כשמסרו בידם יצרא דעבירה אפילו ביעתא בת יומא לא אשתכח דהנה יש עיתים שהם מוכנים מעצמם לעבודת השי\"ת כגון בשבתות ויו\"ט בלי הכנת אדם וביעתא לשון ביעותא לשון תפלה, ר\"ל כשמסרו בידם יצרא דעבירה לא היה להם התלהבות כלל ואף תפילות שהם בשבתות ויו\"ט שהקדושה באה מלמעלה והם מוכנים מעצמם וזהו ביעותא בת יומא שהיום גרם לא אשתכח מפני שלא היו להם שום התלהבות כלל, ונמצא באמת שהיצא הרע הוא העיקר שיקח התלהבות היצר לעבודת הש\"י והתורה הוא המורה דרך ובאמת כמו תבלין עכ\"ד בקיצור ודפח\"ח.\nובס' זאת זכרון להחוזה בד\"ה עוד פי' פסוק יראו מה' (נז, א): שמעתי מהרב המגיד מראוונא פי' על בקשו ביעתא בת יומא לחולה ולא אשכחו, שגם לתפלה צריך חשקת מצד יצה\"ר כי הזך והברור מתיירא לבד ואינו מתפלל כ\"כ בחשק רב כ\"א בפחד גדול, והנה לתפילה חדשה מתפללים בחשק יותר, וזה בקשו תפלה בת יומא לחולה שנחלה באותו יום ולא אשכחו כי לא היה יצה\"ר בעולם וביעותא לשון תפילה כמו אם תבעיון בעיו.\n<i>וכמו שאדם רוצה מהפך החשק כו'</i> – ראה סי' רמו ובהערות שם.\n<i>על ידי אהו\"י הקב\"ה מקשר כו'</i> – ראה סי' רצט."]]],[400080466,"תב\n\n<b>אמרו</b> רז\"ל בים נדמה להם כבחור ובסיני נדמה להם כזקן. ולכאורה אינו מובן, הא כתיב כי לא ראיתם כל תמונה. ויש לומר על פי משל, האב אוהב את בנו, ומפני גודל האהבה שיש לבנו נחקקה להאב צורת הבן כמו שהוא עומד <span data-k=\"sm\">[לפניו]</span>. וכשהבן עדיין קטן <span data-k=\"sm\">[עדיין]</span> נדמה לאביו במחשבתו צורת קטן, וכשהוא גדול נדמה לו צורת גדול במחשבתו. וזה ידוע כי ישראל עלו במחשבה, פי' שהם תמיד נחקקין במחשבה העליונה כמו שהבן נחקק במחשבת אביו. והנה כשהבן מתכשר במעשיו וטוב בעיני אביו המעשים שלו, כך הוא חקוק במחשבת אביו. וכן ח\"ו להיפוך, החקיקה גם כן כך. וז\"ש אם רחץ ה' את צואת בנות ציון, פי' (כי) [כביכול] השי\"ת רחץ את עצמו מצואת בנות ציון, לפי שהיו חקוקים במחשבתו כביכול. ולטובה נאמר <span data-k=\"sm\">[בישראל]</span> ישא ה' פניו אליך, ר\"ל אותו הפנים שלהם החקוקים במחשבתו. והנה ידוע כי כשיצאו ישראל ממצרים היו כעובר הנשמט מרחם אמו, וכשבאו על הים היו כנער שגמלתו אמו, והיה בהם קצת דיבור, אבל לא בשלימות. וזה סוד שלא היו יכולים לומר שירה מעצמם, אלא מה שאמר להם משה ענו אחריו. וזהו פי' שאמר להם משה ואתם תחרישון, שלא היו עדיין יכולים לדבר בשלימות רק כנער קטן.\n<b>וזהו</b> פי' בים נדמה להם כנער, ר\"ל כאשר היו ישראל בעת ההיא, כך נדמה במחשבה עליונה צורתם גם כן כנער ובחור. וכאשר באו למרה נמתקו שם, וזהו פי' הפסוק כי מרים הם, ר\"ל כי ישראל היו עדיין מרים ונמתקו שם. וכשבאו להר סיני היו משיגים כבר ללמוד ואמרו נעשה ונשמע, ומעצמם היו משיגים כבר חכמה עילאה, והיו אז בסוד זקן, זה קנה חכמה. וזהו ובסיני נדמה להם כזקן, ר\"ל כי צורתם נחקקה במחשבה עליונה בצורת זקן, כדרך הבן שנחקק במחשבת אביו כפי גדולתו ושלימותו. וזהו[ftnref_1_טו] פי' שיחת לו לא בניו, כמו שכתב בזוהר לא עבדין ליה חבילו עבדין לגרמיהון.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' ריח (רכט).</b>\n<i>אמרו רז\"ל בים נדמה כו'</i> – פס\"ר כא, ו. ראה מכדרשב\"י בשלח טו, ג. מכדר\"י פ' בשלח מס' דשירתא פ\"ד. שם יתרו מס' דבחדש פ\"ה.<i> כי לא ראיתם גו'</i> – ואתחנן ד, טו.<i> ישראל עלו במחשבה</i> – זח\"א כד, א. בר\"ר א, ד.<i> אם רחץ ה' גו'</i> – ישעיה ד, ד.<i> ישא ה' גו'</i> – נשא ו, כו.<i> כשיצאו כו' כעובר כו'</i> – יחזקאל טז, ד.<i> שלא היו יכולים לומר כו'</i> – סוטה כז, ב.<i> ואתם תחרישון</i> – בשלח יד, יד.<i> כי מרים הם</i> – בשלח טו, כג.<i> ונמתקו שם</i> – ראה בשלח טו, כה.<i> נעשה ונשמע</i> – משפטים כד, ז.<i> זקן זה קנה חכמה</i> – קידושין לב, ב.<i> שחת לו גו'</i> – האזינו לב, ה.<i> בזוהר לא עבדין כו'</i> – זח\"ג רצז, ב.\n----- שולי הגליון -----\n[ftn_1_טו]) וזהו <i>כו' ליכא במדל\"י</i>.\n----- הערות וציונים -----\nעיין סי' קל ובהערות שם\n<i>על פי משל כו'</i> – ראה סי' סד ד\"ה והנה כשהאב, ובהערות שם."]]],[400080467,"תג\n\n<b>או</b> יאמר, בים נדמה להם כבחור ובסיני נדמה להם כזקן. כי וודאי הוא כמו שנדמה אין הוא כך בעצמותו, אפילו חלק מרבוא. אך כמשל בן הקטן, אביו נהנה מרמיזותיו וקריצותיו. כך הם לא יכלו עדיין לדבר ולא השיגו, וסברו שזהו גבורתו שיכול לקרוע את הים. ובאמת אצלו יתברך לא כלום הוא, שיכול לברוא ולהחריב עד אין סוף. אעפ\"כ היה לו יתברך תענוג כמו מתינוק בחור שאינו מבין שכל גדול של אביו, ויש תענוג לאב ממעשה נערות של הקטן. ולכך נדמה להם כבחור, שסברו שהוא ית' בחור כביכול, שיש לו תענוג ממעשה נערות. ואח\"כ התחילו לדבר, רק בלא דעת, כמו התינוק מה שאומרים לו אומר. כך משה רבינו ע\"ה אמר השירה והם עונים אחריו. ואח\"כ בשעת מתן תורה היה להם שכל כזקן להשיג את השם יתברך, והיה לו תענוג כמו מזקן, ולכך נדמה להם כזקן.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א יג, א.</b>\n<i>בים נדמה להם כו'</i> – פס\"ר כא, ו. ראה מכדרשב\"י בשלח טו, ג. מכדר\"י פ' בשלח מס' דשירתא פ\"ד. שם יתרו מס' דבחדש פ\"ה.<i> משה רבינו ע\"ה אמר כו' והם כו'</i> – סוטה כז, ב.\n----- הערות וציונים -----\nראה סי' קל וסי' תב."]]],[400080468,"תד\n\n<b>מ\"ט</b> שערי בינה נמסרו למשה חוץ מאחד. איתא בזוהר מה שמו של השער הזה אית\"ן. פי' על דרך נודע בשערים בעלה, כל חד כפום שיעורין דיליה. ויש ז' מדות, חצבה עמודיה שבעה, אהבה ויראה והתפארות ונצח והוד ויסוד ומלכות, וכל אחד כלול מכולם. למשל כשאוהב את אחד, שונא את שונאיו, וזהו יראה, ומפאר אותו, ומנצח את שונאיו, ומקושר לו. וסיום הדבר נקרא מלכות, מדריגה התחתונה. ועיקר המדות הם ה', כי התקשרות באה מכח המדות הנזכרים, שמקושר לאהבה וליראה. ואלו החמש הם כלולים מעשר כנזכר, אלו שבע הנזכרים וג' עליונות. למשל אהבת הקב\"ה ממה היא באה, כשאני יודע <span data-k=\"sm\">[שיש בורא]</span> אני אוהב אותו. ומזה אני יודע שאני מבין <span data-k=\"sm\">[נ\"א: וממה אני יודע, דאני מבין בשכלי]</span> שיש בורא יתברך. ומזה אני מבין (שצמצם) [שצמצמתי] את מחשבתי שלא לחשוב בשום דבר אך בזה. וזה המדה נקראת אי\"ן, שדוחה מחשבות אחרות. וזהו מדת החכמה. וכתיב ראשית חכמה, וכשנקרא ראשית עדיין אינו אחדות, שהרי ראשון הוא מלשון מספר, כי אח\"ד הוא לשון אחדות מסתמא יש מדריגה שהוא אי\"ן <span data-k=\"sm\">[נ\"א: כאין נגדו]</span> וכנגדו הוי זה י\"ש. וזהו חמשים שערי בינה, שכולם הם שער לעבודת הקב\"ה. ושער אי\"תן לא נתגלה לו. אי\"תן נקרא מדת אי\"ן, והצירוף הוא אי\"ן ת', <span data-k=\"sm\">[ות']</span> לשון <span data-k=\"sm\">[תענוג לה]</span>. זהו הת\"ענוג לא נתגלה לו, כי הוא היה תמיד דבוק להקב\"ה, והיה הדבר אצלו תמידיות, ולא תענוג מקרי כידוע. אבל יתרו שהיה מקודם כומר לע\"ז, ואח\"כ עבד להקב\"ה והיה בא להתענוג. כמשל בן המלך שהיה בשביה ואח\"כ בא אל המלך, יש להמלך תענוג. ולכן כתיב ביה אי\"תן מושבך. וזהו עתה ידעתי כי גדול ה' מכל אלק\"ים, שהעלה כל המדריגות התחתונות אל הקדוש ברוך הוא. וזהו פירוש המדרש שבע שבתות תמימות, שיהיו <span data-k=\"sm\">[תמימות]</span> בשלימות.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א טז, ב. לקו\"א מו, א.</b>\n<i>מ\"ט שערי בינה כו'</i> – ר\"ה כא, ב.<i> איתא בזוהר מה כו'</i> – זח\"ב קי, ב.<i> נודע בשערים בעלה</i> – משלי לא, כג.<i> כל חד כפום כו'</i> – זח\"א קג רע\"ב. שם קכט, ב. תקו\"ז ת\"ע קלה, ב.<i> ויש ז' מדות חצבה כו'</i> – ראה זח\"א פב סע\"א. זח\"ב רעו, ב.<i> חצבה עמודיה שבעה</i> – משלי ט, א.<i> וכל אחד כלול מכולם</i> – תקו\"ז תי\"ז לא סע\"א. תמ\"ז פד, א. שם תס\"ט קטז, ב. פרדס רמונים ש\"ח פ\"ב.<i> אי\"ן . . וזהו מדת החכמה</i> – תקו\"ז תמ\"ב פא, ב. שם ת\"ע קכז סע\"א. וקלג רע\"ב.<i> ראשית חכמה</i> – תהלים קיא, י.<i> יתרו שהיה מקודם כו'</i> – שמ\"ר א, לב.<i> אי\"תן מושבך</i> – בלק כד, כא. ראה שמ\"ר כז, ג.<i> עתה ידעתי כי גו'</i> – יתרו יח, יא.<i> שבע שבתות תמימות</i> – אמר כג, טו.<i> שיהיו בשלימות</i> – תו\"כ אמר פי\"ב ה\"ו. מנחות סו, א. ראה זח\"ג רנה, א. של\"ה מס' פסחים ר\"פ תורה אור.\n----- הערות וציונים -----\n<i>וכשנקרא ראשית כו' מלשון מספר כו'</i> – ראה סי' כז ובהערות שם.\n<i>תמידיות ולא תענוג מקרי כידוע</i> – ראה ריש סי' לה ובהערות שם.\n<i>אבל יתרו כו'</i> – ראה ריש סי' קצב."]]],[400080469,"תה\n\n<b>גדול</b> הנהנה מיגיע כפו יותר מיראת שמים. כי יש פעם שצדיק עובד את הקב\"ה מביא תענוג גדול בעולם. כי מה שמעורר בעצמו, כביכול מתעורר בהקב\"ה, אם אהבה, נגלה בהקב\"ה ג\"כ אהבה. כמשל האב אינו מגלה מדות שלו, אלא כי אם כשבא אצלו בן החביב אזי מראה אהבתו. אזי כל העולמות מתענגים. נמצא זה, שעושה התענוג הזה, <span data-k=\"sm\">[נקרא]</span> יגיע כפיו, <span data-k=\"sm\">[והוא]</span> יותר מיראת שמים. כי הנה בָּנוּ יש אהבה ויראה והתפארות על הקב\"ה, ובהקב\"ה כביכול יש גם כן אהבה שאוהב אותנו, ויראה שלא נפרד ממנו, כאב שירא שלא ילך הבן ממנו, והתפארות שמפאר אותנו. וזהו יותר מיראת שמים, מן המורא שהקב\"ה ירא ומעורר אותו שלא יחטא, כמו בנח את האלקי\"ם התהלך. אבל אברהם אשר התהלכתי לפניו, ומעורר בעצמו יראה, <span data-k=\"sm\">[אזי]</span> כביכול מעורר בהקב\"ה יראה, כמשל האב שהבן אינו רוצה להפרד ממנו, וירא שלא יפרד האב ממנו, האב גם כן ירא שלא יפרד ממנו.\n<b>וזהו</b> פירוש הבן יקיר לי, כשהבן יקיר לי שעושה הכל לשמי, אפרי\"ם, שמפרה <span data-k=\"sm\">[ומרבה]</span> מדותיו <span data-k=\"sm\">[נ\"א: בי' מדות]</span> כביכול, אם ילד שעשועים, שאפילו כשהוא בשכל דילדות אני משתעשע בו, כי מדי דברי בו, בהשכינה, <span data-k=\"sm\">[נ\"א: בו, פי' שהשכינה שורה בו, אמנם]</span> אנו בכל מעשינו מעוררים את השכינה, והשכינה את עולם האופנים, ואופנים את עולם הכסא, ועולם הכסא את הקב\"ה. לכך הצדיק שעובד את הקב\"ה מאהבה, מביא (את) [התגלות] הקב\"ה בעולם האהבה. ובעולם האהבה יש אלף אלפים ורבוא רבבות עולמות, וכולם מתעוררים ועובדים את השי\"ת אפילו בלי הכנה. וזהו עולם האהבה אינו מתעורר, ופעמים שהצדיק (אינו) מעורר אותו. אך כשהוא מדובק בקליפה, ואין בו אלו <span data-k=\"sm\">[נ\"א: אינו בא ל-]</span> התעוררות. ולכך יאחז במדת יראה כדי לפרוד מן הקליפה, ואז יעבוד את השי\"ת בשלימות.",[["","","----- מקורות ומראה מקומות -----\n<b>אוה\"א טז, ב. לקו\"א מו סע\"ב.</b>\n<i>גדול הנהנה כו'</i> – ברכות ח, א.<i> מה שמעורר כו' מתעורר כו'</i> – ראה זח\"א קכה, ב. שם רמד, א. זח\"ב קפד, ב.<i> את האלקי\"ם התהלך</i> – נח ו, ט.<i> אשר התהלכתי לפניו</i> – חיי שרה כד, מ.<i> הבן יקיר לי גו' אם ילד גו' מדי גו'</i> – ירמיה לא, יט.<i> אפרי\"ם שמפרה</i> – ע\"פ מקץ מא, נב.<i> מעוררים את השכינה והשכינה כו'</i> – ראה זח\"א רמד, א.\n----- הערות וציונים -----\n<i>מה שמעורר בעצמו כ\"י מתעורר בהקב\"ה כו'</i> – עיין סי' קלד ד\"ה וזהו על דמות הכסא, ובהערות שם. וסי' ש.\n<i>שאפילו הוא בשכל דילדות אני משתעשע בו</i> – להעיר מסי' קמ ד\"ה משל לאב. סי' רלו. וסי' רמח ד\"ה והנה נאמר."]]],[400080470,"תו\n\n<b>האומר</b> איני עובר לפני התיבה בצבועים אף בלבנים לא יעבור. כי למה נפלה מחשבה זרה לאדם, יבואר על דרך וכל אשה יודעת איש למשכב זכר הרוגו. נשי מדי\"ן נקרא גם כן בנו, כי התורה היא תמידית בכל דור דור, וכהיום יש נשי מדין גם כן. <span data-k=\"sm\">[כי]</span> נש\"י לשון שכחה, מדי\"ן לשון די\"ן. כי כשמתחיל להתפלל, מיד כשאומר אדנ\"י שפתי תפתח השכינה מתלבשת בו ומדברת בו הדברים האלו. וכשיהיה לו האמונה שהשכינה מדברת זאת, <span data-k=\"sm\">[בודאי]</span> יפול עליו <span data-k=\"sm\">[אימה ו]</span>יראה, וגם הקב\"ה <span data-k=\"sm\">[כביכול]</span> מצמצם את עצמו ושורה אצלו, כמ\"ש מציץ מן החרכים. והאותיות הם היכלות, והוא הולך מהיכל להיכל, ובכל היכל דנים אותו אם <span data-k=\"sm\">[הוא]</span> ראוי לכנס. ואם היה אדם משים על לב שדנים אותו בעת שנפלה לו מחשבה זרה, בוודאי היה מתפלל בכוונה, רק שהוא שוכח שדנים אותו. והקליפה נקראת אשה <span data-k=\"sm\">[נ\"א: נוקבא]</span>, שהיא מצפה לקבל חיותה מן האדם בעשיות עבירות ח\"ו, כמו <span data-k=\"sm\">[אשה]</span> שהיא מקבלת. והקדושה נקראת גם כן אשה יראת ה', שהיא מקבלת תענוג בעשיית המצוה של האדם. אך כי בקדושה יש ג\"כ זכר, שהשי\"ת שופע <span data-k=\"sm\">[שפע]</span> בהאדם כדי שיעשה המצוה, אבל הקליפה היא רק מקבלת. וזהו וכל אשה, מי שהוא רק אשה, יודעת איש, שמתחברת להקדושה. והקליפה היא המביאה את המחשבה זרה.\n<b>וכשנופלת</b> לו המחשבה זרה ראוי להוריק פניו מחמת בושה, שהשכינה כנגדו. ואילו היה <span data-k=\"sm\">[עומד]</span> לפני מלך בשר ודם היה מדבר בבושה ולדבר כענין, והקב\"ה מביט אל המחשבה והוא אינו חושב (הענין) [כענין]. ובזה הוא מעלה את המחשבה זרה. והמחשבה זרה באה מכח עבירה שעשה ביום, באה לו זו בתפילתו <span data-k=\"sm\">[להזכיר אותו]</span> להעלותה להקב\"ה. וזהו העבירם לפני הציץ, לפני (הבטחה לפני) [הבטתו של] הקב\"ה מלשון מציץ מן החרכים. וזהו סימן לעבירה הדרוקן. אם עשה עבירה ביום, נתגלה לו בשעת תפילתו מחשבה זרה כדי שיבוש <span data-k=\"sm\">[ויכלם]</span>, ויעלה את העבירה או ההרהור שהירהר דבר שטות.\n<b>וזהו</b> האומר איני עובר לפני התיבה, שאינו רוצה להתפלל, שהמתפלל נקרא עובר לפני התיבה שהוא עולה ומעלה עמו את הדיבור, בצבועים, מפני המחשבה זרה הנקרא צבועים מפני שהוא מהמדות שנפלו בשבירה. והמדות נקראים צבועים <span data-k=\"sm\">[שהם גוונים]</span> כידוע. א\"ף, העבירות נקראים א\"ף של הקב\"ה, בלבני\"ם, בבהירות של הקב\"ה לא יעבור, לא יהיה עליו לעבירה <span data-k=\"sm\">[נ\"א: עבירה]</span>[ftnref_1_טז].",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' ד (ג). אוה\"א יט, א. </b><i>[מיד כשאומר . . ושורה אצלו: </i><b>שמועה טובה סב, א].</b>\n<i>האומר איני עובר כו'</i> – מגילה כד, ב.<i> וכל אשה יודעת גו'</i> – מטות לא, יז.<i> נש\"י לשון שכחה</i> – ע\"פ מקץ מא, נא.<i> מדי\"ן לשון די\"ן</i> – ראה זח\"ב סח, א ובאוה\"ח שם.<i> אד' שפתי תפתח</i> – ריש העמידה (תהלים נא, יז).<i> מציץ מן החרכים</i> – שה\"ש ב, ט.<i> ובכל היכל דנים אותו</i> – זח\"ב רמה, ב.<i> נוקבא . . לקבל</i> – תקו\"ז תנ\"ה פט, א.<i> אשה יראת ה'</i> – משלי לא, ל.<i> זכר . . שופע</i> ראה זח\"א רלב, א. זח\"ב ד, ב. שם רמד, א.<i> ראוי להוריק</i> – ע\"פ יבמות ס, ב.<i> העבירם לפני הציץ</i> – שם.<i> סימן לעבירה הדרוקן</i> – שם. שבת לג, א.<i> והמדות נקראים צבועים</i> – תקו\"ז י, ב. שם תנ\"ו צא רע\"א. וראה שם א, א (בנ\"א).\n----- שולי הגליון -----\n[ftn_1_טז]) <i>במדל\"י הוסיף כאן:</i> (אינו מובן קצת).\n----- הערות וציונים -----\n<i>התורה היא תמידית בכל דור ודור</i> – ראה ריש סי' לח ובהערות שם.\n<i>בודאי יפול עליו אימה ויראה</i> – ראה סי' ת ד\"ה בן בג בג, ובהערות שם.\n<i>והאותיות הם היכלות והוא הולך כו'</i> – ראה סי' נ ד\"ה וזהו פי' וימלוך.\n<i>והקליפה נקראת כו' והקדושה נקראת כו'</i> – ראה סי' שדמ.\n<i>אך כי בקדושה יש כו' אבל הקליפה כו'</i> – שם."]]],[400080471,"תז\n\n<b>העושה</b> תפילתו עגולה סכנה ואינה מצוה. תפילתו, פי' התדבקותו בהקב\"ה, עגולה, <span data-k=\"sm\">[פי']</span> פעמים שהוא דבוק בהקב\"ה ופעמים אינו כמו גלגל שמתגלגל. סכנה ואינה מצוה, מצו\"ה הוא לשון התחברות כמו צוו\"תא, ורצה לומר מסתמא אינו מקושר בהקב\"ה[ftnref_1_יז].",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סי' ה (ד). אוה\"א יט, ב.</b>\n<i>העושה תפילתו עגולה כו'</i> – מגילה כד, ב.<i> תפילתו פי' התדבקותו</i> – ראה ת\"א ופרש\"י ויצא ל, ח. תקו\"ז תמ\"ז פד, ב.<i> מצו\"ה כו' צוו\"תא</i> – של\"ה, בעשרה מאמרות מאמר ג-ד (נא, ב). שם מס' יומא פרק ד\"ח תוכחת מוסר (רלז, ב). אוה\"ח תצוה כז, כ ושם פנחס כז, כג.\n----- שולי הגליון -----\n[ftn_1_יז]) <i>נ\"א, ובאריכות, לקמן סי' תעט</i>.\n----- הערות וציונים -----\nראה לקמן סי' תעט.\n<i>תפילתו פי' התדבקותו</i> – כמו תפלה, כמבואר בזה בסי' רנה ד\"ה ולזה, ובהערות שם."]]],[400080472,"תח\n\n<b>ציפן</b> זהב ונתנן על בית אונקלי שלו, פירוש על בית יד מבחוץ. פירוש שמחזיק לומדי תורה, אך מבחוץ, שהכל רואים ויש לו התפארות בזה, הרי (מדה החיצונית) [מדת החיצונים], פירש\"י בני אדם ההולכים אחר דעתם חוץ (ממדת) [מדעת] חכמים.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל\"י סוף סי' ה (ה). אוה\"א יט, ב.</b>\n<i>ציפן זהב [ה\"ז דרך החיצונים]</i> – מגילה כד, ב.<i> פירש\"י</i> – שם."]]],[400080473,"תט\n\n<b>כל</b> האומר ויכולו בשבת כאילו נעשה שותף להקב\"ה במעשה בראשית. ע\"ד מה היה העולם חסר, מנוחה, באה שבת באה מנוחה. וגם ויכל אלקי\"ם ביום השביעי.\n<b>כי</b> כלל גדול הוא, אם רואה אדם דבר ציור ובנין, ואחר הראות הזה נשאר הרשימו חקוק בלבו וכל הבנין. וזהו נקרא רשימו בכל מקום. ובחינת הרשימו נקרא מלכות, נוקבא, לגבי בנין ממש. ובוודאי כאן ברשימו יש כח הדבר גם כן, כי כח הפועל בנפעל, וכן להיפוך. וזה פירוש אדם וחוה דו פרצופים נבראו. כי באמת בשעה שרואה הדבר בעצמו אינו ניכר הנוקבא כלל, אך אחר שילך מזה המקום נשאר רק הרשימו בעצמה, ואח\"כ, אפילו כשרואה עוד, אעפי\"כ נשאר וניכר הרשימו לבחינה מיוחדת. וזהו ויפל ה' אלקים תרדימה על האדם, דהיינו שנסתלק (נ\"א שנחלק) הזכר וניכר הנוקבא, דהיינו הרשימו, פרצוף בעצמו.\n<b>וז\"ס</b> אסורה נא ואראה את המראה וגו'. כי משה ראה את הנוקבא, והבין שזה הדמיון מאספקלריא המאירה, דהיינו כנזכר, ועיקר הראות הוא המראה הגדול הזה. אמר אסור\"ה נא, להסיר עצמו מזה המראה שהוא הרשימו, לבוא לבחינת דכר. וזה הראה לו בנבואה ראשונה, וזכה מזה לאספקלריא המאירה. וזהו וראה ועשה בתבניתם אשר אתה מראה בהר. כי משה ראה בהר החיות והרוחניות מהמשכן עם כל פרטיותיו, וכשראה נשאר הרשימו אצלו. וכשעשה המשכן בזה הרשימו היה כח הפועל בנפעל, וישרה הרשימו עם הבחינה ראשונה על המשכן. כי ברשימו כלול הדבר גם כן כנזכר.\n<b>והנה</b> כשעלה ברצון המאציל אין סוף ב\"ה לברוא את העולם נצטייר כל בנין העולם, וזהו סוף מעשה במחשבה תחילה. וזהו החיות של העולם, כי כח הפועל בנפעל. עד\"מ כמו שהאומן מצייר תחילה כל הבנין ואח\"כ עושה אותו, ובזה נותן חיות אל הבנין שיהיה קיים. אך הבנין שבציור נקרא מנוחה, שלא היה במעשה ומלאכה, ונקרא עולם התענוג, ובינ\"ה ציירה ציורין כנודע. וזהו החיות של העולם. וכשלא היה העולם בשלימות לא היה החיות שורה עליו, והשלום לא שריא אלא באתר שלים. וזהו מה היה העולם חסר, מנוחה, באה שבת באה מנוחה, ונתן כח הפועל בנפעל, באה מנוחה שהיא שביתה, והיה (שלום) [שלים] באה מנוחה. וזהו ויכל אלקים ביום השביעי וגו'.",[["","","----- מקורות ומראה מקומות -----\n<i>כל האומר ויכלו כו'</i> – שבת קיט, ב.<i> מה היה העולם חסר כו'</i> – פרש\"י בראשית ב, א. פרש\"י מגילה ט, א. ד\"ה ויכל בשם מדרש חכמים.<i> ויכל אלקים גו'</i> – בראשית ב, ב.<i> אדם וחוה דו פרצופים נבראו</i> – ברכות סא, א.<i> ויפל ה' גו'</i> – בראשית ב, כא.<i> אסורה נא גו'</i> – שמות ג, ג.<i> וזכה מזה לאספקלריא המאירה</i> – יבמות מט, ב.<i> וראה ועשה גו'</i> – תרומה כה, מ.<i> סוף מעשה כו'</i> – פזמון לכה דודי. ראה זח\"ג רלח סע\"א. תקו\"ז ו, א.<i> ובינ\"ה ציירה ציורין</i> – ראה זח\"א ב רע\"א. זח\"ב כב, א. ס' הבהיר סי' קמג ובאור הגנוז שם.\n----- הערות וציונים -----\nכבר הובא לעיל סי' יא-א."]]],[400080474,"תי\n\n<b>סייג</b> לחכמה שתיקה. כי כשהוא בשתיקה יכול הוא לדבק את עצמו בעולם המחשבה שהוא חכמה.\n<b>ועיקר</b> הדביקות יכול להשיג כשיתחזק א\"ע תמיד לעלות לעולמות עליונים, ויפרוש מחשבתו מאלו השפלים. ואם ראה שיש מחיצות מבדילות, יסגף את עצמו. אבל העיקר היא המחשבה, יחזיק תמיד לעלות למעלה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י טו, ג (סי' קצ-קצא). אוה\"א פב, א.</b>\n<i>סייג לחכמה שתיקה</i> – אבות פ\"ג מי\"ג.<i> המחשבה שהוא חכמה</i> – זח\"ב כ, א. תקו\"ז יז, א.<i> ואם ראה כו' יסגף את עצמו</i> – ראה זח\"ג קסח, א.\n----- הערות וציונים -----\n<i>כשהוא בשתיקה יכול כו'</i> – ראה צוה\"ר סי' קלג ובהערות שם.\n<i>ואם ראה כו' יסגף את עצמו</i> – להעיר מזח\"ג קסח, א אעא דלא סליק ביה כו' (וראה תניא רפכ\"ט ושם פ' מב).\n<i>כי אדם החכם יכול כו'</i> – ראה סי' תל.\n<i>ולא יסתכל חוץ לד' אמות לראות תמיד בשם בן ד' כו'</i> – ראה ר\"ח שער הקדושה פ\"ח טעם שלא להסתכל חוץ לד\"א כו' עיי\"ש. ועיין לעיל סי' רו ובהערות שם. ולקו\"י סי' נב.\n<i>עיקר כל דבר שבעולם הוא הרוחניות שבו כו'</i> – ראה סי' תיג. וראה סי' רלג ובהערות שם.\n<i>וכן בדיבור כנזכר יכול כו'</i> – עיין סי' סב ד\"ה והנה, ובהערות שם. וראה לקמן סי' תל. וכש\"ט סי' קג ובהערות שם. רג\"כ שם סי' שסו."]]],[400080475,"(תיא)\n\n<b>ואמרו</b> רז\"ל אור זו מעשיהם של צדיקים וכו'. פירוש, כי אדם החכם יכול לאכול דברים טובים ושארי תענוגים, ומכל מקום יכול הוא לסגף את עצמו בהם. וכן לראות בכל מקום שירצה, ולא יסתכל חוץ לד' אמות, לראות תמיד בשם בן ד' שיש באותו דבר, בסוד שויתי ה' לנגדי תמיד, וכמ\"ש רז\"ל אל תסתכל בקנקן אלא במה שיש בו. כי עיקר כל דבר שבעולם הוא הרוחניות שבו הבא מהשם יתברך שנותן בו טעם ומקיימו. וכן בדיבור כנזכר, [יכול לדבר אפילו דברים בטלים באיזה פעם ולהיות דבוק בהשי\"ת][ftnref_1_יח].",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י טו, ג (סי' קצב). אוה\"א פב, א.</b>\n<i>ואמרו רז\"ל אור זו כו'</i> – בר\"ר ב, ה.<i> שויתי ה' גו'</i> – תהלים טז, ח.<i> אל תסתכל בקנקנן כו'</i> – אבות פ\"ד מ\"כ.\n----- שולי הגליון -----\n[ftn_1_יח]) <i>במקבילות המשך:</i> וכן בתפלה, יכול לעבוד עבודת התפלה להשי\"ת שלא יהיה עבודתו נראה בפני בני אדם כלל, שלא יעשה שום תנועה באיברים, רק בפנימיות בנשמתו יהיה בוער בלבו ויצעוק בלחש, מחמת התלהבות, בענין שתהא עבודתו בפנים יותר גדולה משתהא עבודתו נראית באיברים.\n----- הערות וציונים -----\nראה הערות וציונים לעיל סימן תיא."]]],[400080476,"תיב\n\n<b>וחיי</b> צער תחיה. ר\"ל אל תקרי תִּחְיה אלא תְחַיה. פירוש, בכל דבר יראה שיכוון להחיות הניצוצין שהם נתונים בתוך הקליפות שנפלו שם, והם בצער גדול שם, תראה להחיות\"ם ולהוציאם ולהעלותם.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י טו, ב (סי' קעו). אוה\"א קז, א.</b>\n<i>וחיי צער תחיה</i> – אבות פ\"ו מ\"ד.\n----- הערות וציונים -----\nראה סי' קעח. וראה סי' תיג ובהערות שם."]]],[400080477,"תיג\n\n<b>התורה</b> חסה על ממונם של ישראל. ולמה כך, כי זה כלל גדול שכל דבר שאדם לובש או אוכל או משתמש בכלי, הוא נהנה מהחיות שיש באותו דבר. כי לולי אותו הרוחניות לא היה שום קיום לאותו דבר, ויש שם ניצוצות קדושות השייכים לשורש נשמתו. ([ftnref_1_יט]ושמעתי כי זהו הטעם שיש אדם שאוהב דבר זה, ויש אדם ששונא דבר זה ואוהב דבר אחר.) וכשהוא משתמש באותו הכלי, או אוכל מאכל אפילו לצורך גופו, הוא מתקן הניצוצין. כי אח\"כ עובד בכח הזה שבא לגופו מאותו מלבוש או מאכל או שאר דברים, ובזה הכח עובד להשי\"ת, נמצאו מתוקנים.\n<b>ולכך</b> פעמים שיאבד הדבר ההוא ממנו. שכבר כלה לתקן כל הניצוצין שהיו באותו הדבר השייכין לשורש נשמתו, אז לוקח ממנו השי\"ת אותו הכלי ונותן לאחר ששייכין הניצוצות שיש באותו הכלי לשורש [של] אחר [שהוא משורש נשמתו].\n<b>ואמר</b> <i>ר' ישראל ב\"ש זלה\"ה</i>, שאוכלים בני אדם ויושבין על בני אדם ומשתמשין בבני אדם, היינו בניצוצין שיש באותן הדברים.\n<b>לכך</b> צריך אדם לחוס על כליו ועל כל דבר שיש לו, דהיינו מצד הניצוצין שיש שם [נ\"א: שיש בכלי זה], בכדי לחוס על הניצוצין הקדושות.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י טו, ב (סי' קעז). אוה\"א פב, ב. צוה\"ר סי' קט.</b>\n<i>התורה חסה כו'</i> – יומא לט, א.<i> לולי אותו הרוחניות כו'</i> – ראה פרדס רמונים ש\"ד ספ\"י. שם ש\"ו פ\"ח.<i> ויש שם ניצוצות כו'</i> – ראה ע\"ח שכ\"ו פ\"א. שם ש\"נ פ\"ג, שער המצות פ' עקב.\n----- שולי הגליון -----\n[ftn_1_יט]) <i>הבא כאן בסוגריים ליכא בלקו\"י (וגם לא בכש\"ט). ובצוה\"ר ואוה\"א בלי סוגריים</i>.\n----- הערות וציונים -----\nעיין סי' נא וסי' קעח ובהערות שם. ועיין כש\"ט סי' נג וקצד, וצוה\"ר סי' קט, ובהערות שם.\n<i>לולי אותו הרוחניות לא היה כו'</i> – ראה סי' רלג וסי' תיא, ובהערות שם.\n<i>ויש שם ניצוצות קדושות השייכים לשורש נשמתו כו'</i> – ראה שמועה טובה סב, ב פירוש הבעש\"ט עה\"פ רעבים גם צמאים (והובא ג\"כ בכש\"ט סוף סי' קצד, והוא מפירושו להודו). ועיין ע\"ח שכ\"ו פ\"א. ושם ש\"נ פ\"ג."]]],[400080478,"תיד\n\n<b>חלצה</b> במנעל שאין לו עקב חליצתה פסולה. פירוש ע\"ד עקב ענוה יראת ה', שיראת ה' [הוא] עקב לענוה [והגוף נקרא נעל]. וזהו פירוש חלצ\"ה, לשון ה\"חלצו מאתכם אנשים. אם הוא עומד להתפלל במנע\"ל – הגוף נקרא מנעל – שאין לו עקב, בלי יראה, כלומר התפילה היא בלא עקב שהוא יראה, חליצתו פסולה, ר\"ל תפילתו פסולה.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו\"י לב, ב (סי' רסב). אוה\"א מא, ב.</b>\n<i>חלצה (במנעל) [בסנדל] כו'</i> – יבמות קא, א.<i> עקב ענוה גו'</i> – משלי כב, ד.<i> ה\"חלצו מאתכם אנשים</i> – מטות לא, ג.<i> הגוף נקרא מנעל</i> – תקו\"ז תל\"א עו, א. שם תי\"ב כז, א. ושם תכ\"ב מח, ב.\n----- הערות וציונים -----\n<i>שיראת ה' הוא עקב לענוה</i> – ראה סי' שנד.\n<i>עומד להתפלל . . בלי יראה כו' תפילתו פסולה</i> – השוה סי' שעד."]]]]});
